insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Gap chegaralari va tinish belgilari (Boundaries)', 'Mustaqil gaplarni qanday ulash, nuqta, vergul, nuqtali vergul, ikki nuqta va tire qachon kerakligi, qo‘shimcha (nonessential) qismlarni ajratish — Standard English Conventions savollarining tinish belgilariga oid qismi uchun ixcham qoidalar kitobi.', '[{"type":"concept","heading":"Qoidalar kitobi (1-qism): gaplarni ulash","body":"Boundaries savollari bitta narsani tekshiradi: gap qismlari tutashgan joyda **qaysi tinish belgisi** kerak (yoki umuman belgi kerak emas). Barcha qoidalar bitta tushunchaga tayanadi:\n\n**Mustaqil gap (independent clause)** — egasi va kesimi bor, yolg‘iz o‘zi to‘liq gap bo‘la oladi: *The museum reopened.* **Ergash gap (dependent clause)** — *because, although, when, which, who* kabi so‘z bilan boshlanadi va yolg‘iz tura olmaydi: *because the roof was repaired.*\n\n**1-qoida. Ikki mustaqil gapni ulashning to‘g‘ri usullari:**\n\n- nuqta: *The rain stopped. The match resumed.*\n- nuqtali vergul: *The rain stopped; the match resumed.*\n- vergul + teng bog‘lovchi (FANBOYS: *for, and, nor, but, or, yet, so*): *The rain stopped, so the match resumed.*\n- ikki nuqta yoki tire — ikkinchi gap birinchisini izohlasa: *The match resumed for one reason: the rain had stopped.*\n\nNoto‘g‘ri: **comma splice** — faqat vergul bilan ulash (*The rain stopped, the match resumed.*) va **run-on** — hech qanday belgisiz ulash (*The rain stopped the match resumed.*).\n\n**2-qoida. However, therefore kabi so‘zlar bog‘lovchi emas.** *However, therefore, moreover, consequently, for example, in fact* ikki mustaqil gap orasida kelsa, ulardan oldin nuqta yoki nuqtali vergul, keyin esa vergul qo‘yiladi: *The rain stopped; however, the field was still wet.* Faqat vergullar bilan (*The rain stopped, however, the field was still wet.*) — bu comma splice.\n\n**3-qoida. Nuqtali vergul — nuqta kuchida.** Uning ikki tomonida ham mustaqil gap bo‘lishi shart: ✗ *Although the rain stopped; the field was wet.* (Yagona istisno: elementlari ichida vergul bor murakkab ro‘yxat.)\n\n**4-qoida. Ikki nuqtadan (colon) oldin to‘liq gap turishi shart**, undan keyin esa izoh, ro‘yxat yoki misol keladi: ✓ *She packed three tools: a compass, a map, and a flashlight.* ✗ *She packed: a compass, a map, and a flashlight.* ✗ *She packed tools such as: a compass and a map.*\n\n**5-qoida. Qo‘shimcha (nonessential) ma’lumot juft belgi bilan ajratiladi:** ikki vergul, ikki tire yoki qavs — lekin aralashtirmasdan. ✓ *The bridge, which opened in 1932, is still in use.* ✓ *The bridge—completed in 1932—is still in use.* ✗ *The bridge, completed in 1932—is still in use.* Tekshiruv: ajratilgan qismni olib tashlang — qolgan gap to‘liq va to‘g‘ri bo‘lishi kerak."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["Savol so‘zi deyarli har doim bir xil: *“Which choice completes the text so that it conforms to the conventions of Standard English?”*","**Variantlardagi so‘zlar bir xil, faqat tinish belgilari farq qiladi** — masalan, *tank, however,* / *tank; however,* / *tank however*. Bu Boundaries savoli. Agar so‘zning shakli o‘zgarsa (*is / are*, *its / their*), bu Form, Structure, and Sense savoli.","Bo‘sh joy ko‘pincha gap qismlari **tutashgan joyda** turadi: ikki mustaqil gap orasida, ism yoki unvon yonida, uzun ega bilan kesim orasida yoki *however, therefore* kabi so‘z yonida.","Bo‘sh joydan oldin vergul yoki tire bilan boshlangan qo‘shimcha qism bo‘lsa — bu juft belgini yopish haqidagi savol bo‘lishi ehtimoli katta."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Butun gapni o‘qing**, faqat bo‘sh joy atrofini emas. Ba’zan kerakli ishora (ochilgan vergul yoki tire) gap boshida bo‘ladi.","**Bo‘sh joydan chapdagi va o‘ngdagi qismni tekshiring:** har biri yolg‘iz o‘zi to‘liq gap (mustaqil gap) bo‘la oladimi?","**Ikkalasi ham mustaqil bo‘lsa** — nuqta, nuqtali vergul, vergul + FANBOYS yoki (ikkinchi qism izoh bo‘lsa) ikki nuqta kerak. Faqat vergul qo‘yilgan yoki belgisiz variantlarni darhol o‘chiring.","**Bittasi mustaqil bo‘lmasa** — nuqtali vergul va nuqta mumkin emas. Vergul kerakmi yoki umuman belgi kerak emasmi — buni 5–11-qoidalar bo‘yicha aniqlang.","**Juftlikni tekshiring:** gapda qo‘shimcha qism vergul (yoki tire) bilan ochilgan bo‘lsa, u aynan shu belgi bilan yopilishi kerak.","**Bir xil vazifadagi variantlarni o‘chiring.** Ikki variant grammatik jihatdan bir xil ishlasa (masalan, ikki mustaqil gap orasida nuqta va nuqtali vergul), to‘g‘ri javob faqat bitta bo‘lgani uchun ikkalasi ham javob emas.","**Tanlagan variantingiz bilan gapni boshidan oxirigacha bir marta o‘qing** — u to‘liq va mantiqli bo‘lishi kerak."]},{"type":"example","heading":"Namuna 1: ikki mustaqil gap va however","example":{"problem":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Marine biologist Lena Ortiz expected the coral fragments in her experiment to grow fastest in the warmest ______ the fragments kept in the coolest tank grew nearly twice as quickly.","choices":["tank, however,","tank however","tank; however,","tank, however;"],"solution":["Bo‘sh joyning ikki tomonini tekshiramiz. Chap tomon: *Marine biologist Lena Ortiz expected the coral fragments… to grow fastest in the warmest tank* — mustaqil gap. O‘ng tomon: *the fragments kept in the coolest tank grew nearly twice as quickly* — bu ham mustaqil gap.","Demak, ikki mustaqil gapni ulash kerak. *However* bog‘lovchi emas, shuning uchun undan oldin nuqtali vergul, keyin vergul qo‘yiladi: *tank; however, the fragments…* — **C**.","**A** (*tank, however,*) — ikki mustaqil gap faqat vergullar bilan ulangan: bu comma splice.","**B** (*tank however*) — hech qanday belgi yo‘q: run-on gap.","**D** (*tank, however;*) — nuqtali vergul *however* dan keyin kelgani uchun bu so‘z birinchi gapga yopishib qoladi. Lekin zidlik ikkinchi gapda (kutilgan natijaga qarshi natija), shuning uchun *however* ikkinchi gapni boshlashi kerak."],"answer":"C) tank; however,"}},{"type":"example","heading":"Namuna 2: qo‘shimcha qismni yopish","example":{"problem":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Ceramic artist Malika Yusupova, whose blue glazes are made with ash from plants that grow near her ______ sells her bowls at a weekly market in Rishton.","choices":["home—","home;","home","home,"],"solution":["Gapning egasi *Ceramic artist Malika Yusupova*, kesimi *sells*. Ular orasida vergul bilan **ochilgan** qo‘shimcha qism bor: *whose blue glazes are made with ash from plants that grow near her home*.","Qo‘shimcha qism qaysi belgi bilan ochilgan bo‘lsa, shu belgi bilan yopiladi. Ochilish — vergul, demak yopilish ham vergul: *home, sells* — **D**. Tekshiruv: qo‘shimcha qismni olib tashlasak, *Ceramic artist Malika Yusupova sells her bowls…* — to‘liq gap ✓.","**A** (*home—*) — vergul bilan ochilib, tire bilan yopilgan: juftlik buzilgan.","**B** (*home;*) — nuqtali vergul ikki tomonda mustaqil gap talab qiladi, bu yerda esa u ega bilan kesimni ajratib qo‘ygan.","**C** (*home*) — qo‘shimcha qism yopilmagan; gap go‘yo *her home sells her bowls* (“uyi kosalarini sotadi”) degandek o‘qiladi."],"answer":"D) home,"}},{"type":"example","heading":"Namuna 3: uzun ega va kesim","example":{"problem":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The hundreds of small sensors attached to the bridge''s steel ______ data about vibrations to a central computer every second, allowing engineers to spot problems early.","choices":["cables send","cables, send","cables; send","cables: send"],"solution":["Ega — *The hundreds of small sensors attached to the bridge''s steel cables* (uzun, lekin bitta ega), kesim — *send*.","Ega va kesim orasiga hech qanday tinish belgisi qo‘yilmaydi (6-qoida), ega qanchalik uzun bo‘lmasin. To‘g‘ri javob — **A**: *cables send*.","**B** (*cables, send*) — ega va kesim orasida ortiqcha vergul. O‘qiganda “pauza” sezilsa ham, vergul pauza uchun emas, grammatika uchun qo‘yiladi.","**C** (*cables; send*) — nuqtali vergul ikki tomonda mustaqil gap talab qiladi; chap tomonda kesim yo‘q.","**D** (*cables: send*) — ikki nuqtadan oldin to‘liq gap bo‘lishi kerak; bu yerda u ega bilan kesimni ajratib qo‘ygan."],"answer":"A) cables send"}},{"type":"watch_out","heading":"Qoidalar kitobi (2-qism): nimaga e’tibor berish kerak","items":["**6-qoida. Ega va kesim orasiga belgi qo‘yilmaydi**, ega qanchalik uzun bo‘lmasin: ✗ *The results of the two-year survey, were surprising.* ✓ *The results of the two-year survey were surprising.* Xuddi shunday, kesim va to‘ldiruvchi, predlog va undan keyingi so‘z orasida ham vergul bo‘lmaydi.","**7-qoida. Zarur (essential) ma’lumot ajratilmaydi.** Qism qaysi narsa haqida gap ketayotganini aniqlab bersa, vergulsiz yoziladi: *The students who finished early left.* (faqat erta tugatganlar ketdi). *That* bilan boshlangan qism hech qachon vergul bilan ajratilmaydi.","**8-qoida. Kasb yoki unvon + ism — vergulsiz:** *the biologist Rachel Carson*, *the novelist Abdulla Qodiriy*. Lekin ism oldin kelib, izoh qo‘shimcha bo‘lsa — juft vergul: *Abdulla Qodiriy, an Uzbek novelist, wrote…*","**9-qoida. Kirish qismidan keyin vergul:** gap ergash gap yoki uzun ibora bilan boshlansa, asosiy gapdan oldin vergul qo‘yiladi: *When the rain stopped, the match resumed.* Teskari tartibda odatda vergul kerak emas: *The match resumed when the rain stopped.*","**10-qoida. Bitta ega, ikki kesim — vergulsiz:** *She measured the samples and recorded the results.* Ikkinchi qismning o‘z egasi bo‘lsa — vergul + *and*: *She measured the samples, and her partner recorded the results.*","**11-qoida. Ro‘yxat:** elementlar vergul bilan ajratiladi; elementlarning o‘zida vergul bo‘lsa, ular nuqtali vergul bilan ajratiladi: *Tashkent, Uzbekistan; Almaty, Kazakhstan; and Bishkek, Kyrgyzstan.*","**12-qoida. Bitta tire ikki nuqta kabi, juft tire juft vergul kabi ishlaydi.** Gap oxiridagi izohdan oldin bitta tire: *She had one goal—to finish the race.*","**13-qoida. Gap oxiri:** savol belgisi faqat to‘g‘ridan-to‘g‘ri savolda qo‘yiladi: *Why did the bridge fail?* Bilvosita savol nuqta bilan tugaydi: *The engineers asked why the bridge had failed.*","**Apostrof va egalik shakllari** (*its / it''s*, *scientist''s / scientists''*) “Form, Structure, and Sense” qo‘llanmasida batafsil yoritilgan."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Comma splice “tabiiy” eshitiladi.** Og‘zaki nutqda ikki gapni ko‘pincha vergul bilan ulaymiz, shuning uchun bu variant to‘g‘ri bo‘lib tuyuladi. Har doim ikki tomonni “mustaqil gapmi?” deb tekshiring.","**However va therefore faqat vergullar bilan** — eng ko‘p uchraydigan tuzoq. Ular ikki mustaqil gap orasida kelsa, oldidan nuqtali vergul yoki nuqta kerak.","**Tugallanmagan qism oldida nuqtali vergul:** *Although the samples were small; the results…* — chap tomon ergash gap, nuqtali vergul mumkin emas.","**To‘liq bo‘lmagan gapdan keyin ikki nuqta:** *such as:*, *including:*, *are:* — ikki nuqtadan oldin to‘liq gap bo‘lishi shart.","**Aralash juftlik:** vergul bilan ochilib, tire yoki qavs bilan yopilgan qism (Namuna 2 dagi A).","**“Pauza” vergullari:** ega va kesim, kesim va to‘ldiruvchi orasidagi yoki *that* oldidagi ortiqcha vergul. O‘qiganda pauza bo‘lgani uchun to‘g‘ri tuyuladi, lekin bu xato (Namuna 3 dagi B)."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Reading and Writing bo‘limida har bir savolga o‘rtacha taxminan 71 soniya bor. Boundaries savollari qisqa — **30–45 soniyada** yechishga harakat qiling va tejagan vaqtni uzun matnli savollarga qoldiring.","Matn odatda bir-ikki gapdan iborat: bo‘sh joy turgan gapni (kerak bo‘lsa, oldingi gapni ham) diqqat bilan o‘qing.","**Option Eliminator** vositasi bilan aniq noto‘g‘ri variantlarni chizib qo‘ying — to‘rt variantdan ikkitasi odatda 10 soniyada tushib qoladi.","Ikki variant orasida ikkilansangiz, qoidani nomlang: “ikki mustaqil gap bormi?”, “juft belgi yopildimi?”. Qulog‘ingizga qanday eshitilishiga qarab emas, qoidaga qarab tanlang."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"independent clause","meaning":"mustaqil gap — egasi va kesimi bor, yolg‘iz tura oladi"},{"term":"dependent clause","meaning":"ergash gap — *because, although, which* kabi so‘z bilan boshlanadi, yolg‘iz tura olmaydi"},{"term":"comma splice","meaning":"ikki mustaqil gapni faqat vergul bilan ulash xatosi"},{"term":"run-on sentence","meaning":"ikki mustaqil gapni hech qanday belgisiz ulash xatosi"},{"term":"coordinating conjunction (FANBOYS)","meaning":"teng bog‘lovchilar: *for, and, nor, but, or, yet, so*"},{"term":"conjunctive adverb","meaning":"bog‘lovchi vazifasidagi ravish: *however, therefore, moreover* — bog‘lovchi emas, ikki gap orasida nuqtali vergul talab qiladi"},{"term":"nonessential (nonrestrictive) element","meaning":"qo‘shimcha qism — olib tashlansa ham gapning asosiy ma’nosi saqlanadi; juft belgi bilan ajratiladi"},{"term":"essential (restrictive) element","meaning":"zarur qism — qaysi narsa ekanini aniqlaydi; vergulsiz yoziladi"},{"term":"semicolon / colon","meaning":"nuqtali vergul (;) / ikki nuqta (:)"},{"term":"dash","meaning":"tire (—): bittasi ikki nuqta kabi, jufti juft vergul kabi ishlaydi"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Bo‘sh joyning ikki tomonida mustaqil gap bormi — buni tekshirdimmi?","Ochilgan vergul yoki tire xuddi shu belgi bilan yopildimi?","Ega va kesim (yoki kesim va to‘ldiruvchi) orasida ortiqcha belgi qolmadimi?","Tanlagan variantim bilan butun gapni o‘qib chiqdimmi?"]}]'::jsonb
from public.guides g where g.slug = 'boundaries-punctuation'
on conflict (guide_id, locale) do nothing;

-- central-ideas-and-details
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'central-ideas-and-details', 'skill', (select id from public.skills where code = 'central_ideas_details'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'central_ideas_details'), 23, 9, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Central Ideas and Details: asosiy g‘oya va tafsilotlar', 'Matnning asosiy g‘oyasini topish va matnda aniq aytilgan tafsilotni to‘g‘ri tushunish. To‘g‘ri javob butun matnni qamrab oladi, lekin matnda yo‘q narsani qo‘shmaydi.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Central Ideas and Details savollari **Information and Ideas** domeniga kiradi va ikki narsani tekshiradi:\n\n- **Asosiy g‘oya (main idea):** matn umuman nima haqida va u shu mavzu haqida **nima demoqchi**. Mavzu (*topic*) va asosiy g‘oya bir narsa emas: “kutubxona” — mavzu, “kechki ish vaqti kutubxonaga ishlaydigan kattalarni olib keldi” — asosiy g‘oya.\n- **Tafsilot (detail):** matnda aniq aytilgan ma’lumot — kim nima qildi, nima sodir bo‘ldi, qahramon nimani his qildi.\n\nMatnlar ilmiy, ijtimoiy, tarixiy yoki badiiy (hikoya, she’r) bo‘lishi mumkin. Har doim bitta qoida ishlaydi: to‘g‘ri javob **matnda yozilgan narsani** boshqa so‘zlar bilan qayta ifodalaydi. Siz o‘zingizdan hech narsa qo‘shmaysiz."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["*Which choice best states the main idea of the text?* — asosiy g‘oya savoli; ilmiy matnlarda ham, badiiy matnlarda ham uchraydi.","*According to the text, what is true about…?* — tafsilot savoli: javob matnda aniq yozilgan.","*Based on the text, what is true about…?* yoki *What does the text indicate about…?* — matndagi ma’lumotni to‘g‘ri tushunganingiz tekshiriladi.","Variantlar to‘liq jumlalar bo‘ladi va ko‘pincha matndagi so‘zlarni takrorlaydi. Ehtiyot bo‘ling: so‘zlar mos kelishi ma’no mos kelishini anglatmaydi.","Farqlang: **Text Structure and Purpose** savollarida “muallif nima **qilyapti**?” so‘raladi, bu yerda esa “matn nima **deyapti**?”"]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Savolni o‘qing:** asosiy g‘oya so‘ralyaptimi yoki aniq tafsilot? Tafsilot bo‘lsa, savoldagi kalit so‘zni (ism, raqam, hodisa) belgilab oling — matnda aynan shuni qidirasiz.","**Matnni o‘qib, mavzuni toping:** matn kim yoki nima haqida?","**Mavzu haqida nima deyilganini toping.** Ilmiy matnlarda asosiy g‘oya ko‘pincha *however, but, in fact* dan keyin yoki *found, argues, concludes, suggests* fe’llari bilan keladi. Birinchi jumla ko‘pincha faqat fon yoki keyin rad etiladigan eski fikr bo‘ladi.","**Badiiy matnda** qahramonning holati qanday o‘zgarganini kuzating: boshida nima his qildi, oxirida-chi? Asosiy g‘oya ko‘pincha shu o‘zgarishda.","**Bashoratni bitta o‘zbekcha jumlada ayting:** “Matn shuni ko‘rsatadi: …”. Keyin variantlarni o‘qing.","**Har bir variantni uch savol bilan tekshiring:** butun matnni qamrab oladimi (juda tor emasmi)? Matndan tashqariga chiqmaydimi (juda keng yoki ortiqcha kuchli emasmi)? Matnga zid emasmi? Uchala testdan o‘tgan variant — javob."]},{"type":"example","heading":"Namuna 1: ijtimoiy matnning asosiy g‘oyasi","example":{"problem":"Which choice best states the main idea of the text?","passage":"When the public library in the town of Greenhill began staying open until nine o''clock in the evening, librarians expected more students to use its study rooms. What they did not expect was a steady rise in adult visitors. Records showed that after the change, many residents who worked during the day began borrowing books, attending free language classes and using the library''s computers to apply for jobs. Head librarian Marta Kowal concluded that the library''s earlier schedule had quietly excluded a large part of the community it was meant to serve.","choices":["Extending the library''s hours revealed that its earlier schedule had kept many working adults from using it.","Students in Greenhill prefer to study in the library in the evening rather than during the day.","The library''s free language classes became more popular than its public computers.","Libraries should stay open all night so that every resident can use their services."],"solution":["**Mavzu:** Greenhill kutubxonasining kechki ish vaqti.","**Burilish:** kutubxonachilar ko‘proq talaba kutgan edi, lekin kutilmagan natija bo‘ldi — kattalar soni oshdi (*What they did not expect…*). Oxirgi jumlada xulosa: eski jadval jamiyatning katta qismini “sezdirmay chetda qoldirgan”.","**Bashorat:** “Kechgacha ochiq turish ko‘rsatdiki, avvalgi jadval ishlaydigan kattalarga kutubxonadan foydalanish imkonini bermagan.”","**A** — bashorat bilan bir xil va matnning boshi (o‘zgarish), o‘rtasi (kattalar ko‘paydi) va oxirini (Kowal xulosasi) qamrab oladi. ✓","**B** noto‘g‘ri: talabalar haqida faqat kutubxonachilarning **kutgani** aytilgan; ular kechqurun o‘qishni afzal ko‘rishi haqida ma’lumot yo‘q. So‘zlar matndan olingan, lekin fikr matnda yo‘q.","**C** noto‘g‘ri: til kurslari va kompyuterlar faqat ro‘yxatda sanab o‘tilgan; qaysi biri ommaboproq ekani solishtirilmagan. Bundan tashqari, bu juda tor tafsilot.","**D** noto‘g‘ri — **juda keng va ortiqcha kuchli:** matn bitta kutubxona haqida va “tun bo‘yi” ochiq turish haqida hech narsa demaydi. Bu umumiy tavsiya matndan tashqariga chiqadi."],"answer":"A"}},{"type":"example","heading":"Namuna 2: badiiy matnning asosiy g‘oyasi","example":{"problem":"Which choice best states the main idea of the text?","passage":"Nodira had practiced the piano piece for months, but when she sat down on the stage, the keys looked strangely unfamiliar. She glanced at the audience and found her grandfather in the third row. He was not smiling or waving; he simply nodded once, the same small nod he gave every evening when she finished practicing at home. Nodira placed her hands on the keys. The first notes came out softly, then more firmly, and soon she forgot that anyone was listening at all.","choices":["Nodira''s grandfather is disappointed that she feels nervous before her performance.","Nodira prefers practicing at home to performing in front of an audience.","A familiar gesture from her grandfather helps Nodira overcome her nervousness and play with confidence.","Nodira''s grandfather was the person who first taught her to play the piano."],"solution":["**Qahramon holatining o‘zgarishi:** boshida Nodira hayajonda — klavishlar unga “begona” ko‘rinadi. Oxirida u ishonch bilan chaladi va tinglovchilarni unutadi.","**O‘zgarishning sababi:** bobosining tanish ishorasi — har kuni kechqurun mashqdan keyin qiladigan o‘sha kichik bosh irg‘ashi.","**Bashorat:** “Bobosining tanish ishorasi Nodiraga hayajonni yengib, ishonch bilan chalishga yordam beradi.”","**A** noto‘g‘ri: bobo jilmaymaydi, lekin uning ishorasi tanish va dalda beruvchi. Matnda u xafa ekani haqida hech qanday belgi yo‘q — bu tafsilotni noto‘g‘ri talqin qilish.","**B** noto‘g‘ri: matn uyda mashq qilishni tilga oladi, lekin Nodira uni sahnadan afzal ko‘rishini aytmaydi. Aksincha, oxirida u sahnada erkin chaladi.","**C** — bashoratga to‘liq mos: ishora, hayajonni yengish va ishonch — uchalasi ham bor. ✓","**D** noto‘g‘ri: pianinoni kim o‘rgatgani haqida matnda ma’lumot yo‘q. Bu — tashqi taxmin, matnga asoslanmagan."],"answer":"C"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Mavzu ≠ asosiy g‘oya.** “Bu matn kutubxona haqida” — mavzu. To‘g‘ri variant mavzu haqida aniq bir fikr aytadi.","**Birinchi jumlaga ishonib qolmang.** SAT matnlari ko‘pincha keng tarqalgan fikr yoki fon bilan boshlanadi, keyin *however, but, yet* bilan haqiqiy g‘oyaga o‘tadi. Asosiy g‘oya ko‘pincha burilishdan keyin yoki oxirgi jumlada.","**Butun matnni qamrab olish testi:** variant matnning boshi, o‘rtasi va oxiriga mos keladimi? Faqat bitta jumlaga mos variant — juda tor.","**Tafsilot savollarida** javobni xotiradan emas, matndan toping: savoldagi kalit so‘zni matndan qidiring va o‘sha jumlani qayta o‘qing. To‘g‘ri javob o‘sha jumlaning boshqa so‘zlar bilan ifodasi bo‘ladi.","**O‘z bilimingizni chetga qo‘ying.** Mavzuni yaxshi bilsangiz ham, faqat matnda aytilgan narsaga tayaning. Hayotda to‘g‘ri, lekin matnda yo‘q fikr — noto‘g‘ri javob.","**Ingliz tili bo‘yicha maslahat:** har bir so‘zni tarjima qilishga urinmang; notanish so‘zni “X” deb qabul qilib davom eting. Asosiy g‘oyani beradigan fe’llarni qidiring: *found* (aniqladi), *argues* (ta’kidlaydi), *concluded* (xulosa qildi), *suggests* (ko‘rsatadi, taxmin qiladi), *revealed* (oshkor qildi). Ulardan keyingi qism ko‘pincha matnning yuragi. Burilish so‘zlari — *however, but, yet, in fact* — asosiy fikr qayerda ekanini ko‘rsatadi.","**Badiiy matnlarda** qahramonning his-tuyg‘usini bildiruvchi so‘zlar va harakatlar (*hesitated, glanced, trembled, smiled, forgot*) asosiy g‘oyaga yo‘l ko‘rsatadi."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Juda tor (too narrow):** matndagi bitta tafsilotni asosiy g‘oya qilib ko‘rsatadi (1-namunadagi C).","**Juda keng yoki umumlashtirilgan (too broad):** bitta holatdan hamma uchun qoida chiqaradi — *all libraries*, *every student* (1-namunadagi D).","**Matnda yo‘q, lekin ishonarli:** mantiqan bo‘lishi mumkin, ammo matnda aytilmagan (2-namunadagi D).","**Noto‘g‘ri talqin:** matndagi tafsilotni teskari tushunish — bobo jilmaymagani uchun uni “xafa” deb o‘ylash (2-namunadagi A).","**So‘z mos, munosabat noto‘g‘ri:** variant matndagi so‘zlarni ishlatadi (*students, evening*), lekin ular orasidagi bog‘lanishni buzadi (1-namunadagi B).","**Ortiqcha kuchli so‘zlar:** *always, never, only, proves, all* — matn ehtiyotkor bo‘lsa (*suggests, may*), bunday variant odatda noto‘g‘ri."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Reading and Writing’da bir savolga o‘rtacha **71 soniya** bor (har modulda 27 savol, 32 daqiqa).","Asosiy g‘oya savollariga **60–75 soniya** yetarli: matnni bir marta diqqat bilan o‘qing, bashorat qiling va variantlarni tekshiring.","Tafsilot savolida savolni matndan **oldin** o‘qish vaqtni tejaydi: nimani qidirayotganingizni bilib o‘qiysiz.","Ikki variant orasida qolsangiz, har biri uchun matndan dalil qidiring. Dalili topilmagan variantni o‘chiring; ikkalasi ham shubhali bo‘lsa, birini tanlang, **Mark for Review** qiling va davom eting."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"main idea","meaning":"asosiy g‘oya: matn mavzu haqida nima demoqchi"},{"term":"central claim","meaning":"markaziy da’vo — muallif isbotlamoqchi bo‘lgan asosiy fikr"},{"term":"topic","meaning":"mavzu: matn nima haqida"},{"term":"supporting detail","meaning":"asosiy g‘oyani qo‘llab-quvvatlovchi tafsilot (misol, raqam, fakt)"},{"term":"according to the text","meaning":"matnga ko‘ra — javob matnda aniq yozilgan"},{"term":"based on the text","meaning":"matnga asoslanib — faqat matndagi ma’lumotdan foydalaning"},{"term":"primarily / mainly","meaning":"asosan, birinchi navbatda"},{"term":"conclude / conclusion","meaning":"xulosa qilmoq / xulosa"},{"term":"suggest","meaning":"ko‘rsatmoq, ishora qilmoq — ehtiyotkor da’vo"},{"term":"indicate","meaning":"bildirmoq, ko‘rsatmoq"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Tanlagan variantim mavzuni emas, mavzu haqidagi **fikrni** ifodalaydimi?","U matnning boshi, o‘rtasi va oxiriga mos keladimi?","Variantdagi har bir da’vo matnda bormi — o‘zimdan hech narsa qo‘shmadimmi?","Variantdagi so‘zlar (*all, always, only*) matndagi ehtiyotkorlik darajasiga mosmi?"]}]'::jsonb
from public.guides g where g.slug = 'central-ideas-and-details'
on conflict (guide_id, locale) do nothing;

-- circles
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'circles', 'skill', (select id from public.skills where code = 'circles'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'circles'), 19, 10, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Aylana va doira', 'Aylana uzunligi va doira yuzasi, yoy uzunligi va sektor yuzasi, markaziy va ichki chizilgan burchaklar, urinma hamda koordinata tekisligidagi aylana tenglamasi — bu savollarning deyarli barchasida asosiy kalit radius.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Bu ko‘nikma aylana va doira bilan bog‘liq hisoblarni tekshiradi. Deyarli har bir savol **radiusni** topishga borib taqaladi.\n\n- **Asosiy formulalar:** aylana uzunligi $C = 2\\pi r$, doira yuzasi $A = \\pi r^2$.\n- **Burchak o‘lchovi:** to‘liq aylana $360^\\circ$ yoki $2\\pi$ radian; $180^\\circ = \\pi$ radian. Gradusdan radianga o‘tish uchun $\\frac{\\pi}{180}$ ga ko‘paytiring: $60^\\circ = \\frac{\\pi}{3}$.\n\n**Qism va butun proporsiyasi** — yoy va sektor masalalarining kaliti. Markaziy burchak $\\theta$ bo‘lsa:\n$$\\frac{\\theta}{360^\\circ} = \\frac{\\text{arc length}}{2\\pi r} = \\frac{\\text{sector area}}{\\pi r^2}$$\nRadianda bu formulalar soddalashadi: yoy uzunligi $s = r\\theta$, sektor yuzasi $\\frac{1}{2}r^2\\theta$.\n\n- **Markaziy burchak** (uchi markazda) o‘zi tiralgan yoyning gradus o‘lchoviga teng.\n- **Ichki chizilgan burchak** (uchi aylanada) xuddi shu yoyga tiralgan markaziy burchakning **yarmiga** teng. Diametrga tiralgan ichki chizilgan burchak $90^\\circ$.\n- **Urinma** (tangent) urinish nuqtasiga tortilgan radiusga perpendikulyar — demak, to‘g‘ri burchakli uchburchak va Pifagor teoremasi paydo bo‘ladi.\n- **Ikki radius** va vatar (chord) teng yonli uchburchak hosil qiladi.\n\n**Aylana tenglamasi** (xy-tekislikda):\n$$(x - h)^2 + (y - k)^2 = r^2$$\nbu yerda $(h, k)$ — markaz, $r$ — radius. Tenglama $x^2 + y^2 + Dx + Ey + F = 0$ ko‘rinishida berilsa, **to‘la kvadrat ajratish** (completing the square) kerak: $x$ hadlariga $\\left(\\frac{D}{2}\\right)^2$ ni, $y$ hadlariga $\\left(\\frac{E}{2}\\right)^2$ ni qo‘shing va xuddi shu sonlarni tenglikning o‘ng tomoniga ham qo‘shing.\n\nReference sheet’da $C = 2\\pi r$, $A = \\pi r^2$ hamda aylanada $360^\\circ$ va $2\\pi$ radian borligi berilgan. Aylana tenglamasi, yoy uzunligi va sektor yuzasi formulalari esa **yo‘q** — ularni yodlang yoki proporsiyadan chiqaring."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["*“In the xy-plane, the graph of the given equation is a circle. What are the coordinates of the center…”*, *“…what is the radius of the circle?”* — aylana tenglamasi.","*“Which equation represents a circle with center (3, −2) and radius 5?”* — tenglamani tuzish.","*“arc”*, *“minor arc”*, *“sector”*, *“central angle”* — yoy va sektor; aylananing qismini proporsiya bilan toping.","*“…has a measure of 2π/3 radians”* — burchak radianda; $s = r\\theta$ formulasi tez ishlaydi.","*“Line ℓ is tangent to the circle at point P”* — urinma radiusga perpendikulyar, to‘g‘ri burchakli uchburchak paydo bo‘ladi.","*“Points A, B, and C lie on the circle”*, *“AC is a diameter”* — ichki chizilgan burchaklar."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Savol turini aniqlang:** (a) yoy yoki sektor — aylananing bir qismi; (b) burchaklar — markaziy, ichki chizilgan yoki urinma; (c) koordinata tekisligidagi tenglama.","**Radiusni toping.** Diametr berilsa — ikkiga bo‘ling; aylana uzunligi yoki yuza berilsa — formuladan $r$ ni chiqaring ($C = 10\\pi$ bo‘lsa, $r = 5$).","**Yoy va sektor uchun bitta proporsiya tuzing:** “qism / butun” — burchak bo‘yicha ham, uzunlik bo‘yicha ham, yuza bo‘yicha ham bir xil kasr. Burchak radianda bo‘lsa, butun $2\\pi$, gradusda bo‘lsa — $360^\\circ$.","**Burchak savollarida radiuslarni chizing.** Markazdan aylanadagi nuqtalarga tortilgan radiuslar teng — teng yonli uchburchak; urinish nuqtasidagi radius urinmaga perpendikulyar — to‘g‘ri burchak; diametrga tiralgan ichki chizilgan burchak $90^\\circ$.","**Tenglamani standart ko‘rinishga keltiring.** $x$ va $y$ hadlarini guruhlang, har biri uchun to‘la kvadrat ajrating va qo‘shilgan sonlarni o‘ng tomonga ham qo‘shing. $x^2$ va $y^2$ oldida 1 dan boshqa umumiy koeffitsiyent bo‘lsa, avval butun tenglamani unga bo‘ling.","**Tekshiring:** o‘ng tomondagi son — $r^2$, radius emas; markaz koordinatalarining ishorasi qavsdagi ishoraga **teskari**; javob gradusda yoki radianda — so‘ralganidek."]},{"type":"example","heading":"Namuna 1: tenglamadan radiusni topish","example":{"problem":"In the xy-plane, the graph of the equation $x^2 + y^2 - 8x + 6y = 24$ is a circle. What is the radius of the circle?","choices":["$2\\sqrt{6}$","$5$","$7$","$49$"],"solution":["Hadlarni guruhlaymiz: $(x^2 - 8x) + (y^2 + 6y) = 24$.","To‘la kvadrat: $x$ uchun $\\left(\\frac{-8}{2}\\right)^2 = 16$, $y$ uchun $\\left(\\frac{6}{2}\\right)^2 = 9$. Ikkala sonni ham **ikkala tomonga** qo‘shamiz: $(x^2 - 8x + 16) + (y^2 + 6y + 9) = 24 + 16 + 9$.","Standart ko‘rinish: $(x - 4)^2 + (y + 3)^2 = 49$. Markaz $(4, -3)$, $r^2 = 49$, demak $r = 7$.","Xato variantlar: **D** (49) — bu $r^2$, radius emas. **A** ($2\\sqrt{6} = \\sqrt{24}$) — o‘ng tomonga 16 va 9 qo‘shilmagan. **B** (5) — faqat qo‘shilgan sonlar olingan ($\\sqrt{16 + 9}$), asl 24 esa unutilgan."],"answer":"C) 7"}},{"type":"example","heading":"Namuna 2: yoy uzunligi radianda (javobni o‘zingiz yozasiz)","example":{"problem":"A circle has center $O$ and radius 9. Points $A$ and $B$ lie on the circle, and the measure of central angle $AOB$ is $\\frac{2\\pi}{3}$ radians. The length of minor arc $AB$ is $k\\pi$, where $k$ is a constant. What is the value of $k$?","solution":["Burchak radianda berilgan, shuning uchun eng tez formula: $s = r\\theta$.","$s = 9 \\cdot \\frac{2\\pi}{3} = 6\\pi$.","Proporsiya bilan tekshiramiz: $\\frac{2\\pi}{3}$ — to‘liq aylananing ($2\\pi$) uchdan biri. Aylana uzunligi $2\\pi \\cdot 9 = 18\\pi$, uning uchdan biri $6\\pi$ ✓.","Demak $k = 6$. Tuzoqlar: sektor yuzasini hisoblash ($\\frac{1}{2} \\cdot 81 \\cdot \\frac{2\\pi}{3} = 27\\pi$, ya’ni 27) yoki radius o‘rniga diametrni olish (12). Javob katagiga **6** ni yozing."],"answer":"6"}},{"type":"example","heading":"Namuna 3: ichki chizilgan va markaziy burchak","example":{"problem":"Points $A$, $B$, and $C$ lie on a circle with center $O$, and $\\overline{AC}$ is a diameter of the circle. The measure of angle $BAC$ is $28^\\circ$. What is the measure of angle $BOC$?","choices":["$28^\\circ$","$56^\\circ$","$62^\\circ$","$124^\\circ$"],"solution":["$\\angle BAC$ — ichki chizilgan burchak (uchi aylanada), u $BC$ yoyiga tiraladi. $\\angle BOC$ — markaziy burchak, u ham xuddi shu $BC$ yoyiga tiraladi.","Qoida: markaziy burchak bir xil yoyga tiralgan ichki chizilgan burchakdan **ikki marta** katta. $\\angle BOC = 2 \\cdot 28^\\circ = 56^\\circ$.","Boshqa yo‘l bilan tekshiramiz: $OA = OB$ (radiuslar), demak $\\triangle AOB$ teng yonli va $\\angle OBA = 28^\\circ$. $O$ nuqta $AC$ diametrda yotgani uchun $\\angle BOC$ — $\\triangle AOB$ ning tashqi burchagi: $28^\\circ + 28^\\circ = 56^\\circ$ ✓.","Xato variantlar: **A** (28°) — ichki chizilgan burchakni markaziy burchakka teng deb olish. **C** (62°) — bu $\\angle BCA$: diametrga tiralgan $\\angle ABC = 90^\\circ$ bo‘lgani uchun $90^\\circ - 28^\\circ$. **D** (124°) — bu $\\angle AOB$, ya’ni $180^\\circ - 56^\\circ$."],"answer":"B) $56^\\circ$"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Markaz ishorasi:** $(x + 3)^2 + (y - 5)^2 = 16$ tenglamada markaz $(-3, 5)$ — qavs ichidagi ishoraga teskari.","**O‘ng tomon — r², radius emas:** yuqoridagi tenglamada radius 4, 16 emas. O‘ng tomon to‘la kvadrat bo‘lmasa (masalan, 20), radius $\\sqrt{20} = 2\\sqrt{5}$.","**To‘la kvadrat ajratganda** qo‘shilgan sonlarni o‘ng tomonga ham qo‘shishni unutmang — bu eng ko‘p uchraydigan xato.","**Gradus va radian:** $180^\\circ = \\pi$ radian. $s = r\\theta$ va $\\frac{1}{2}r^2\\theta$ formulalari **faqat radianda** ishlaydi; gradusda proporsiyadan foydalaning.","**Yoy o‘lchovi va yoy uzunligi farqli:** yoy o‘lchovi (arc measure) gradusda o‘lchanadi va markaziy burchakka teng; yoy uzunligi (arc length) esa uzunlik birligida.","**Kichik va katta yoy:** kichik yoy (minor arc) $180^\\circ$ dan kichik; katta yoy (major arc) uchun $360^\\circ$ dan kichik yoyni ayiring.","**Nuqta aylananing ichidami, tashqarisidami?** Nuqta koordinatalarini $(x - h)^2 + (y - k)^2$ ga qo‘yib, $r^2$ bilan solishtiring: kichik — ichida, teng — aylanada, katta — tashqarida."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**r² ni radius sifatida berish** (Namuna 1 dagi 49).","**Markaz koordinatalarida ishora xatosi:** to‘g‘ri javob $(4, -3)$ bo‘lsa, $(-4, 3)$ ham variantlarda turadi.","**Yoy uzunligi va sektor yuzasini adashtirish** — ikkala natija ham (masalan, $6\\pi$ va $27\\pi$) variantda bo‘lishi mumkin.","**Ichki chizilgan burchakni ikkiga ko‘paytirmaslik** yoki aksincha, markaziy burchakdan ichki chizilgan burchakka o‘tganda ikkiga bo‘lmaslik.","**Radius o‘rniga diametr:** aylana uzunligi yoki yuzadan $r$ ni chiqarganda $C = \\pi d$ va $C = 2\\pi r$ ni adashtirish.","**Qo‘shni burchak:** so‘ralgan burchak o‘rniga uni $180^\\circ$ gacha to‘ldiruvchi burchak (Namuna 3 dagi 124°)."]},{"type":"time","heading":"Vaqt, Desmos va reference sheet","items":["Odatda **45–90 soniya**. To‘la kvadrat ajratishni yaxshi bilsangiz, tenglama savollari 45 soniyada yechiladi.","**Desmos aylana savollarida juda kuchli:** tenglamani o‘zgartirmasdan to‘g‘ridan-to‘g‘ri kiriting — Desmos aylanani chizadi va markaz hamda radiusni grafikdan ko‘rasiz. Variantdagi tenglamani ham kiritib, ikki grafik ustma-ust tushishini tekshirishingiz mumkin.","**Reference sheet** faqat $C = 2\\pi r$, $A = \\pi r^2$ va aylanadagi $360^\\circ$ / $2\\pi$ radianni beradi. Aylana tenglamasi va yoy yoki sektor formulalari u yerda yo‘q.","Ichki chizilgan burchak va urinma savollarida chizma chizish hisoblashdan ko‘ra ko‘proq vaqt oladi — radiuslarni chizib, teng yonli yoki to‘g‘ri burchakli uchburchaklarni toping. 90 soniyadan oshsa, **Mark for Review** bilan belgilang."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"radius / diameter","meaning":"radius / diametr — markazdan aylanagacha masofa; diametr markazdan o‘tadi: $d = 2r$"},{"term":"circumference","meaning":"aylana uzunligi: $C = 2\\pi r$"},{"term":"arc / minor arc / major arc","meaning":"yoy / kichik yoy (180° dan kichik) / katta yoy"},{"term":"central angle","meaning":"markaziy burchak — uchi markazda; tiralgan yoyning gradus o‘lchoviga teng"},{"term":"inscribed angle","meaning":"ichki chizilgan burchak — uchi aylanada; markaziy burchakning yarmi"},{"term":"sector","meaning":"sektor — ikki radius va yoy bilan chegaralangan “pirog bo‘lagi”"},{"term":"chord","meaning":"vatar — aylananing ikki nuqtasini tutashtiruvchi kesma"},{"term":"tangent","meaning":"urinma — aylanaga bitta nuqtada tegadi va o‘sha nuqtadagi radiusga perpendikulyar"},{"term":"radian","meaning":"radian — burchak o‘lchov birligi: $\\pi$ radian $= 180^\\circ$"},{"term":"completing the square","meaning":"to‘la kvadrat ajratish — tenglamani $(x - h)^2 + (y - k)^2 = r^2$ ko‘rinishiga keltirish usuli"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Radiusni (diametr, $r^2$ yoki aylana uzunligini emas) to‘g‘ri topdimmi?","Burchak birligi — gradus yoki radian — formulaga mosmi?","Tenglamada markaz ishorasini va o‘ng tomonga qo‘shilgan sonlarni tekshirdimmi?","So‘ralgan narsa — yoy uzunligi, sektor yuzasi yoki burchak — aynan shumi?"]}]'::jsonb
from public.guides g where g.slug = 'circles'
on conflict (guide_id, locale) do nothing;

-- command-of-evidence-quantitative
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'command-of-evidence-quantitative', 'skill', (select id from public.skills where code = 'command_of_evidence_quantitative'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'command_of_evidence_quantitative'), 25, 10, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Command of Evidence (Quantitative): jadval va grafikdan dalil', 'Matndagi da’voni jadval yoki grafikdagi ma’lumot bilan qo‘llab-quvvatlash yoki matnni ma’lumot asosida to‘ldirish. To‘g‘ri javob ikki shartga javob beradi: grafikka ko‘ra aniq va da’voga aloqador.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Command of Evidence: Quantitative savollari **Information and Ideas** domeniga kiradi. Sizga qisqa matn va unga ilova qilingan **jadval, ustunli diagramma (bar graph) yoki chiziqli grafik (line graph)** beriladi. Matnda odatda tadqiqotchining da’vosi yoki xulosasi bor; siz uni grafikdagi ma’lumot bilan qo‘llab-quvvatlaydigan variantni tanlaysiz yoki matn oxiridagi bo‘sh joyni ma’lumotga asoslanib to‘ldirasiz.\n\nBu Math savoli emas: murakkab hisob-kitob deyarli kerak bo‘lmaydi. Ko‘nikmaning mohiyati — ikki filtrni birga qo‘llash:\n\n- **Aloqadorlik:** variant matndagi **aynan shu** da’voni qo‘llab-quvvatlaydimi?\n- **Aniqlik:** variantdagi raqamlar, yillar va taqqoslashlar grafikka mos keladimi?\n\nKo‘p o‘quvchilar faqat aniqlikni tekshiradi va aloqadorlikni unutadi. Grafikka ko‘ra to‘g‘ri, lekin da’voga aloqasiz variant — bu turdagi savolning eng mashhur tuzog‘i."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["Matn yonida jadval yoki grafik bor va savolda *data from the table* yoki *data from the graph* iborasi ishlatiladi.","*Which choice most effectively uses data from the graph to support the researchers'' claim?* — da’voni qo‘llab-quvvatlovchi ma’lumot.","*Which choice most effectively uses data from the table to complete the statement?* — matn oxiridagi bo‘sh joyni ma’lumot bilan to‘ldirish.","*Which choice best describes data from the graph that support the hypothesis?* — gipotezaga mos keladigan ma’lumotni tanlash.","Variantlar odatda aniq raqamlar, yillar yoki guruhlar nomini o‘z ichiga oladi: *In 2019, Town A…*, *…rose from about 1,200 to about 3,100*."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Grafikdan oldin matnni va savolni o‘qing.** Da’voni toping va belgilang: u nimani taqqoslaydi yoki qanday o‘zgarishni aytadi?","**Da’voni “ma’lumot tiliga” o‘giring:** “dastur suv sarfini hamma shaharda kamaytirdi” → har bir shaharda keyingi qiymat oldingisidan kichik bo‘lishi kerak. “Tiklash loyihasi yordam berdi” → loyiha bo‘lgan joyda o‘sish va loyiha bo‘lmagan joyda o‘sish yo‘qligi.","**Grafikni o‘qing:** sarlavha, o‘qlar (x va y), **o‘lchov birliklari** (foiz, ming, *in hundreds*), legenda (qaysi rang yoki chiziq qaysi guruh) va vaqt oralig‘i.","**Har bir variantni ikki bosqichda tekshiring:** (a) da’voga aloqadormi? Aloqasiz variantni raqamlarini tekshirmasdan o‘chiring. (b) grafikka ko‘ra aniqmi? Raqam, yil va guruh nomini grafikdan topib solishtiring.","**Taqqoslash talab qilinsa,** to‘g‘ri variant odatda **ikkala** guruhni (yoki ikkala davrni) tilga oladi. Faqat bitta guruh haqidagi variant ko‘pincha yetarli emas.","**Qolgan variantni da’vo bilan yana bir bor solishtiring:** u da’voning barcha qismlarini (masalan, “hammasida kamaydi” va “har xil miqdorda”) qamrab oladimi?"]},{"type":"example","heading":"Namuna 1: jadval bilan da’voni qo‘llab-quvvatlash","example":{"problem":"Which choice most effectively uses data from the table to support Alimova''s claim?","passage":"In 2021, three towns in a dry region launched a program that gave residents free water-saving showerheads and taught them how to repair leaking pipes. Program manager Feruza Alimova claims that the program reduced household water use in every town, although the size of the reduction was not the same everywhere.\n\nAverage daily water use per household (liters):\n\n- Town A: 410 in 2020; 350 in 2022\n- Town B: 380 in 2020; 360 in 2022\n- Town C: 450 in 2020; 330 in 2022","choices":["In 2020, households in Town C used more water per day than households in Town A or Town B did.","Average daily water use per household fell in all three towns from 2020 to 2022, by 20 liters in Town B and by as much as 120 liters in Town C.","Average daily water use per household fell by the same amount in Town A and Town C from 2020 to 2022.","In 2022, households in Town A used less water per day than households in Town B did."],"solution":["**Da’vo ikki qismdan iborat:** (1) suv sarfi **har bir** shaharda kamaygan; (2) kamayish miqdori **har xil** bo‘lgan.","**Jadvaldan o‘zgarishlarni hisoblaymiz:** A: $410 \\to 350$, ya’ni 60 litrga kam; B: $380 \\to 360$, 20 litrga kam; C: $450 \\to 330$, 120 litrga kam. Uchala shaharda ham kamaygan va miqdorlar turlicha — da’vo ma’lumotga mos.","**B** — aniq (uchala shaharda kamaygan; B da 20, C da 120 litr) va da’voning **ikkala qismini** ham qamrab oladi. ✓","**A** noto‘g‘ri: 2020-yil uchun ma’lumot to‘g‘ri (450 litr 410 va 380 dan ko‘p), lekin u faqat dasturdan **oldingi** holatni ko‘rsatadi va dastur suv sarfini kamaytirgani haqida hech narsa demaydi. Aniq, lekin aloqasiz.","**C** noto‘g‘ri — **noaniq**: A da kamayish 60 litr, C da 120 litr. Bundan tashqari, bu da’voning ikkinchi qismiga (“har xil miqdorda”) zid.","**D** noto‘g‘ri: 2022-yilda A (350) haqiqatan B dan (360) kam, ya’ni ma’lumot aniq. Lekin bitta yildagi ikki shaharni solishtirish o‘zgarish haqida hech narsa aytmaydi — yana aniq, lekin aloqasiz."],"answer":"B"}},{"type":"example","heading":"Namuna 2: chiziqli grafik va o‘lchov birligi","example":{"problem":"Which choice most effectively uses data from the graph to support the ecologists'' claim?","passage":"Ecologists counted nesting pairs of a wading bird at two wetlands, Lake North and Lake South, from 2016 to 2024. In 2019, a restoration project began at Lake North that raised water levels and replanted native reeds; Lake South received no restoration. The ecologists claim that the project helped the bird population at Lake North recover.\n\nLine graph: number of nesting pairs (in hundreds)\n\n- Lake North: 2016 — 14; 2019 — 12; 2022 — 22; 2024 — 31\n- Lake South: 2016 — 15; 2019 — 13; 2022 — 13; 2024 — 12","choices":["At Lake North, the number of nesting pairs rose from 12 in 2019 to 31 in 2024.","In 2016, Lake South had more nesting pairs than Lake North did.","At Lake North, the number of nesting pairs rose from about 1,200 in 2019 to about 3,100 in 2024, while at Lake South it stayed between about 1,200 and 1,300 over the same period.","The number of nesting pairs at Lake South increased steadily from 2016 to 2024."],"solution":["**Da’vo:** tiklash loyihasi (2019-yildan, faqat Lake North’da) qushlar sonining tiklanishiga yordam berdi. Buni eng kuchli qo‘llab-quvvatlaydigan ma’lumot: loyihadan keyin Lake North’da o‘sish **va** loyiha bo‘lmagan Lake South’da o‘sish yo‘qligi.","**Birlikka e’tibor:** grafik sarlavhasida *in hundreds* — “yuzlarda”. Demak 12 — bu 1,200 juft, 31 — 3,100 juft.","**A** noto‘g‘ri — **birlik xatosi**: grafikda qiymatlar yuzlarda berilgan, ya’ni 12 emas, 1,200 juft. Yo‘nalish to‘g‘ri bo‘lsa ham, raqamlar noto‘g‘ri.","**B** noto‘g‘ri: 2016-yil uchun to‘g‘ri (15 > 14), lekin bu loyihadan **oldingi** yil — loyiha natijasi haqida hech narsa demaydi.","**C** — aniq (12 dan 31 gacha yuz, ya’ni 1,200 dan 3,100 gacha; Lake South’da 12–13 yuz) va da’voga to‘liq aloqador: loyiha bo‘lgan joyni loyiha bo‘lmagan joy bilan taqqoslaydi. ✓","**D** noto‘g‘ri — noaniq: Lake South’da juftlar soni 15 dan 12 ga **kamaygan**, o‘smagan."],"answer":"C"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Grafikning “pasporti”ni o‘qing:** sarlavha, o‘qlar nomi, o‘lchov birligi va legenda. *In thousands*, *percent of respondents*, *per 1,000 people* kabi izohlar raqamlarning ma’nosini butunlay o‘zgartiradi.","**Ikki filtr:** har bir variant uchun “da’voga aloqadormi?” va “grafikka ko‘ra to‘g‘rimi?” deb so‘rang. To‘g‘ri javob ikkala savolga ham “ha” deydi.","**Da’vo nimani talab qilishini aniqlang:** o‘zgarish (yillar bo‘yicha), taqqoslash (guruhlar orasida) yoki bitta qiymat. Da’vo o‘zgarish haqida bo‘lsa, faqat bitta yil haqidagi variant yetarli emas.","**Foiz va son farqi:** *percent* (foiz) va *number* (son) ni, shuningdek *percentage points* (foiz punkti) va *percent change* (foiz o‘zgarishi) ni adashtirmang. 20% dan 30% ga o‘sish — 10 foiz punktiga o‘sish, lekin foiz o‘zgarishi bo‘yicha 50% ga o‘sish.","**Grafikdagi ma’lumotdan ortiq xulosa chiqarmang.** Variant grafikda yo‘q sabab yoki kelajak haqida gapirsa (*will continue to rise*, *because of…*), u ma’lumotdan tashqariga chiqqan.","**Ingliz tili bo‘yicha maslahat — o‘zgarish va taqqoslash so‘zlari:** *increase / rise / grow* — o‘smoq; *decrease / decline / drop / fall* — kamaymoq; *remain stable / stay roughly the same* — deyarli o‘zgarmaslik; *peak* — eng yuqori nuqta; *exceed* — oshib ketmoq; *respectively* — mos ravishda; *whereas / while* — holbuki (taqqoslash). Savoldagi *most effectively uses data … to support* iborasini “qaysi variant ma’lumotdan foydalanib da’voni eng yaxshi isbotlaydi” deb tushuning. Notanish so‘z (masalan, qush yoki o‘simlik nomi) muhim emas — uni “X” deb qabul qiling, raqamlar va da’vo muhimroq."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Aniq, lekin aloqasiz** (eng ko‘p uchraydi): raqamlar grafikka mos, ammo da’voni qo‘llab-quvvatlamaydi (1-namunadagi A va D, 2-namunadagi B).","**Aloqador, lekin noaniq:** variant da’voga mos keladigandek tuyuladi, ammo raqamlari noto‘g‘ri (1-namunadagi C).","**Birlik yoki o‘q xatosi:** *in hundreds* yoki *in thousands* ni e’tiborsiz qoldirish, x va y o‘qlarini almashtirish (2-namunadagi A).","**Noto‘g‘ri yil yoki guruh:** legendadagi ranglarni adashtirish yoki da’voda aytilgan davrdan boshqa yillarni olish.","**Teskari tendensiya:** kamayishni o‘sish deb o‘qish (2-namunadagi D).","**Ortiqcha xulosa:** grafik ko‘rsatmaydigan sabab-natija yoki kelajak haqidagi bashorat."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Reading and Writing’da bir savolga o‘rtacha **71 soniya** bor (har modulda 27 savol, 32 daqiqa). Grafikli savollar biroz ko‘proq vaqt olishi mumkin — **80–100 soniya** normal.","Eng katta vaqt tejovchi usul: **avval da’voni o‘qing**, keyin grafikka faqat kerakli joylarda qarang. Grafikdagi barcha raqamlarni o‘rganish shart emas.","Variantlarni tekshirishda **aloqadorlikdan** boshlang: da’voga aloqasi yo‘q variantni raqamlarini solishtirmasdan o‘chirsangiz, vaqt tejaladi.","Hisob kerak bo‘lsa (ayirma yoki taqqoslash), natijani yozib qo‘ying — bir nechta raqamni xotirada ushlab turish xatoga olib keladi."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"data","meaning":"ma’lumotlar (raqamlar, o‘lchovlar)"},{"term":"table","meaning":"jadval"},{"term":"bar graph","meaning":"ustunli diagramma"},{"term":"line graph","meaning":"chiziqli grafik — vaqt bo‘yicha o‘zgarishni ko‘rsatadi"},{"term":"axis (x-axis, y-axis)","meaning":"o‘q (gorizontal va vertikal o‘q)"},{"term":"legend / key","meaning":"legenda: qaysi rang yoki belgi qaysi guruhni bildiradi"},{"term":"trend","meaning":"tendensiya — umumiy o‘zgarish yo‘nalishi"},{"term":"respectively","meaning":"mos ravishda — sanalgan tartibda"},{"term":"approximately / about","meaning":"taxminan"},{"term":"exceed","meaning":"oshib ketmoq, …dan ko‘p bo‘lmoq"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Grafikning sarlavhasi, o‘lchov birligi va legendasini o‘qidimmi?","Tanlagan variantimdagi har bir raqam, yil va guruh grafikka mosmi?","Variant matndagi aynan shu da’voni qo‘llab-quvvatlaydimi — shunchaki to‘g‘ri fakt emasmi?","Da’vo taqqoslash talab qilsa, variant ikkala guruhni ham tilga oladimi?"]}]'::jsonb
from public.guides g where g.slug = 'command-of-evidence-quantitative'
on conflict (guide_id, locale) do nothing;

-- command-of-evidence-textual
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'command-of-evidence-textual', 'skill', (select id from public.skills where code = 'command_of_evidence_textual'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'command_of_evidence_textual'), 24, 10, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Command of Evidence (Textual): da’voni dalil bilan isbotlash', 'Berilgan da’voni eng yaxshi ko‘rsatadigan iqtibosni yoki gipotezani eng to‘g‘ridan-to‘g‘ri qo‘llab-quvvatlaydigan (yoki zaiflashtiradigan) topilmani tanlash. Kalit — da’voni qismlarga ajratib, har bir qismga mos dalil izlash.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Command of Evidence: Textual savollari **Information and Ideas** domeniga kiradi. Ularda sizga biror **da’vo** (*claim*) yoki **gipoteza** (*hypothesis*) beriladi va uni eng yaxshi isbotlaydigan dalilni topish so‘raladi. Ikki asosiy ko‘rinish bor:\n\n- **Iqtibos tanlash:** matnda badiiy asar (she’r, roman, hikoya) haqida da’vo aytiladi, variantlar esa o‘sha asardan to‘rtta iqtibos. Da’voni eng yaxshi ko‘rsatadigan (*illustrates*) iqtibosni tanlaysiz.\n- **Topilma tanlash (“if true”):** matnda olimning gipotezasi tasvirlanadi, variantlar esa faraziy tadqiqot natijalari. Qaysi natija, **agar to‘g‘ri bo‘lsa**, gipotezani eng to‘g‘ridan-to‘g‘ri qo‘llab-quvvatlashini (ba’zan — zaiflashtirishini) aniqlaysiz.\n\nIkkala holatda ham ish bir xil: avval da’voni aniq tushunasiz, keyin unga **to‘liq va bevosita** mos keladigan dalilni topasiz. Mavzuga oid, lekin da’voning aynan o‘zini isbotlamaydigan variantlar — asosiy tuzoq."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["*Which quotation from the poem most effectively illustrates the claim?* (yoki *from the novel*, *from the story*) — badiiy asardan iqtibos tanlash.","*Which finding, if true, would most directly support the researcher''s hypothesis?* — gipotezani qo‘llab-quvvatlovchi faraziy natija.","*Which finding, if true, would most directly weaken the researchers'' claim?* — teskari savol: da’voni **zaiflashtiradigan** natija kerak. *Undermine* va *challenge* so‘zlari ham shu ma’noda keladi.","Matnning oxirida da’vo yoki gipoteza odatda aniq bayon qilinadi: *X hypothesizes that…*, *the student claims that…*, *the speaker suggests that…*.","Farqlang: agar dalil jadval yoki grafikdan olinishi kerak bo‘lsa, bu **Command of Evidence: Quantitative** savoli (alohida qo‘llanmada)."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Savolni o‘qing va yo‘nalishini belgilang:** *support / illustrate* (qo‘llab-quvvatlash) yoki *weaken / undermine* (zaiflashtirish). Bu so‘zni **Highlights & Notes** bilan belgilab qo‘ying — u butun javobni o‘zgartiradi.","**Da’voni yoki gipotezani topib, qismlarga ajrating.** Masalan: “shovqin (1) qushlarni balandroq sayrashga (2) majbur qiladi” yoki “to‘quvchilik o‘tmishni (1) kelajak bilan (2) bog‘laydi”. To‘g‘ri dalil **har bir qismni** qamrab olishi kerak.","**Ideal dalilni bashorat qiling:** qanday natija chiqsa, olim “Ko‘rdingizmi, men haq edim!” deya oladi? Iqtibos savolida esa: qaysi satr bu da’voni ochiq ko‘rsatadi?","**“If true” savollarida** natija haqiqatan shunday yoki yo‘qligini tekshirmang — uni to‘g‘ri deb qabul qiling. Faqat bitta narsani so‘rang: bu natija gipotezadagi **aynan o‘sha sabab va oqibatni** bog‘laydimi?","**Variantlarni chiqarib tashlang:** mavzuga oid, lekin da’voga bevosita aloqasi yo‘q; da’voning faqat yarmini ko‘rsatadi; teskari yo‘nalishda ishlaydi (qo‘llash o‘rniga zaiflashtiradi yoki aksincha).","**Tanlangan variantni da’vo bilan yonma-yon o‘qing** va da’voning har bir qismiga mos so‘z yoki g‘oya borligini tekshiring."]},{"type":"example","heading":"Namuna 1: gipotezani qo‘llab-quvvatlovchi topilma","example":{"problem":"Which finding, if true, would most directly support Tursunov''s hypothesis?","passage":"In several cities, great tits (small songbirds) that live near busy roads sing at a higher pitch than great tits living in quiet forests. Biologist Anvar Tursunov hypothesizes that this difference is a response to traffic noise: because the low rumble of cars drowns out low notes, birds that sing higher notes can be heard more easily by other birds. Tursunov plans to test his hypothesis by recording great tits at several locations over the course of a year.","choices":["Great tits living near roads sing more often in the early morning than great tits living in forests do.","When traffic on a road is stopped for several days, great tits near that road begin singing at a lower pitch.","Great tits in quiet forests defend larger territories than great tits living near roads do.","Some bird species that live near busy roads rarely sing at all."],"solution":["**Yo‘nalish:** *support* — gipotezani qo‘llab-quvvatlovchi natija kerak.","**Gipotezani qismlarga ajratamiz:** (1) sabab — transport shovqini; (2) oqibat — qushlar balandroq tovushda sayraydi. Eng kuchli dalil **sabab o‘zgarganda oqibat ham o‘zgarishini** ko‘rsatadi.","**Bashorat:** “Shovqin yo‘qolsa, qushlar pastroq tovushga qaytadi” yoki “shovqin kuchaygan sari tovush balandlashadi”.","**B** — transport to‘xtaganda (shovqin yo‘qolganda) qushlar pastroq tovushda sayray boshlaydi. Bu shovqin bilan tovush balandligi orasidagi bevosita bog‘lanishni ko‘rsatadi. ✓","**A** noto‘g‘ri: gap qushlar **qachon va qanchalik tez-tez** sayrashi haqida, tovush **balandligi** haqida emas. Mavzuga oid, lekin gipotezaga aloqasiz.","**C** noto‘g‘ri: hudud kattaligi shovqin bilan tovush balandligi orasidagi bog‘lanish haqida hech narsa aytmaydi.","**D** noto‘g‘ri: boshqa qush turlarining kam sayrashi great tit qushlarining tovush balandligini tushuntirmaydi."],"answer":"B"}},{"type":"example","heading":"Namuna 2: da’voni ko‘rsatuvchi iqtibos","example":{"problem":"Which quotation from “The Loom” most effectively illustrates the claim?","passage":"“The Loom” is a short poem about a grandmother who weaves carpets in a small village near the city of Bukhara. The speaker describes her quick hands, the bright wool and the buyers who come from the market, but the poem''s deeper interest lies elsewhere. In the poem, the speaker suggests that the grandmother''s weaving connects the family''s past to its future.","choices":["“Her fingers move faster than the morning light / that slips across the dusty floor.”","“She ties her mother''s knots in every row / and leaves a border for a child not born.”","“The market buyers praise the colors bright / and count their coins beside the door.”","“She learned these patterns from her mother''s hands / when she was smaller than the loom is tall.”"],"solution":["**Da’voni qismlarga ajratamiz:** to‘quvchilik oilaning (1) **o‘tmishini** va (2) **kelajagini** bog‘laydi. To‘g‘ri iqtibosda ikkalasi ham bo‘lishi shart.","**B** — *her mother''s knots* (onasining tugunlari) — o‘tmish; *a border for a child not born* (hali tug‘ilmagan bola uchun qoldirilgan hoshiya) — kelajak. Bitta iqtibosda ikkala qism ham bor. ✓","**D** — eng xavfli tuzoq: *learned these patterns from her mother''s hands* o‘tmish bilan bog‘lanishni ko‘rsatadi, lekin **kelajak** haqida hech narsa yo‘q. Da’voning faqat yarmi.","**A** noto‘g‘ri: buvining mahorati va tezligini tasvirlaydi. Matnda tilga olingan bo‘lsa ham (*quick hands*), da’voga aloqasi yo‘q.","**C** noto‘g‘ri: bozor xaridorlari va savdo haqida — avlodlar orasidagi bog‘lanish haqida emas.","**Xulosa:** matnning o‘zi A va C dagi mavzularni eslatib, she’rning “asosiy qiziqishi boshqa joyda” deydi. SAT ataylab mavzuga oid, lekin da’voga mos kelmaydigan iqtiboslarni beradi."],"answer":"B"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Da’voning har bir qismini tekshiring.** Da’voda ikki yoki uch element bo‘lsa (sabab va oqibat, o‘tmish va kelajak, his-tuyg‘u va uning sababi), to‘g‘ri dalil ularning hammasini qamrab oladi.","**Support va weaken ni adashtirmang.** *Weaken, undermine, challenge, cast doubt on* — zaiflashtirish; bunday savolda to‘g‘ri javob gipotezaga **zid** natija bo‘ladi. Savolni o‘qiyotganda bu so‘zni albatta belgilang.","**“If true” — faraz.** Natija sizga g‘alati yoki haqiqatga to‘g‘ri kelmaydigandek tuyulsa ham, uni to‘g‘ri deb qabul qiling. Siz faqat mantiqiy bog‘lanishni baholaysiz.","**“Most directly” — eng bevosita.** Bir nechta variant gipotezaga qandaydir aloqador bo‘lishi mumkin. To‘g‘risi — gipotezadagi aynan o‘sha o‘zgaruvchilarni (masalan, shovqin va tovush balandligi) bog‘laydigan variant.","**She’riy yoki eski ingliz tili qiyin bo‘lsa:** iqtibosning har bir so‘zini tushunishingiz shart emas; notanish so‘zni “X” deb qabul qiling. Da’voning kalit tushunchalarini (o‘tmish va kelajak, qayg‘u va quvonch, tabiat va shahar) iqtiboslardagi ot va fe’llardan qidiring: *mother, ancestors, long ago* → o‘tmish; *not yet born, tomorrow, will* → kelajak.","**Savol so‘zlarini tez tushuning:** *illustrates* — misol bilan ko‘rsatadi; *most directly support* — eng to‘g‘ridan-to‘g‘ri qo‘llab-quvvatlaydi; *finding* — tadqiqot natijasi; *hypothesis* — tekshirilishi kerak bo‘lgan taxmin. Gipoteza matnida *because, so, as a result* kabi sabab-natija so‘zlarini toping — dalil aynan shu bog‘lanishni tasdiqlashi kerak."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Mavzuga oid, da’voga emas:** variant xuddi shu mavzuda (qushlar, gilam), lekin da’voning o‘zini isbotlamaydi (1-namunadagi A, 2-namunadagi A va C).","**Yarim dalil:** da’voning faqat bir qismini ko‘rsatadi (2-namunadagi D).","**Teskari yo‘nalish:** qo‘llab-quvvatlash so‘ralganda zaiflashtiruvchi natija (yoki aksincha). Savoldagi fe’lni diqqat bilan o‘qimagan o‘quvchining eng keng tarqalgan xatosi.","**So‘z o‘xshashligi tuzog‘i:** iqtibosda da’vodagi so‘z (*past*, *family*) takrorlanadi, lekin boshqa ma’noda ishlatilgan. So‘zlarga emas, ma’noga qarang.","**Boshqa shaxsning fikri:** matnda ikki olim bo‘lsa, variant boshqasining gipotezasini qo‘llab-quvvatlashi mumkin. Savol kimning da’vosi haqida ekanini tekshiring.","**Tashqi bilim:** variant hayotda to‘g‘ri bo‘lishi mumkin, lekin gipoteza bilan mantiqiy bog‘lanmagan."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Reading and Writing’da bir savolga o‘rtacha **71 soniya** bor (har modulda 27 savol, 32 daqiqa). Iqtibosli savollarda variantlar uzun, shuning uchun **75–90 soniya** ketishi normal.","Avval da’voni toping va qismlarga ajrating, keyin iqtiboslarni o‘qing. Da’voni bilmasdan to‘rtta she’riy satrni o‘qish — vaqtni isrof qilish.","Iqtiboslarni o‘qiyotganda da’voning birinchi qismini qidiring; uni o‘z ichiga olmagan variantni darhol o‘chiring. Ko‘pincha ikkinchi qismni tekshirish uchun faqat ikkita variant qoladi.","Ikki variant qolib, qaror qila olmasangiz — qaysi biri da’voning **ko‘proq qismini** qamrab olishini tanlang, **Mark for Review** qiling va davom eting."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"claim","meaning":"da’vo — isbotlanishi kerak bo‘lgan fikr"},{"term":"hypothesis","meaning":"gipoteza — tekshirilishi kerak bo‘lgan ilmiy taxmin"},{"term":"finding","meaning":"topilma, tadqiqot natijasi"},{"term":"if true","meaning":"agar to‘g‘ri bo‘lsa — natijani haqiqat deb qabul qiling"},{"term":"support / strengthen","meaning":"qo‘llab-quvvatlamoq / kuchaytirmoq"},{"term":"weaken / undermine","meaning":"zaiflashtirmoq / asosini yemirmoq"},{"term":"illustrate","meaning":"misol bilan ko‘rsatmoq"},{"term":"quotation","meaning":"iqtibos — asardan aynan keltirilgan parcha"},{"term":"most directly","meaning":"eng to‘g‘ridan-to‘g‘ri, eng bevosita"},{"term":"the speaker","meaning":"she’rdagi so‘zlovchi (lirik qahramon) — shoirning o‘zi bo‘lishi shart emas"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Savol qo‘llab-quvvatlashni so‘rayaptimi yoki zaiflashtirishni?","Da’voni qismlarga ajratdimmi va tanlagan dalilim har bir qismni qamrab oladimi?","Dalil gipotezadagi aynan o‘sha sabab va oqibatni bog‘laydimi?","Javobim tashqi bilimga emas, matndagi da’voga tayanadimi?"]}]'::jsonb
from public.guides g where g.slug = 'command-of-evidence-textual'
on conflict (guide_id, locale) do nothing;

