select 'cross-text-connections', 'skill', (select id from public.skills where code = 'cross_text_connections'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'cross_text_connections'), 22, 10, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Cross-Text Connections: ikki matnni bog‘lash', 'Bir mavzudagi ikkita qisqa matnni o‘qib, mualliflar qayerda rozi va qayerda turlicha fikrda ekanini aniqlash: ikkinchi muallif birinchisiga qanday javob berardi va ikkalasi nimada kelishadi.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Cross-Text Connections savollari **Craft and Structure** domeniga kiradi. Sizga bitta mavzu haqida ikkita qisqa matn beriladi — **Text 1** va **Text 2**. Ular odatda turli olimlar, tanqidchilar yoki tarixchilarning qarashlarini ifodalaydi. Savol mualliflar orasidagi **munosabatni** so‘raydi:\n\n- Text 2 muallifi Text 1 dagi da’vo yoki topilmaga **qanday javob berardi?**\n- Ikkala muallif **qaysi fikrga qo‘shiladi?**\n- Text 1 muallifi Text 2 dagi yondashuvni **qanday baholardi?**\n\nMunosabat deyarli hech qachon oddiy “to‘liq rozi” yoki “to‘liq qarshi” bo‘lmaydi. Ko‘pincha Text 2 birinchi matnni **qisman** qabul qiladi, lekin uni cheklaydi, unga yangi omil qo‘shadi yoki u hamma holatga to‘g‘ri kelmasligini ko‘rsatadi. Bu ko‘nikmaning mohiyati — shu nozik farqni ko‘ra bilish."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["Ekranda **Text 1** va **Text 2** sarlavhali ikkita matn — bu turdagi savolning eng aniq belgisi.","*Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1?* — eng ko‘p uchraydigan savol.","*Based on the texts, how would [Text 2 dagi olim] most likely describe the view presented in Text 1?* — ikkinchi muallifning birinchi qarashga bahosi.","*Based on the texts, both authors would most likely agree with which statement?* — ikkala matn ham qo‘llab-quvvatlaydigan fikr.","Javob variantlari ko‘pincha *By arguing that…*, *By agreeing that…*, *By pointing out that…* kabi iboralar bilan boshlanadi — har biri munosabatning bir turini bildiradi."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Savolni birinchi o‘qing va yo‘nalishni belgilang:** kim kimga javob beryapti? *Text 2 → Text 1* va *Text 1 → Text 2* butunlay boshqa javob beradi. Ismlarni ham belgilab oling (Bluebook’dagi **Highlights & Notes** vositasi).","**Text 1 ni o‘qing va asosiy da’vosini bitta o‘zbekcha jumlada ayting:** “Saidov: planshet tushunishni yaxshilaydi”.","**Text 2 ni o‘qing va xuddi shunday qisqa xulosa qiling.** Keyin so‘rang: Text 2 aynan Text 1 ning **qaysi qismiga** tegadi?","**Munosabatni aniqlang:** to‘liq rozi / qisman rozi, lekin cheklaydi / yangi omil qo‘shadi / rad etadi. Text 2 dagi signal so‘zlar (*however, but, only, not enough, also, confirms*) yordam beradi.","**Javobni o‘zingiz bashorat qiling:** “Text 2 muallifi derdi: …, chunki …”.","**Variantlarni chiqarib tashlang:** yo‘nalishi teskari, faqat bitta matnga tegishli, haddan tashqari kuchli yoki ikkala matnda ham yo‘q fikrni o‘chiring."]},{"type":"example","heading":"Namuna 1: Text 2 muallifi qanday javob berardi?","example":{"problem":"Based on the texts, how would Ortiz (Text 2) most likely respond to Saidov''s claim in Text 1?","passage":"**Text 1**\n\nMany schools have replaced printed textbooks with tablets, and supporters say the change improves learning. Digital books can be updated instantly, include videos and quizzes, and spare students from carrying heavy bags. According to education consultant Rahim Saidov, these advantages mean that students who read on screens understand material better than students who read on paper.\n\n**Text 2**\n\nPsychologist Lena Ortiz compared how well students understood the same material in print and on a tablet. For short texts, she found no meaningful difference. For longer and more complex texts, however, students who read on paper answered more comprehension questions correctly. Ortiz suggests that tablets may be useful for some tasks but that schools should not assume screens are always the better choice.","choices":["By agreeing that tablets improve understanding because they include videos and quizzes","By arguing that the claim does not hold for all kinds of reading, especially longer and more complex texts","By insisting that schools should stop using tablets for every classroom task","By pointing out that printed textbooks are too heavy for many students to carry"],"solution":["**Yo‘nalish:** Text 2 (Ortiz) → Text 1 (Saidov). Avval Saidovning da’vosini aniq belgilaymiz.","**Text 1 xulosasi:** Saidov — ekrandan o‘qigan o‘quvchilar materialni qog‘ozdan o‘qiganlarga qaraganda **yaxshiroq** tushunadi.","**Text 2 xulosasi:** Ortiz — qisqa matnlarda farq yo‘q, uzun va murakkab matnlarda esa **qog‘oz** yaxshiroq natija beradi. Planshet ba’zi vazifalar uchun foydali bo‘lishi mumkin.","**Munosabat:** Ortiz Saidovning umumiy da’vosi hamma holatda to‘g‘ri emasligini ko‘rsatadi. U planshetni butunlay rad etmaydi, balki da’voni cheklaydi.","**B** — da’vo hamma turdagi o‘qishga to‘g‘ri kelmaydi, ayniqsa uzun va murakkab matnlarga. Bu Ortizning topilmasiga aynan mos. ✓","**A** noto‘g‘ri — teskari: Ortiz ekran tushunishni yaxshilaydi degan fikrga qo‘shilmaydi; videolar va testlar haqida esa faqat Text 1 gapiradi.","**C** noto‘g‘ri — haddan tashqari kuchli: Ortiz planshetlar *may be useful for some tasks* deydi, ya’ni ulardan butunlay voz kechishni talab qilmaydi.","**D** noto‘g‘ri: og‘ir sumkalar haqida faqat Text 1 gapiradi va bu planshet foydasiga dalil. Ortiz bu masalaga umuman to‘xtalmaydi."],"answer":"B"}},{"type":"example","heading":"Namuna 2: ikkala muallif nimada kelishadi?","example":{"problem":"Based on the texts, Brooks and Nurmatov would most likely agree with which statement?","passage":"**Text 1**\n\nEach spring and fall, millions of migrating birds fly over cities at night. Ornithologist Maya Brooks found that bright lights from tall buildings draw many birds off course, causing them to circle until they are exhausted or to strike windows. Brooks concludes that turning off unnecessary lights during migration seasons is one of the simplest ways for cities to protect birds.\n\n**Text 2**\n\nIn a study of one large city, ecologist Aziz Nurmatov confirmed that dimming building lights during migration reduced the number of injured birds found near those buildings. But he also found that many collisions happen in daylight, when birds see trees and sky reflected in glass and fly toward them. Nurmatov argues that lighting rules alone are not enough: cities should also require glass with patterns that birds can recognize as a solid barrier.","choices":["Reducing building lights during migration seasons can help protect birds.","Most collisions between birds and buildings happen during the daytime.","Patterned glass is the simplest way for cities to protect migrating birds.","Rules about building lights are enough to prevent most bird collisions."],"solution":["**Savol turi:** ikkala muallif ham qo‘shiladigan fikr. To‘g‘ri javob **ikkala** matnda ham asosga ega bo‘lishi shart.","**Text 1 (Brooks):** yorug‘lik qushlarni yo‘ldan ozdiradi; ortiqcha chiroqlarni o‘chirish — qushlarni himoya qilishning eng oddiy usullaridan biri.","**Text 2 (Nurmatov):** chiroqlarni xiralashtirish jarohatlangan qushlar sonini kamaytirgani **tasdiqlandi** (*confirmed*), lekin bu yetarli emas — kunduzgi to‘qnashuvlar ham ko‘p, shuning uchun naqshli oyna ham kerak.","**Umumiy nuqta:** ikkalasi ham chiroqlarni kamaytirish qushlarga yordam berishini qabul qiladi. Farq faqat shundaki, Nurmatov buni yetarli deb hisoblamaydi.","**A** — ikkala matn ham qo‘llab-quvvatlaydi. ✓","**B** noto‘g‘ri: kunduzgi to‘qnashuvlar haqida faqat Text 2 gapiradi, u ham “ko‘p” (*many*) deydi, “ko‘pchilik” (*most*) emas. Brooks esa bu haqida hech narsa demaydi.","**C** noto‘g‘ri: naqshli oyna faqat Text 2 da bor va u “eng oddiy usul” deb atalmagan. Brooks “eng oddiy usullardan biri” deb chiroqlarni o‘chirishni aytadi.","**D** noto‘g‘ri: Nurmatov aynan buning teskarisini aytadi — *lighting rules alone are not enough*."],"answer":"A"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Yo‘nalishni adashtirmang.** *How would the author of Text 1 respond to Text 2?* savolida javob Text 1 muallifining nuqtai nazaridan bo‘ladi, garchi u ikkinchi matnni “ko‘rmagan” bo‘lsa ham. O‘zingizni o‘sha muallif o‘rniga qo‘ying: uning g‘oyalari bilan qaraganda, ikkinchi matn haqida nima derdi?","**Eng ko‘p uchraydigan munosabat — “qisman rozi, lekin…”.** Text 2 ko‘pincha Text 1 ni rad etmaydi, balki uni cheklaydi (*the claim is true only for…*), aniqlashtiradi yoki yangi omil qo‘shadi (*another factor also matters*).","**Ismlarni kuzatib boring.** Ikki matnda 3–4 ta ism bo‘lishi mumkin. Har bir ism qaysi matnda va qaysi fikr bilan bog‘liqligini belgilab qo‘ying.","**“Both would agree” savolida** variant ikkala matnda ham asosga ega bo‘lishi kerak. Faqat bitta matnda aytilgan fikr — garchi o‘zi to‘g‘ri bo‘lsa ham — noto‘g‘ri javob.","**Ingliz tili bo‘yicha maslahat:** Text 2 dagi munosabat so‘zlari — kalit. *confirms, supports, is consistent with* → qo‘shiladi; *however, but, overlooks, fails to consider, underestimates* → e’tiroz; *only, not enough, in some cases* → cheklash. Har bir matndan shu so‘zlarni va asosiy da’voni topa olsangiz, notanish so‘zlar bo‘lsa ham javob bera olasiz — ularni “X” deb qabul qilib o‘qishda davom eting.","**Savol tilini tez tushuning:** *respond to* — javob bermoq, munosabat bildirmoq; *most likely* — matnga asoslanib, ehtimoli eng yuqori; *the view presented in Text 1* — Text 1 da bayon qilingan qarash."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Yo‘nalish almashinuvi:** variant Text 1 muallifining fikrini Text 2 muallifiga (yoki aksincha) taqib qo‘yadi (1-namunadagi D).","**Faqat bitta matnga tegishli:** “both agree” savolida faqat bitta matnda bor fikr (2-namunadagi B va C).","**Haddan tashqari kuchli munosabat:** Text 2 faqat cheklaydi, variant esa “butunlay rad etadi” yoki “hamma joyda to‘xtatish kerak” deydi (1-namunadagi C).","**Teskari munosabat:** Text 2 rozi emas, variant esa “rozi bo‘ladi” deydi (1-namunadagi A).","**Mavzuga oid, lekin matnlarda yo‘q:** hayotda to‘g‘ri bo‘lishi mumkin bo‘lgan, ammo hech bir matnda aytilmagan fikr. SAT faqat matnga asoslangan javobni qabul qiladi.","**So‘zlar mos, ma’no o‘zgargan:** variant matndagi so‘zlarni takrorlaydi, lekin *many* ni *most* ga, *some* ni *all* ga almashtiradi."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Reading and Writing’da bir savolga o‘rtacha **71 soniya** bor (har modulda 27 savol, 32 daqiqa). Ikki matnli savol uzunroq: unga **80–100 soniya** sarflash normal. Bu vaqtni qisqaroq savollarda (masalan, Words in Context) tejaysiz.","Ikkala matnni o‘qib bo‘lgach, har biri uchun bitta qisqa xulosa qiling — keyin variantlarni tekshirishda matnni qayta o‘qishga hojat qolmaydi.","“Both agree” savolida tez yo‘l: har bir variantni avval cheklovchi yoki e’tiroz bildiruvchi matn bilan tekshiring — unga zid variantlar darhol tushib qoladi.","Ikki variant orasida qolsangiz, yaxshiroq ko‘ringanini tanlang, **Mark for Review** bilan belgilang va keyinroq qayting."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"Text 1 / Text 2","meaning":"birinchi va ikkinchi matn"},{"term":"respond to","meaning":"javob bermoq, munosabat bildirmoq"},{"term":"claim","meaning":"da’vo, muallif isbotlamoqchi bo‘lgan fikr"},{"term":"finding(s)","meaning":"topilma, tadqiqot natijasi"},{"term":"view / perspective","meaning":"qarash, nuqtai nazar"},{"term":"qualify","meaning":"(da’voni) cheklamoq, aniqlashtirmoq — to‘liq rad etmasdan"},{"term":"concede / acknowledge","meaning":"(qarshi tomonning biror fikrini) tan olmoq"},{"term":"overlook / fail to consider","meaning":"e’tibordan chetda qoldirmoq, hisobga olmaslik"},{"term":"be consistent with","meaning":"…ga mos kelmoq, …ga zid bo‘lmaslik"},{"term":"most likely","meaning":"ehtimoli eng yuqori — matnga eng ko‘p asoslangan"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Kim kimga javob berayotganini (yo‘nalishni) to‘g‘ri aniqladimmi?","Har ikki matnning asosiy da’vosini bir jumlada ayta olamanmi?","Tanlagan variantim munosabat kuchini (to‘liq yoki qisman) to‘g‘ri aks ettiryaptimi?","“Both agree” bo‘lsa — variant ikkala matnda ham bormi?"]}]'::jsonb
from public.guides g where g.slug = 'cross-text-connections'
on conflict (guide_id, locale) do nothing;

-- desmos-calculator-strategies
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'desmos-calculator-strategies', 'strategy', null, (select id from public.subjects where code = 'math'), 5, 10, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Desmos kalkulyatori: tezkor strategiyalar', 'Grafik kalkulyator yordamida tenglamalarni ikkala tomonni chizib yechish, sistemalarda kesishish nuqtasini topish, kvadrat funksiyaning uchi va nollarini aniqlash, jadvaldan regressiya, o‘zgarmaslar uchun slayder, ekvivalent ifodalarni tekshirish — va Desmos’ni qachon ishlatmaslik kerakligi.', '[{"type":"concept","heading":"Nega Desmos’ni o‘rganish kerak","body":"Bluebook ilovasida Math bo‘limi davomida Desmos kalkulyatori (grafik va ilmiy rejimlar) ochiq. Grafik rejim ko‘plab algebra savollarini 20–40 soniyada **ko‘rib** yechish imkonini beradi: tenglama, sistema, kvadrat funksiya, jadval ma’lumotlari.\n\nLekin Desmos — vosita, fikrlash o‘rnini bosmaydi. U tenglamani siz uchun **tuzib** bermaydi va noto‘g‘ri kiritilgan ifodaga noto‘g‘ri javob beradi. Eng yaxshi natija: algebrani bilish + Desmos’ni qachon ishlatishni bilish.\n\nSAT MASTER’da mashq, diagnostika va sinov imtihonlarining Math savollarida **Kalkulyator** tugmasi bor — bu usullarni har kuni o‘sha yerda mashq qiling."},{"type":"method","heading":"Asosiy ko‘nikmalar: avval shularni o‘rganing","steps":["**Har bir qatorga bitta ifoda.** Funksiyani $y = 3x - 5$ ko‘rinishida yozing — Desmos darhol grafigini chizadi.","**Maxsus nuqtalarni bosing.** Grafikni bossangiz, kulrang nuqtalar paydo bo‘ladi: o‘qlar bilan kesishish, boshqa grafik bilan kesishish, eng katta yoki eng kichik qiymat. Nuqtani bosib, koordinatasini ko‘rasiz.","**Masshtabni o‘zgartiring.** Grafik ko‘rinmasa yoki kesishish ekrandan tashqarida bo‘lsa, kattalashtirish/kichiklashtirish tugmalari bilan uzoqlashtiring.","**Funksiya qiymatini hisoblang.** $f(x) = x^2 - 4x$ deb yozing, keyingi qatorga $f(7)$ — natija darhol chiqadi.","**O‘zgaruvchilarni moslang.** Grafik o‘qlari $x$ va $y$. Savolda $t$, $n$ yoki $p$ bo‘lsa, uni $x$ bilan almashtiring. Boshqa harflar Desmos uchun noma’lum o‘zgarmas (slayder) hisoblanadi."]},{"type":"method","heading":"1-usul: tenglamani ikkala tomonni chizib yechish","steps":["Tenglamaning chap tomonini $y = \\ldots$ deb bir qatorga, o‘ng tomonini $y = \\ldots$ deb ikkinchi qatorga yozing.","Ikki grafikning **kesishish nuqtasi**ni bosing: uning $x$-koordinatasi — tenglamaning yechimi.","Bir nechta kesishish — bir nechta yechim; umuman kesishmasa — yechim yo‘q.","Muqobil yo‘l: $y = (\\text{chap tomon}) - (\\text{o‘ng tomon})$ deb bitta grafik chizing va uning $x$-o‘qi bilan kesishishlarini toping.","Savol $x$ ni emas, boshqa narsani (masalan, $2x + 1$) so‘rasa, topilgan qiymatni qo‘yib hisoblang."]},{"type":"example","heading":"Namuna 1: tenglamani grafik bilan yechish","example":{"problem":"$$\\frac{3x}{2} - 4 = \\frac{x + 6}{4}$$ What value of $x$ is the solution to the given equation?","solution":["Desmos’ga ikki qator yozamiz: $y = \\frac{3x}{2} - 4$ va $y = \\frac{x + 6}{4}$.","Ikki to‘g‘ri chiziq bitta nuqtada kesishadi. Nuqtani bosamiz: $(4.4,\\ 2.6)$.","Savol $x$ ni so‘rayapti, demak javob $4.4$.","Algebraik tekshiruv: ikkala tomonni 4 ga ko‘paytiramiz — $6x - 16 = x + 6$, bundan $5x = 22$, $x = 4.4$ ✓.","Javobni **4.4** yoki **22/5** deb kiritish mumkin."],"answer":"4.4 (yoki 22/5)"}},{"type":"method","heading":"2-usul: tenglamalar sistemasi — kesishish nuqtasi","steps":["Ikkala tenglamani **qanday berilgan bo‘lsa, shunday** kiriting: $2x + 3y = 12$ ni $y$ ga keltirish shart emas, Desmos uni o‘zi chizadi.","Kesishish nuqtasini bosing — u sistemaning yechimi $(x, y)$. Masalan, $2x + 3y = 12$ va $x - y = 1$ uchun nuqta $(3, 2)$.","Savol $x + y$, $xy$ yoki $\\frac{x}{y}$ ni so‘rasa — koordinatalardan hisoblang.","Chiziqlar **parallel** bo‘lsa — yechim yo‘q (*no solution*); **ustma-ust** tushsa — cheksiz ko‘p yechim (*infinitely many solutions*)."]},{"type":"method","heading":"3-usul: kvadrat funksiya — uchi va nollari","steps":["Funksiyani yozing, masalan $y = 2x^2 - 8x + 3$.","Grafikni bosing: **uchi** (*vertex*) — parabolaning eng past yoki eng baland nuqtasi, bu yerda $(2, -5)$.","**Nollari** (*zeros*, *x-intercepts*, *roots*) — $x$-o‘qi bilan kesishish nuqtalari: bu yerda taxminan $0.419$ va $3.581$.","$y$-o‘qi bilan kesishish (*y-intercept*) — $(0, 3)$.","Variantlar ildiz ko‘rinishida bo‘lsa (masalan, $2 + \\frac{\\sqrt{10}}{2}$), ularni Desmos’ning yangi qatoriga yozib o‘nli qiymatini ko‘ring va grafikdagi son bilan solishtiring.","**Nechta haqiqiy yechim bor?** Grafik $x$-o‘qini necha marta kesishini sanang: 2, 1 (faqat tegib o‘tadi) yoki 0."]},{"type":"method","heading":"4-usul: jadvaldan regressiya","steps":["**+** tugmasi orqali jadval (*table*) qo‘shing va ma’lumotlarni $x_1$, $y_1$ ustunlariga kiriting.","Chiziqli model uchun yangi qatorga $y_1 \\sim mx_1 + b$ deb yozing (to‘lqin belgisi $\\sim$ — “taxminan teng”). Desmos $m$, $b$ qiymatlarini va moslik ko‘rsatkichi $r^2$ ni chiqaradi.","Kvadrat model: $y_1 \\sim ax_1^2 + bx_1 + c$; eksponensial model: $y_1 \\sim a \\cdot b^{x_1}$.","Topilgan koeffitsiyentlarni variantlar bilan solishtiring. Masalan, $x$: 1, 2, 3, 4 va $y$: 5, 8, 11, 14 uchun $m = 3$, $b = 2$, $r^2 = 1$ — demak, aniq $y = 3x + 2$.","Ma’lumotlar to‘g‘ri chiziqda yotmasa ham (*line of best fit*), regressiya eng mos tenglamani beradi — variantlardan unga eng yaqinini tanlang."]},{"type":"method","heading":"5-usul: slayder bilan noma’lum o‘zgarmasni topish","steps":["Savoldagi tenglamani o‘zgarmasi bilan birga yozing, masalan $y = x^2 - 6x + c$. Desmos $c$ uchun slayder qo‘shishni taklif qiladi (*add slider*) — bosing.","Slayderni suring va grafikni kuzating. Savol “parabola $x$-o‘qiga aynan bir nuqtada tegsin” desa, shu holatni toping: $c = 9$.","Variantlar berilgan bo‘lsa, ularning qiymatlarini slayder raqamiga birma-bir yozing — taxminiy surishdan ko‘ra aniqroq.","Slayder ko‘pincha tekshirish uchun eng yaxshi: algebraik shartni (masalan, qiyaliklar tengligi yoki diskriminant nolga tengligi) bilsangiz, avval shuni qo‘llang."]},{"type":"example","heading":"Namuna 2: slayder bilan sistemani tekshirish","example":{"problem":"In the given system of equations, $k$ is a constant.\n$y = kx - 3$\n$y = -\\frac{2}{5}x + 7$\nFor what value of $k$ does the system have no solution?","choices":["$-\\frac{5}{2}$","$-\\frac{2}{5}$","$\\frac{2}{5}$","$\\frac{5}{2}$"],"solution":["Ikkala tenglamani Desmos’ga yozamiz va $k$ uchun slayder qo‘shamiz.","Yechim yo‘q — demak, chiziqlar kesishmaydi, ya’ni parallel. Variantlardagi qiymatlarni slayder raqamiga yozib ko‘ramiz: faqat $k = -0.4$ da chiziqlar parallel bo‘ladi.","Algebraik tasdiq: parallel chiziqlarning qiyaliklari teng, ozod hadlari esa har xil. Qiyaliklar: $k = -\\frac{2}{5}$; ozod hadlar $-3 \\neq 7$ ✓.","Tuzoqlar: **$\\frac{2}{5}$** — ishorani unutish; **$-\\frac{5}{2}$** — kasrni ag‘darib yuborish; **$\\frac{5}{2}$** — perpendikulyar chiziqning qiyaligi (bunda chiziqlar kesishadi, ya’ni yechim bor)."],"answer":"B) $-\\frac{2}{5}$"}},{"type":"method","heading":"6-usul: ekvivalent ifodalarni tekshirish","steps":["Savoldagi ifodani $y = \\ldots$ deb yozing, masalan $y = (x + 4)^2 - 9$.","Har bir variantni ham alohida qatorga $y = \\ldots$ deb yozing va ranglariga qarang.","Grafigi savoldagi grafik bilan **to‘liq ustma-ust** tushgan variant — ekvivalent. Bu misolda $y = (x + 1)(x + 7)$.","Grafiklar juda yaqin ko‘rinsa, ikki-uch nuqtada qiymatlarni solishtiring (masalan, jadvalda $x = 0$, $x = 2$, $x = 5$) — yaqin, lekin bir xil bo‘lmagan grafiklar ham bo‘ladi."]},{"type":"note","heading":"Boshqa foydali buyruqlar","items":["**Statistika:** ro‘yxat tuzing, masalan $L = [3, 7, 8, 12, 15]$, so‘ng $\\text{mean}(L)$, $\\text{median}(L)$, $\\text{min}(L)$, $\\text{max}(L)$ — o‘rtacha, mediana, eng kichik va eng katta qiymat.","**Tengsizliklar:** $y > 2x - 1$ yozsangiz, yechimlar sohasi bo‘yaladi. “Qaysi nuqta yechim?” savolida nuqtani, masalan $(3, 4)$ ni yozing va u bo‘yalgan sohada ekanini tekshiring.","**Aylana:** $(x - 2)^2 + (y + 1)^2 = 25$ kabi tenglamani yozsangiz, aylanani ko‘rasiz — markaz va radius haqidagi variantlarni tekshirishga yordam beradi.","**Trigonometriya:** Desmos odatda radianlarda ishlaydi. Burchak gradusda berilsa, sozlamalardan (*Degrees*) gradus rejimini yoqing — aks holda $\\sin(30)$ noto‘g‘ri chiqadi."]},{"type":"watch_out","heading":"Desmos’ni qachon ishlatmaslik kerak","items":["**Oddiy hisob:** 2–3 qadamli arifmetika yoki $3x + 5 = 20$ kabi tenglamani qo‘lda yechish tezroq.","**Tushunchaga oid savollar:** “ifodadagi 12 soni nimani anglatadi?”, “qaysi tasdiq doim to‘g‘ri?” — grafik bunga javob bermaydi.","**Faqat harflardan iborat ifodalar:** variantlarda $a$, $b$, $c$ hammasi harf bo‘lsa, grafik chizish qiyin — son tanlash usuli tezroq.","**Geometriya:** burchaklar, o‘xshash uchburchaklar, yuzalar — chizma va formulalar bilan ishlang.","**Matnli masalada tenglama tuzish:** Desmos tenglamani tuzmaydi. Avval tenglamani o‘zingiz tuzing, keyin kerak bo‘lsa Desmos’da yeching.","**30 soniya qoidasi:** 30 soniyada grafik kerakli javobni bermasa, algebraga qayting."]},{"type":"traps","heading":"Desmos bilan keng tarqalgan xatolar","items":["**Kasrni noto‘g‘ri kiritish:** “1/2x” deb yozsangiz, Desmos $\\frac{1}{2x}$ hosil qiladi. $\\frac{1}{2}x$ uchun 2 dan keyin o‘ng strelka bilan maxrajdan chiqing.","**Daraja ko‘rsatkichi:** $2^{x} + 1$ yozish uchun daraja ichidan o‘ng strelka bilan chiqing, aks holda $2^{x+1}$ bo‘lib qoladi.","**Qavslar:** $-x^2$ va $(-x)^2$ — har xil narsa. Manfiy sonni darajaga ko‘targanda qavsni unutmang.","**Yaxlitlangan qiymat:** Desmos $0.333$ ko‘rsatadi, aniq javob esa $\\frac{1}{3}$. Javobni yozadigan savollarda kasrni kiriting yoki maydonga sig‘adigan barcha raqamlarni yozing.","**Noto‘g‘ri koordinata:** kesishish nuqtasining $x$ ini topib, savol $y$ ni so‘raganini unutish.","**Gradus/radian:** trigonometrik hisobda rejimni tekshirmaslik."]},{"type":"checklist","heading":"Desmos’ni ochishdan oldin","items":["Bu savolda grafik haqiqatan vaqt tejaydimi?","O‘zgaruvchilarni $x$ va $y$ ga almashtirdimmi?","Kasr, daraja va qavslar to‘g‘ri kiritildimi?","Topgan qiymatim — savol so‘ragan kattalikmi?"]}]'::jsonb
from public.guides g where g.slug = 'desmos-calculator-strategies'
on conflict (guide_id, locale) do nothing;

-- digital-sat-format
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'digital-sat-format', 'strategy', null, null, 2, 9, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Digital SAT formati: tuzilishi, vaqti va baholanishi', 'Digital SAT qanday tuzilgan: ikki bo‘lim, to‘rt modul, 98 ta savol va 2 soat 14 daqiqa. Moslashuvchan (adaptive) ikkinchi modul nimani anglatadi, ball qanday hisoblanadi, pretest savollar nima va bularning barchasi strategiyangizga qanday ta’sir qiladi.', '[{"type":"concept","heading":"Test bir qarashda","body":"Digital SAT kompyuter yoki planshetda, College Board’ning **Bluebook** ilovasida topshiriladi. Test ikki bo‘limdan iborat: avval **Reading and Writing** (O‘qish va yozish), keyin **Math** (Matematika). Har bir bo‘lim ikkita teng **modul**ga bo‘lingan va har bir modul alohida vaqtlanadi.\n\n- **Reading and Writing:** 54 ta savol, 64 daqiqa — 2 ta modul, har birida 27 ta savol va 32 daqiqa.\n- **Math:** 44 ta savol, 70 daqiqa — 2 ta modul, har birida 22 ta savol va 35 daqiqa.\n- **Tanaffus:** ikki bo‘lim orasida 10 daqiqa.\n- **Jami:** 98 ta savol, 134 daqiqa (2 soat 14 daqiqa), tanaffus bunga kirmaydi."},{"type":"time","heading":"Har bir savolga qancha vaqt to‘g‘ri keladi","items":["**Reading and Writing:** 32 daqiqa ÷ 27 ta savol — har bir savolga o‘rtacha **≈71 soniya**.","**Math:** 35 daqiqa ÷ 22 ta savol — har bir savolga o‘rtacha **≈95 soniya**.","Bu — o‘rtacha qiymat. Oson savollarda vaqt tejab, uni qiyin savollarga qoldirasiz. Batafsil — “Vaqtni boshqarish va taxmin qilish” qo‘llanmasida."]},{"type":"concept","heading":"Reading and Writing bo‘limida nima bor","body":"Har bir savol bitta qisqa matn (25–150 so‘z) yoki bir juft matndan iborat, ba’zan jadval yoki grafik bilan. **Har bir matnga faqat bitta savol** beriladi. Barcha savollar — to‘rt variantli test, har birining bitta eng to‘g‘ri javobi bor. Matnlar adabiyot, tarix va ijtimoiy fanlar, gumanitar fanlar va tabiiy fanlardan olinadi.\n\nTo‘rtta yo‘nalish (domain) va ularning taxminiy ulushi:\n\n- **Craft and Structure** — ≈28%, 13–15 ta savol: so‘zning kontekstdagi ma’nosi, matn tuzilishi va maqsadi, ikki matn orasidagi bog‘liqlik.\n- **Information and Ideas** — ≈26%, 12–14 ta savol: asosiy g‘oya va tafsilotlar, matn va jadval/grafikdan dalil, xulosa chiqarish.\n- **Standard English Conventions** — ≈26%, 11–15 ta savol: gap tuzilishi, tinish belgilari, so‘z shakllari.\n- **Expression of Ideas** — ≈20%, 8–12 ta savol: bog‘lovchi so‘zlar (transitions) va eslatmalardan maqsadga mos gap tuzish."},{"type":"concept","heading":"Math bo‘limida nima bor","body":"Math savollarining taxminan **75%** i to‘rt variantli test, taxminan **25%** ida esa javobni o‘zingiz yozasiz (*student-produced response*, SPR). Savollarning taxminan 30% i hayotiy vaziyat (kontekst) asosida tuzilgan.\n\nTo‘rtta yo‘nalish (har bir yo‘nalishdagi baholanadigan savollar soni):\n\n- **Algebra** — 13–15 ta savol.\n- **Advanced Math** — 13–15 ta savol.\n- **Problem-Solving and Data Analysis** — 5–7 ta savol.\n- **Geometry and Trigonometry** — 5–7 ta savol.\n\nKalkulyatordan **butun Math bo‘limi davomida** foydalanish mumkin: Bluebook’da Desmos kalkulyatori (grafik va ilmiy rejimlar) o‘rnatilgan, ruxsat etilgan o‘z kalkulyatoringizni ham olib kelish mumkin. Formulalar ma’lumotnomasi (reference sheet) va ko‘rsatmalar test davomida ochiq. Reading and Writing bo‘limida kalkulyator yo‘q."},{"type":"concept","heading":"Savollar qanday tartibda keladi","items":["**Reading and Writing:** har bir modulda to‘rttala yo‘nalish bor va ular shu tartibda keladi: Craft and Structure → Information and Ideas → Standard English Conventions → Expression of Ideas. O‘xshash ko‘nikmani tekshiradigan savollar birga guruhlangan va guruh ichida **osondan qiyinga** joylashgan. Standard English Conventions savollari qaysi qoida tekshirilishidan qat’i nazar osondan qiyinga tartiblangan.","**Math:** har bir modulda savollar boshidan oxirigacha **osondan qiyinga** joylashgan, mavzular esa aralash keladi.","**Modul ichida erkin harakatlanasiz:** oldinga o‘tib keyingi savollarni ko‘rishingiz, belgilangan savollarga qaytishingiz mumkin.","**Modulga qaytib bo‘lmaydi:** modulni topshirganingizdan yoki vaqt tugaganidan keyin unga qaytish imkoni yo‘q. Taymer nolga yetganda ilova sizni avtomatik ravishda keyingi qismga o‘tkazadi."]},{"type":"concept","heading":"“Adaptive” (moslashuvchan) test nima","body":"Digital SAT — **modul darajasida moslashuvchan** test. Har bir bo‘limning 1-modulida oson, o‘rta va qiyin savollar aralash beriladi. 1-moduldagi natijangizga qarab ikkinchi modul o‘rtacha hisobda **qiyinroq** yoki **osonroq** savollar to‘plamidan iborat bo‘ladi.\n\nMoslashuv har bir savoldan keyin emas, faqat modul tugaganda sodir bo‘ladi. Shuning uchun modul ichida savollarni o‘tkazib yuborish, belgilash va qaytish mumkin.\n\nBo‘lim bali **ikkala moduldagi** javoblaringiz asosida hisoblanadi. College Board Item Response Theory (IRT) usulidan foydalanadi: bir xil sondagi to‘g‘ri javob har xil ball berishi mumkin, chunki to‘g‘ri javob berilgan savollarning qiyinligi va boshqa xususiyatlari ham hisobga olinadi."},{"type":"watch_out","heading":"Moslashuvchanlik strategiyaga qanday ta’sir qiladi","items":["**1-modul hal qiluvchi:** u qaysi 2-modulni olishingizni belgilaydi. College Board tushuntirishicha, 1-modulda bir nechta savolda xato qilsangiz, 2-modulni to‘liq to‘g‘ri ishlasangiz ham bo‘lim bo‘yicha 800 olish mumkin bo‘lmaydi. Shuning uchun 1-moduldagi oson savollarda shoshilmang va e’tiborsizlik xatosiga yo‘l qo‘ymang.","**2-modul qiyin tuyulsa, vahimaga tushmang:** bu 1-modulni yaxshi ishlaganingiz belgisi bo‘lishi mumkin. Qaysi modulni olganingizni taxmin qilishga vaqt sarflamang — har bir savolni o‘z holicha ishlang.","**Har bir savolga javob bering:** hatto eng qiyin oxirgi savollar ham, chunki noto‘g‘ri javob uchun ball ayirilmaydi.","**Modulni topshirishdan oldin tekshiring:** keyin qaytib bo‘lmaydi. Belgilangan va javobsiz savollarni savollar menyusida ko‘ring.","**Ikkala bo‘limga ham kuch qoldiring:** Math bo‘limi uzun o‘qishdan keyin boshlanadi — 10 daqiqalik tanaffusdan dam olish uchun foydalaning."]},{"type":"concept","heading":"Ball qanday hisoblanadi","items":["**Umumiy ball 400–1600:** ikki bo‘lim ballari yig‘indisi. Har bir bo‘lim 200–800 oralig‘ida, 10 ballik qadam bilan baholanadi.","**Noto‘g‘ri javob uchun jarima yo‘q:** College Board savolni bo‘sh qoldirgandan ko‘ra taxmin qilish yaxshiroq ekanini ta’kidlaydi, ayniqsa bir-ikki variantni chiqarib tashlay olsangiz.","**Pretest savollar:** har bir modulda 2 ta pretest (sinov) savol bor — ular ballga ta’sir qilmaydi va College Board ularni yangi savollarni sinash uchun qo‘shadi. Ular boshqa savollardan farqlanmaydi, demak qaysi biri pretest ekanini bilolmaysiz. Shunday qilib, Reading and Writing modulida 25 ta, Math modulida 20 ta savol ballga hisoblanadi.","**Ball shunchaki to‘g‘ri javoblar soni emas:** IRT tufayli savollarning qiyinligi ham hisobga olinadi. Shu sabab internetdagi “X ta xato = Y ball” jadvallariga to‘liq ishonmang."]},{"type":"note","heading":"Bluebook va test qoidalari haqida","items":["Vaqtni Bluebook ilovasi har bir o‘quvchi uchun alohida hisoblaydi va rejalashtirilgan tanaffus boshlanganini o‘zi bildiradi.","Rejadan tashqari tanaffus olish mumkin, lekin bunda test vaqtingizni yo‘qotasiz.","Testdagi vositalar (taymer, belgilash, variantlarni o‘chirish, kalkulyator va boshqalar) haqida — “Test ilovasidagi vositalar” qo‘llanmasida.","Ro‘yxatdan o‘tish, test sanalari, narxlar va test markazlari haqidagi ma’lumot o‘zgarib turadi — ularni faqat College Board’ning rasmiy saytidan (satsuite.collegeboard.org) tekshiring."]},{"type":"note","heading":"SAT MASTER sinov imtihonlari shu formatni qanday takrorlaydi","items":["To‘liq sinov imtihoni xuddi shu tuzilishda: har bir bo‘limda 2 ta modul, moslashuvchan 2-modul va bo‘limlar orasida ixtiyoriy 10 daqiqalik tanaffus.","2-modulga yo‘naltirish SAT MASTER’ning o‘z chegara qoidasi asosida bo‘ladi va natijalar sahifasida ochiq tushuntiriladi.","Taxminiy ball oralig‘i SAT MASTER’ning ochiq formulasi bilan hisoblanadi. Rasmiy baholashda bizda mavjud bo‘lmagan statistik modellar qo‘llanadi, shuning uchun bu ball rasmiy emas — uni mashq signali sifatida qabul qiling."]},{"type":"note","heading":"SAT MASTER va College Board","body":"SAT® — College Board’ning ro‘yxatdan o‘tgan savdo belgisi. SAT MASTER — mustaqil platforma: College Board bilan bog‘liq emas va u tomonidan qo‘llab-quvvatlanmaydi. Platformadagi barcha mashq savollari original, ya’ni SAT MASTER muharrirlari tomonidan yozilgan. Bu qo‘llanmadagi format haqidagi ma’lumotlar College Board’ning rasmiy sahifalari asosida tayyorlangan; o‘zgarishlar bo‘lsa, rasmiy manba ustun turadi."},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"section","meaning":"bo‘lim: Reading and Writing yoki Math"},{"term":"module","meaning":"modul — bo‘limning alohida vaqtlanadigan yarmi"},{"term":"adaptive","meaning":"moslashuvchan: 2-modul 1-moduldagi natijangizga qarab tanlanadi"},{"term":"operational question","meaning":"ballga hisoblanadigan savol"},{"term":"pretest question","meaning":"sinov savoli — ballga ta’sir qilmaydi, lekin boshqalardan farqlanmaydi"},{"term":"section score","meaning":"bo‘lim bali, 200–800"},{"term":"total score","meaning":"umumiy ball, 400–1600"},{"term":"multiple-choice","meaning":"variantli savol (A–D)"},{"term":"student-produced response (SPR)","meaning":"javobni o‘zingiz yozadigan Math savoli"},{"term":"passage","meaning":"matn — Reading and Writing savolidagi qisqa parcha"},{"term":"reference sheet","meaning":"formulalar ma’lumotnomasi (Math bo‘limida)"},{"term":"break","meaning":"tanaffus — bo‘limlar orasida 10 daqiqa"}]},{"type":"checklist","heading":"Formatdan yodda tutish kerak bo‘lgan asosiy faktlar","items":["RW: 2 × 27 savol, 2 × 32 daqiqa; Math: 2 × 22 savol, 2 × 35 daqiqa; orada 10 daqiqa tanaffus.","O‘rtacha: RW’da ≈71 soniya, Math’da ≈95 soniya bir savolga.","Noto‘g‘ri javob uchun jarima yo‘q — hech bir savolni bo‘sh qoldirmang.","1-modulda aniqlik — eng muhim narsa.","Modulni topshirgach, unga qaytib bo‘lmaydi."]}]'::jsonb
from public.guides g where g.slug = 'digital-sat-format'
on conflict (guide_id, locale) do nothing;

-- english-for-the-sat
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'english-for-the-sat', 'strategy', null, (select id from public.subjects where code = 'reading_writing'), 10, 10, 'draft'
