insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'equivalent-expressions', 'skill', (select id from public.skills where code = 'equivalent_expressions'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'equivalent_expressions'), 8, 10, 'draft'
