insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Ekvivalent ifodalar', 'Ifodalarni qavslarni ochish, ko‘paytuvchilarga ajratish, daraja qoidalari va kasrlar yordamida qayta yozish; “for all values of x” savollarida koeffitsiyentlarni tenglashtirish va javobni son qo‘yib tekshirish.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Ikki ifoda **ekvivalent** (aynan teng) deyiladi, agar ular $x$ ning **har qanday** ruxsat etilgan qiymatida bir xil son bersa. Masalan, $2(x + 3)$ va $2x + 6$ ekvivalent. SAT sizdan ifodani boshqa shaklda — odatda javob variantlaridagi ko‘rinishda — qayta yozishni so‘raydi.\n\nAsosiy vositalar:\n\n- **Qavslarni ochish va o‘xshash hadlarni ixchamlash:** $(2x + 3)(x - 4) = 2x^2 - 5x - 12$.\n- **Qisqa ko‘paytirish formulalari:** $(a + b)^2 = a^2 + 2ab + b^2$, $(a - b)^2 = a^2 - 2ab + b^2$, $a^2 - b^2 = (a - b)(a + b)$.\n- **Ko‘paytuvchilarga ajratish:** umumiy ko‘paytuvchini qavsdan tashqariga chiqarish, $x^2 + bx + c$ ni ikki qavsga ajratish.\n- **Daraja qoidalari:** $x^m \\cdot x^n = x^{m + n}$, $\\frac{x^m}{x^n} = x^{m - n}$, $(x^m)^n = x^{mn}$, $x^{-n} = \\frac{1}{x^n}$, $x^{m/n} = \\sqrt[n]{x^m}$.\n- **Kasrli ifodalar:** umumiy maxrajga keltirish; faqat **ko‘paytuvchilarni** qisqartirish mumkin, qo‘shiluvchilarni emas.\n\n**“For all values of x” qoidasi:** ikki ko‘phad $x$ ning barcha qiymatlarida teng bo‘lsa, ularning mos koeffitsiyentlari ham teng. Masalan, $ax^2 + bx + c = 6x^2 - 7x + 2$ bo‘lsa, $a = 6$, $b = -7$, $c = 2$.\n\nFormulani biror harfga nisbatan qayta yozish (*“in terms of”*) ham shu mantiqqa tayanadi: ikkala tomonga bir xil amalni qo‘llab, kerakli harfni yolg‘iz qoldirasiz."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["*“Which of the following is equivalent to …?”* — eng ko‘p uchraydigan shakl; variantlar odatda bir-biriga juda o‘xshaydi.","*“… for all values of x, where a and b are constants. What is the value of b?”* — koeffitsiyentlarni tenglashtirish.","*“where x > 0”* yoki *“x ≠ 3”* kabi shart bor — ildizlar, kasr darajalar yoki kasrli ifoda bilan ishlayapsiz.","Variantlarda kasr daraja yoki ildiz bor — daraja qoidalari savoli.","*“The expression … can be rewritten as …”* — ifodani berilgan shaklga keltirish.","*“Which equation correctly expresses r in terms of V and h?”* — formulani kerakli harfga nisbatan qayta yozish."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Avval variantlarga qarang:** ular qaysi shaklda — qavslar ochilganmi, ko‘paytuvchilarga ajratilganmi, daraja ko‘rinishidami? Berilgan ifodani aynan o‘sha shaklga olib boring.","**Qavslarni ehtiyotkorlik bilan oching:** har bir hadni har biriga ko‘paytiring; qavs oldidagi minus ichidagi **barcha** ishoralarni o‘zgartiradi.","**Qisqa ko‘paytirish formulalarini taniy oling:** $9x^2 - 25$ — kvadratlar ayirmasi, $x^2 + 10x + 25$ — to‘liq kvadrat.","**Daraja va ildizlarda** hammasini $x^{\\text{son}}$ ko‘rinishiga o‘tkazing, ko‘rsatkichlarni qo‘shing yoki ayiring, oxirida kerakli shaklga qaytaring.","**“For all values of x” savolida** ikkala tomonni to‘liq oching va $x^2$, $x$ hamda ozod had koeffitsiyentlarini alohida-alohida tenglashtiring.","**Son qo‘yib tekshiring:** $x = 2$ yoki $x = 3$ ni (0 va 1 ni emas — ular ko‘p ifodalarni bir xil qilib qo‘yadi) berilgan ifodaga va variantlarga qo‘ying. Faqat ekvivalent variant bir xil natija beradi."]},{"type":"example","heading":"Namuna 1: qavslarni ochish","example":{"problem":"Which expression is equivalent to $(3x - 2)^2 - (x + 4)(x - 4)$?","choices":["$8x^2 - 12x + 20$","$8x^2 + 20$","$8x^2 - 12x - 12$","$8x^2 - 6x + 20$"],"solution":["Birinchi qism — to‘liq kvadrat: $(3x - 2)^2 = 9x^2 - 12x + 4$ (o‘rta had: $2 \\cdot 3x \\cdot 2 = 12x$).","Ikkinchi qism — kvadratlar ayirmasi: $(x + 4)(x - 4) = x^2 - 16$.","Ayiramiz; minus qavsning **ikkala** hadiga ta’sir qiladi: $9x^2 - 12x + 4 - x^2 + 16 = 8x^2 - 12x + 20$.","Son qo‘yib tekshiruv ($x = 2$): berilgan ifoda $4^2 - 6 \\cdot (-2) = 16 + 12 = 28$; **A**: $32 - 24 + 20 = 28$ ✓.","Tuzoqlar: **B** — $(3x - 2)^2$ ni $9x^2 + 4$ deb, o‘rta hadni unutish ($x = 2$ da 52 chiqadi). **C** — minusni faqat birinchi hadga tarqatish: $-x^2 - 16$ ($x = 2$ da $-4$). **D** — o‘rta haddagi 2 ko‘paytuvchisini unutish: $-6x$ ($x = 2$ da 40)."],"answer":"A) $8x^2 - 12x + 20$"}},{"type":"example","heading":"Namuna 2: koeffitsiyentlarni tenglashtirish","example":{"problem":"$$(ax + 5)(3x - 2) = 12x^2 + bx - 10$$\n\nIn the given equation, $a$ and $b$ are constants, and the equation is true for all values of $x$. What is the value of $b$?","solution":["Chap tomonni ochamiz: $3ax^2 - 2ax + 15x - 10 = 3ax^2 + (15 - 2a)x - 10$.","Mos koeffitsiyentlarni tenglashtiramiz. $x^2$ oldida: $3a = 12$, demak $a = 4$.","$x$ oldida: $b = 15 - 2a = 15 - 8 = 7$.","Ozod hadlar: $-10 = -10$ ✓ — shartlar bir-biriga zid emas.","Tekshiruv: $(4x + 5)(3x - 2) = 12x^2 - 8x + 15x - 10 = 12x^2 + 7x - 10$ ✓.","Tuzoqlar: $a = 4$ ni javob qilish — savol $b$ ni so‘rayapti. Yoki $-2a$ ni $+2a$ deb olib, $b = 23$ ni hosil qilish. Javob: **7**."],"answer":"7"}},{"type":"example","heading":"Namuna 3: daraja va ildizlar","example":{"problem":"Which of the following is equivalent to $\\dfrac{x^2 \\sqrt[3]{x^2}}{x^{1/3}}$, where $x > 0$?","choices":["$x$","$x^2 \\sqrt[3]{x}$","$x^{19/6}$","$x^3$"],"solution":["Hammasini daraja ko‘rinishiga o‘tkazamiz: $\\sqrt[3]{x^2} = x^{2/3}$ (ildiz ko‘rsatkichi maxrajga tushadi).","Suratda ko‘paytirish — ko‘rsatkichlar qo‘shiladi: $x^2 \\cdot x^{2/3} = x^{8/3}$.","Bo‘lish — ko‘rsatkichlar ayiriladi: $x^{8/3 - 1/3} = x^{7/3}$.","Variantlarda $x^{7/3}$ yo‘q, shuning uchun uni qayta yozamiz: $x^{7/3} = x^{6/3} \\cdot x^{1/3} = x^2 \\sqrt[3]{x}$ — bu **B**.","Tuzoqlar: **C** ($x^{19/6}$) — ildizni teskari o‘girib, $x^{3/2}$ deb yozish. **D** ($x^3$) — maxrajdagi ko‘rsatkichni ayirish o‘rniga qo‘shish. **A** ($x$) — ko‘paytirishda ko‘rsatkichlarni qo‘shish o‘rniga ko‘paytirish: $2 \\cdot \\frac{2}{3} - \\frac{1}{3} = 1$.","Son bilan tekshiruv ($x = 8$): berilgan ifoda $\\frac{64 \\cdot 4}{2} = 128$; **B**: $64 \\cdot 2 = 128$ ✓."],"answer":"B) $x^2 \\sqrt[3]{x}$"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Kvadratning o‘rta hadi:** $(a + b)^2 \\ne a^2 + b^2$. O‘rta had $2ab$ — eng ko‘p unutiladigan qism.","**Qavs oldidagi minus:** $-(x^2 - 16) = -x^2 + 16$. Ayirishdan oldin ayriluvchi ifodani qavsga oling.","**Faqat ko‘paytuvchilar qisqaradi:** $\\frac{x + 6}{x}$ dagi $x$ larni qisqartirib bo‘lmaydi; $\\frac{x(x + 6)}{x} = x + 6$ esa to‘g‘ri ($x \\ne 0$ bo‘lganda).","**Manfiy daraja — manfiy son emas:** $x^{-2} = \\frac{1}{x^2}$, $-x^2$ emas.","**Kasr daraja:** $x^{m/n}$ da maxraj — ildiz ko‘rsatkichi, surat — daraja: $x^{3/4} = \\sqrt[4]{x^3}$.","**Son qo‘yishda ehtiyot bo‘ling:** $x = 0$ yoki $x = 1$ ko‘pincha bir nechta variantni “to‘g‘ri” qilib ko‘rsatadi. Ikki variant bir xil natija bersa, boshqa son bilan qayta tekshiring.","**Shartlarga e’tibor:** *“where x > 0”* — ildiz va kasr darajalar ma’noga ega bo‘lishi uchun; *“x ≠ 3”* — maxraj nolga aylanmasligi uchun. Bu shartlar ifodani o‘zgartirmaydi, faqat u aniqlangan bo‘lishini ta’minlaydi."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**O‘rta hadsiz kvadrat:** $(3x - 2)^2 = 9x^2 + 4$ (Namuna 1 dagi B).","**Minus faqat birinchi hadga:** $-(x^2 - 16)$ ni $-x^2 - 16$ deb yozish (Namuna 1 dagi C).","**Daraja qoidalari aralashib ketgan:** ko‘paytirishda ko‘rsatkichlarni ko‘paytirish yoki darajani darajaga ko‘tarishda ularni qo‘shish (Namuna 3 dagi A).","**Ildiz ko‘rsatkichi teskari:** $\\sqrt[3]{x^2} = x^{3/2}$ deb yozish (Namuna 3 dagi C).","**Boshqa konstanta:** *“What is the value of b?”* savoliga $a$ ning qiymatini kiritish.","**Qisman to‘g‘ri variant:** ko‘pchilik variantlarda birinchi had to‘g‘ri bo‘ladi — farq odatda o‘rta hadda yoki ozod hadda. Har bir hadni alohida tekshiring."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Qavs ochish va daraja savollari — **40–70 soniya**; *“for all values of x”* savollari — **50–80 soniya**.","**Desmos — grafiklarning ustma-ust tushishi:** berilgan ifodani $y = (3x - 2)^2 - (x + 4)(x - 4)$ deb kiriting, keyin variantni ham $y = \\ldots$ ko‘rinishida kiriting. Ekvivalent bo‘lsa, ikkinchi grafik birinchisining ustiga to‘liq tushadi.","**Desmos — son qo‘yish:** $f(x)$ ni berilgan ifoda, $g(x)$ ni variant sifatida kiriting va $f(3) - g(3)$ deb yozing; natija 0 bo‘lsa — bu nomzod. Ishonch uchun yana bir son bilan tekshiring.","**Koeffitsiyent savollarida** Desmos kamroq yordam beradi — qavslarni qo‘lda ochish odatda 30 soniyada tugaydi."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"equivalent","meaning":"ekvivalent, aynan teng — barcha $x$ larda bir xil qiymat beradi"},{"term":"expression","meaning":"ifoda (unda tenglik belgisi yo‘q)"},{"term":"for all values of x","meaning":"$x$ ning barcha qiymatlarida — koeffitsiyentlarni tenglashtiring"},{"term":"constant","meaning":"o‘zgarmas son ($a$, $b$, $c$, $k$)"},{"term":"coefficient","meaning":"koeffitsiyent: had oldidagi son, masalan $7x^2$ da 7"},{"term":"factor / factored form","meaning":"ko‘paytuvchi / ko‘paytuvchilarga ajratilgan shakl"},{"term":"rewritten as / in the form","meaning":"… ko‘rinishida qayta yozilgan — kerakli shaklni bildiradi"},{"term":"in terms of","meaning":"… orqali ifodalang: kerakli harfni yolg‘iz qoldiring"},{"term":"where x > 0","meaning":"bu yerda $x > 0$ — ifoda aniqlangan bo‘lishi uchun qo‘yilgan shart"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Qavs oldidagi minus barcha hadlarga tarqaldimi?","Kvadratni ochganda o‘rta hadni ($2ab$) yozdimmi?","Daraja qoidalarini to‘g‘ri qo‘lladimmi: ko‘paytirishda ko‘rsatkichlar qo‘shiladi, darajani darajaga ko‘tarishda ko‘paytiriladi?","Javobimni 0 va 1 dan boshqa son qo‘yib tekshirdimmi?"]}]'::jsonb
from public.guides g where g.slug = 'equivalent-expressions'
on conflict (guide_id, locale) do nothing;

-- evaluating-statistical-claims
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'evaluating-statistical-claims', 'skill', (select id from public.skills where code = 'evaluating_statistical_claims'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'evaluating_statistical_claims'), 15, 9, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Statistik da’volarni baholash: kuzatuv tadqiqotlari va tajribalar', 'Tadqiqot qanday o‘tkazilganiga qarab qaysi xulosa asosli ekanini aniqlash: natijani kimga umumlashtirish mumkin va sabab-oqibat haqida gapirish mumkinmi. Ikki kalit ibora — randomly selected va randomly assigned.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Bu ko‘nikmada hisob deyarli yo‘q: sizdan tadqiqot tavsifini o‘qib, undan **qaysi xulosa kelib chiqishini** aniqlash so‘raladi. Hammasi ikki savolga borib taqaladi:\n\n- **Ishtirokchilar bosh to‘plamdan tasodifiy tanlanganmi (random selection)?** Ha bo‘lsa — natijani **shu bosh to‘plamga** umumlashtirish mumkin. Yo‘q bo‘lsa (ko‘ngillilar, qo‘l ostidagi qulay guruh) — faqat o‘rganilganlar haqida gapirish mumkin.\n- **Ishtirokchilar guruhlarga tasodifiy taqsimlanganmi (random assignment)?** Ha bo‘lsa — bu **tajriba** (experiment) va **sabab-oqibat** (cause-and-effect) haqida xulosa qilish mumkin. Yo‘q bo‘lsa — bu **kuzatuv tadqiqoti** (observational study) va faqat **bog‘liqlik** (association) haqida gapirish mumkin.\n\nNatijada to‘rt holat bo‘ladi:\n\n- Tasodifiy tanlash + tasodifiy taqsimlash → sabab-oqibat, butun bosh to‘plam uchun.\n- Faqat tasodifiy taqsimlash → sabab-oqibat, lekin faqat ishtirokchilar uchun.\n- Faqat tasodifiy tanlash → bog‘liqlik, butun bosh to‘plam uchun.\n- Hech biri yo‘q → faqat ishtirokchilar orasidagi bog‘liqlik.\n\nKuzatuv tadqiqotida sabab haqida gapirib bo‘lmasligining sababi — **chalkashtiruvchi omillar** (confounding variables). Masalan, ko‘p kitob o‘qiydigan o‘quvchilarning baholari yuqori bo‘lishi mumkin, lekin bunga uydagi qo‘llab-quvvatlash kabi boshqa omil ham sabab bo‘lishi mumkin."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["*“Which of the following conclusions is best supported by the study?”*, *“Which statement is an appropriate conclusion?”* — xulosani baholash savoli.","Tavsifda *“were selected at random from …”* yoki *“volunteered”*, *“chose to respond to an online poll”* — tanlash usuli: kimga umumlashtirish mumkinligini hal qiladi.","Tavsifda *“were randomly assigned to …”*, *“treatment group”*, *“control group”* — tajriba belgisi.","Tavsifda *“researchers surveyed …”*, *“recorded …”*, *“found that people who …”* — ishtirokchilar guruhni o‘zlari tanlagan yoki shunchaki kuzatilgan: bu kuzatuv tadqiqoti.","Variantlarda *“causes”*, *“leads to”*, *“improves”*, *“lowers”* yoki *“is associated with”*, *“is related to”* — sabab yoki bog‘liqlik da’vosi."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Ishtirokchilar qanday tanlanganini belgilang.** Tasodifiymi? Qaysi guruhdan (bitta universitet, bitta shahar, ko‘ngillilar)? Shu guruh — umumlashtirish chegarasi.","**Guruhlarga kim ajratganini belgilang.** Tadqiqotchi tasodifiy taqsimlagan bo‘lsa — tajriba. Odamlar o‘zlari tanlagan yoki shunchaki kuzatilgan bo‘lsa — kuzatuv tadqiqoti.","**Xulosaning kuchini aniqlang:** tajriba → “causes”, “is likely to improve” mumkin; kuzatuv → faqat “is associated with”.","**Xulosaning qamrovini aniqlang:** tasodifiy tanlangan bo‘lsa — o‘sha bosh to‘plam; aks holda — faqat ishtirokchilar.","**Har bir variantni kuch va qamrov bo‘yicha sinang.** Variant juda kuchli (sabab, “hamma”, “isbotlaydi”) ham, juda kuchsiz (“hech qanday xulosa qilib bo‘lmaydi”) ham bo‘lishi mumkin — to‘g‘ri javob aynan ma’lumot ruxsat bergan darajada bo‘ladi."]},{"type":"example","heading":"Namuna 1: tasodifiy tanlash va tasodifiy taqsimlash","example":{"problem":"A researcher selected 300 students at random from a large university. The researcher randomly assigned 150 of the students to use a vocabulary flashcard app for 20 minutes each day and the other 150 students not to use the app. After 6 weeks, the students who used the app had a significantly higher mean score on a vocabulary test than the students who did not. Which of the following conclusions is best supported by the study?","choices":["Using the app causes higher vocabulary test scores for students at any university.","Using the app is likely to improve vocabulary test scores for students at this university.","Using the app is associated with higher vocabulary test scores, but no cause-and-effect conclusion can be drawn.","Using the app will improve the vocabulary test score of every student at this university."],"solution":["Tanlash: 300 talaba **shu universitetdan tasodifiy** tanlangan → natijani shu universitet talabalariga umumlashtirish mumkin.","Taqsimlash: tadqiqotchi talabalarni ilovadan foydalanadigan va foydalanmaydigan guruhlarga **tasodifiy** ajratgan → bu tajriba, sabab-oqibat haqida gapirish mumkin.","Demak to‘g‘ri xulosa: ilova **shu universitet** talabalarining natijasini yaxshilashi ehtimoli katta — B variant.","Nega A xato: qamrov juda keng — boshqa universitetlar talabalari tanlanmada bo‘lmagan.","Nega C xato: juda kuchsiz — tasodifiy taqsimlash bo‘lgani uchun sabab-oqibat xulosasi qilish mumkin.","Nega D xato: *“every student”* — statistik natija o‘rtacha haqida, har bir talaba uchun kafolat bermaydi."],"answer":"B"}},{"type":"example","heading":"Namuna 2: kuzatuv tadqiqoti","example":{"problem":"Researchers surveyed a random sample of 1,000 adults in a country. They found that adults who reported drinking at least 3 cups of tea per day had, on average, lower blood pressure than adults who reported drinking fewer than 3 cups of tea per day. Which of the following conclusions is best supported by the study?","choices":["Drinking at least 3 cups of tea per day lowers blood pressure for adults in the country.","For adults in the country, drinking at least 3 cups of tea per day is associated with lower blood pressure.","Drinking at least 3 cups of tea per day lowers blood pressure for people in every country.","No conclusion can be drawn about adults in the country, because the participants were not randomly assigned to drink tea."],"solution":["Tanlash: mamlakat kattalaridan **tasodifiy** tanlanma → natijani shu mamlakat kattalariga umumlashtirish mumkin.","Taqsimlash: kim qancha choy ichishini odamlar **o‘zlari** tanlagan, tadqiqotchilar faqat so‘rashgan → kuzatuv tadqiqoti, faqat bog‘liqlik haqida gapirish mumkin.","Demak: mamlakat kattalari orasida ko‘p choy ichish past qon bosimi bilan **bog‘liq** — B variant.","Nega A xato: *“lowers”* — sabab da’vosi. Ko‘p choy ichadiganlar, masalan, kamroq kofe ichishi yoki ko‘proq harakat qilishi mumkin — qon bosimiga aynan shu omil ta’sir qilayotgan bo‘lishi mumkin.","Nega C xato: ham sabab da’vosi, ham qamrov juda keng (boshqa mamlakatlar tanlanmada bo‘lmagan).","Nega D xato: juda kuchsiz. Tasodifiy taqsimlash bo‘lmagani uchun sabab haqida gapirib bo‘lmaydi, lekin tasodifiy **tanlash** bo‘lgani uchun bog‘liqlikni butun bosh to‘plamga umumlashtirish mumkin."],"answer":"B"}},{"type":"example","heading":"Namuna 3: ixtiyoriy javob berilgan so‘rovnoma","example":{"problem":"A city council wanted to know how city residents feel about a proposed bike lane. The council posted a poll on its social media page, and 2,400 people chose to respond. Of those who responded, 71% said they oppose the bike lane. Which of the following statements is most appropriate?","choices":["About 71% of the city''s residents oppose the bike lane.","The results may not represent the opinions of all city residents, because the people who responded chose to participate.","The results represent all city residents, because the sample size of 2,400 is large.","The poll shows that the proposed bike lane caused most residents to be unhappy."],"solution":["Tanlash: odamlar javob berishni o‘zlari tanlagan (*“chose to respond”*) — bu **ixtiyoriy javob** (voluntary response) tanlanmasi, tasodifiy emas.","Bunday so‘rovnomaga odatda masala bo‘yicha kuchli fikri bor odamlar ko‘proq javob beradi; bundan tashqari, faqat kengashning sahifasini kuzatuvchilar qatnashgan. Natija noxolis (biased) bo‘lishi mumkin — B variant.","Nega A xato: tasodifiy bo‘lmagan tanlanmadan butun shahar haqida foiz chiqarib bo‘lmaydi.","Nega C xato: katta hajm tanlov usulidagi kamchilikni tuzatmaydi — 2400 ta ixtiyoriy javob ham noxolis bo‘lishi mumkin.","Nega D xato: so‘rovnoma sabab-oqibatni tekshirmaydi; qolaversa, yo‘lak hali qurilmagan (*“proposed”*), u hech narsaga sabab bo‘la olmaydi."],"answer":"B"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**“Randomly selected” va “randomly assigned” — har xil narsa.** Birinchisi kimga umumlashtirishni, ikkinchisi sabab haqida gapirish mumkinligini hal qiladi. Matnda ikkalasini alohida qidiring.","**Katta tanlanma — hali yaxshi tanlanma degani emas.** Tanlov usuli noxolis bo‘lsa, hajm buni tuzatmaydi.","**Qamrov — tanlanma olingan joy:** bitta maktab, bitta shahar, bitta yosh guruhi… Xulosa undan kengaymasligi kerak.","**Nazorat guruhi (control group)** bo‘lmasa, o‘zgarishni aynan muolajaga bog‘lash qiyin.","**Chalkashtiruvchi omil:** kuzatuv tadqiqotida guruhlar boshqa jihatlardan ham farq qilishi mumkin — shuning uchun sabab da’vosi asossiz.","**Juda kuchsiz variant ham xato bo‘ladi:** tadqiqot tasodifiy taqsimlangan tajriba bo‘lsa, “sabab haqida hech narsa deyib bo‘lmaydi” degan variant noto‘g‘ri."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Kuzatuvdan sabab xulosasi:** kuzatuv tadqiqotiga oid variantda *“lowers”*, *“causes”*, *“improves”* so‘zlari — tuzoq (namuna 2, A).","**Ortiqcha umumlashtirish:** “any university”, “every country”, “all teenagers” (namuna 1, A; namuna 2, C).","**Har bir shaxs uchun kafolat:** *“every student will improve”* (namuna 1, D).","**Hajm bilan oqlash:** “sample is large, so it represents everyone” (namuna 3, C).","**Haddan tashqari ehtiyotkorlik:** tajribada “no cause-and-effect conclusion” yoki tasodifiy tanlanmada “no conclusion about the population” (namuna 1, C; namuna 2, D)."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Bu tur odatda tez yechiladi: **30–60 soniya**. Hisob yo‘q, asosiy ish — tavsifni diqqat bilan o‘qish.","Variantlarni o‘qishdan oldin qoralamaga ikki belgi qo‘ying: “tanlash: random / random emas (kimdan?)” va “taqsimlash: random / yo‘q”. Keyin variantlar yuqoridagi to‘rt holat bo‘yicha tez saralanadi.","Desmos va kalkulyator bu turda kerak emas — tejalgan vaqtni hisob talab qiladigan savollarga qoldiring.","Bu ko‘nikma savollarida javob gap ko‘rinishida bo‘lgani uchun ular odatda variantli (multiple-choice) bo‘ladi; shu sababli bu qo‘llanmadagi barcha namunalar variantli."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"observational study","meaning":"kuzatuv tadqiqoti: tadqiqotchi faqat kuzatadi, guruhlarga o‘zi ajratmaydi"},{"term":"experiment","meaning":"tajriba: kim qaysi muolajani olishini tadqiqotchi belgilaydi"},{"term":"randomly assigned","meaning":"guruhlarga tasodifiy taqsimlangan → sabab-oqibat haqida gapirish mumkin"},{"term":"selected at random / random sample","meaning":"tasodifiy tanlangan → bosh to‘plamga umumlashtirish mumkin"},{"term":"treatment group / control group","meaning":"muolaja (sinov) guruhi / nazorat guruhi"},{"term":"cause-and-effect","meaning":"sabab-oqibat bog‘liqligi"},{"term":"associated with","meaning":"bog‘liq — lekin biri ikkinchisiga sabab bo‘lishi shart emas"},{"term":"generalize","meaning":"umumlashtirish: natijani kengroq guruhga tatbiq etish"},{"term":"volunteer / voluntary response","meaning":"ko‘ngilli / ixtiyoriy javob — noxolis tanlanma belgisi"},{"term":"bias","meaning":"noxolislik: natijaning bir tomonga tizimli og‘ishi"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Ishtirokchilar tasodifiy tanlanganmi — va qaysi guruhdan?","Guruhlarga tasodifiy taqsimlanganmi (tajribami yoki kuzatuvmi)?","Tanlagan variantim ma’lumot ruxsat bergandan kuchliroq ham, kuchsizroq ham emasmi?"]}]'::jsonb
from public.guides g where g.slug = 'evaluating-statistical-claims'
on conflict (guide_id, locale) do nothing;

-- form-structure-sense
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'form-structure-sense', 'skill', (select id from public.skills where code = 'form_structure_sense'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'form_structure_sense'), 28, 11, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Shakl, tuzilish va ma’no (Form, Structure, and Sense)', 'Ega va kesim moslashuvi, olmosh va u almashtirgan ot, fe’l zamoni va shakli, ko‘plik va egalik (apostrof) hamda aniqlovchining to‘g‘ri joylashuvi — variantlarda bitta so‘zning turli shakllari berilgan grammatika savollari uchun ixcham qoidalar kitobi.', '[{"type":"concept","heading":"Qoidalar kitobi (1-qism): asosiy qoidalar","body":"Bu savollarda variantlar bitta so‘zning turli shakllaridan iborat bo‘ladi: *is / are / were*, *its / their*, *scientist''s / scientists''*. Vazifangiz — gapning qolgan qismiga grammatik va mantiqiy jihatdan mos shaklni tanlash. Quyidagi misollarda muhim so‘zlarning tagiga chizilgan.\n\n**1-qoida. Ega va kesim moslashuvi.** Kesim haqiqiy egaga moslashadi, unga eng yaqin turgan otga emas. *of…, with…, in…* kabi predlogli iboralarni va vergul bilan ajratilgan qismlarni xayolan o‘chiring: *The __list__ of supplies __is__ long.* (*supplies are* emas). *The __paintings__ in the old hall __were__ restored.* *And* bilan bog‘langan ega — ko‘plik: *The __map and the compass are__ missing.* *Each, every, one of, either, neither* — birlik: *One of the samples __was__ damaged.*\n\n**2-qoida. Olmosh va u almashtirgan ot (pronoun–antecedent agreement).** Olmosh soni u almashtirgan otga mos bo‘lishi kerak: *The __company__ announced __its__ new policy.* (kompaniya — birlik, *their* emas). *The __researchers__ published __their__ results.* Avval olmosh kimni yoki nimani almashtirayotganini toping.\n\n**3-qoida. Fe’l zamoni va shakli.** Zamon matndagi vaqt ko‘rsatkichlariga mos bo‘lishi kerak: *in 1920* — o‘tgan zamon, *currently* — hozirgi zamon, *since 2015* — *has / have* + III shakl. O‘tmishdagi ikki voqeadan avvalroq sodir bo‘lgani uchun *had* + III shakl ishlatiladi: *By the time the rescuers arrived, the storm __had passed__.* III shakl (past participle) to‘g‘ri bo‘lsin: *had __begun__* (*had began* emas), *has __written__*.\n\n**4-qoida. Gapda asosiy fe’l bo‘lishi shart.** *-ing* yoki *to* + fe’l shakli yolg‘iz o‘zi kesim bo‘la olmaydi: ✗ *The researchers analyzing the data.* ✓ *The researchers __analyzed__ the data.*\n\n**5-qoida. Ko‘plik va egalik (apostrof).** Oddiy ko‘plik — apostrofsiz: *two __scientists__*. Birlikdagi egalik — *''s*: *the __scientist''s__ notes* (bitta olim). Ko‘plikdagi egalik — *s''*: *the __scientists''__ notes* (bir necha olim). -s bilan tugamaydigan ko‘plik — *''s*: *the __children''s__ books*. Olmoshlarning egalik shaklida apostrof yo‘q: *its, their, whose*; *it''s* = *it is*, *they''re* = *they are*, *who''s* = *who is*.\n\n**6-qoida. Aniqlovchining joylashuvi (modifiers).** Gap boshidagi, vergul bilan tugaydigan ibora verguldan keyingi birinchi otni tasvirlaydi: ✗ *Hiking up the trail, __the view__ was stunning.* (manzara yo‘l yurmaydi) ✓ *Hiking up the trail, __we__ saw a stunning view.*"},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["Savol so‘zi Boundaries bilan bir xil: *“Which choice completes the text so that it conforms to the conventions of Standard English?”* Farq variantlarda.","**Fe’l shakllari:** *is / are / was / have been* yoki *began / had begun / beginning* — moslashuv yoki zamon savoli.","**Olmoshlar:** *it / they*, *its / their / it''s / they''re* — olmosh moslashuvi yoki egalik.","**Bir ot, to‘rt shakl:** *tortoise''s / tortoises / tortoises''* — ko‘plik va egalik.","**Butun gap qismi almashadi:** gap *Having tracked…,* yoki *Known for…,* kabi kirish iborasi bilan boshlanadi va variantlarda harakatni kim bajargani turlicha — aniqlovchining joylashuvi savoli."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Variantlarni solishtiring: nima o‘zgaryapti?** Fe’l, olmosh, apostrof yoki gap tartibi — shu sizga qaysi qoida tekshirilayotganini aytadi.","**Fe’l bo‘lsa — haqiqiy egani toping.** Predlogli iboralarni (*of the…, in the…*) va qo‘shimcha qismlarni xayolan o‘chiring. “Bu ishni kim yoki nima qiladi?” deb so‘rang, keyin birlik yoki ko‘plikni aniqlang.","**Zamonni kontekstdan aniqlang.** Oldingi va keyingi gaplardagi fe’llarga hamda *in 1890, today, since, by the time* kabi vaqt ko‘rsatkichlariga qarang.","**Olmosh bo‘lsa — u almashtirgan otni toping** va sonini (birlik yoki ko‘plik) solishtiring. *Company, team, city, species* — birlik, demak *its*.","**Apostrof bo‘lsa, ikki savol bering:** (1) birlikmi yoki ko‘plikmi? (2) biror narsaga egalik qilyaptimi? *of* bilan qayta aytib ko‘ring: *the burrows of the tortoises* → *the tortoises'' burrows*.","**Kirish iborasi bo‘lsa** — undagi harakatni kim bajarganini aniqlang va verguldan keyin aynan shu shaxs yoki narsa kelgan variantni tanlang.","**Gapni tanlangan variant bilan to‘liq o‘qing:** asosiy fe’l bormi, zamon izchilmi?"]},{"type":"example","heading":"Namuna 1: ega va kesim moslashuvi","example":{"problem":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"The collection of hand-painted ceramic tiles that once decorated the walls of the old caravanserai ______ now displayed in the regional history museum.","choices":["are","is","have been","were"],"solution":["Variantlar — fe’l shakllari, demak ega va kesim moslashuvini hamda zamonni tekshiramiz.","Haqiqiy egani topamiz: *of hand-painted ceramic tiles* (predlogli ibora) va *that once decorated the walls of the old caravanserai* (aniqlovchi qism) ni xayolan o‘chirsak, *The collection… now displayed* qoladi. Ega — *collection*, birlikda.","*now* so‘zi hozirgi zamonni ko‘rsatadi. Birlik + hozirgi zamon = *is* — **B**.","**A** (*are*) va **D** (*were*) — ko‘plik shakllari: kesim yaqin turgan *tiles* yoki *walls* ga moslashtirilgan. **D** bundan tashqari o‘tgan zamonda, bu *now* ga zid.","**C** (*have been*) — ko‘plik shakli (birlik uchun *has been* bo‘lardi), shuning uchun egaga mos emas."],"answer":"B) is"}},{"type":"example","heading":"Namuna 2: ko‘plik va egalik","example":{"problem":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Biologist Kamila Usmonova placed small cameras near the burrows of several desert tortoises. The footage showed that the ______ stayed much cooler than the sand surface during the hottest hours of the day.","choices":["tortoise''s burrows","tortoises burrow''s","tortoises'' burrows","tortoises'' burrow''s"],"solution":["Variantlarda ikki so‘z — *tortoise* va *burrow* — turli ko‘plik va egalik shakllarida. Har bir so‘zni alohida tekshiramiz.","*Tortoise*: birinchi gapda *several desert tortoises* — bir nechta toshbaqa, ya’ni ko‘plik. Inlar ularga tegishli (*the burrows of the tortoises*), demak ko‘plikdagi egalik kerak: *tortoises''*.","*Burrow*: inlar hech narsaga egalik qilmaydi — ular gapning egasi va ular bir nechta. Demak oddiy ko‘plik: *burrows*. To‘g‘ri javob — **C**: *tortoises'' burrows*.","**A** (*tortoise''s burrows*) — birlikdagi egalik: bitta toshbaqa haqida gapiradi, matnda esa bir nechta toshbaqa bor.","**B** (*tortoises burrow''s*) — egalik belgisi noto‘g‘ri so‘zda: toshbaqalarda apostrof yo‘q, *burrow''s* esa inning nimagadir egaligini bildiradi, lekin undan keyin hech qanday ot yo‘q.","**D** (*tortoises'' burrow''s*) — birinchi so‘z to‘g‘ri, lekin *burrow''s* ortiqcha egalik shakli (va birlikda)."],"answer":"C) tortoises'' burrows"}},{"type":"example","heading":"Namuna 3: aniqlovchining joylashuvi","example":{"problem":"Which choice completes the text so that it conforms to the conventions of Standard English?","passage":"Having tracked dozens of steppe eagles with lightweight GPS tags for nearly a decade, ______","choices":["the eagles'' wintering sites were identified by ornithologist Timur Saidov.","the eagles'' wintering sites, according to ornithologist Timur Saidov, had been identified.","identifying the eagles'' wintering sites was ornithologist Timur Saidov''s achievement.","ornithologist Timur Saidov identified the eagles'' wintering sites."],"solution":["Gap *Having tracked…* kirish iborasi bilan boshlanadi. Unda harakat (kuzatish) bor, lekin kim kuzatgani aytilmagan. Qoida: verguldan keyingi birinchi ot (shaxs) aynan shu harakatni bajargan bo‘lishi kerak.","Burgutlarni GPS orqali kim kuzatgan? Ornitolog Timur Saidov. Faqat **D** variantida verguldan keyin darhol *ornithologist Timur Saidov* keladi — to‘g‘ri javob.","**A** — verguldan keyin *the eagles'' wintering sites* turibdi: go‘yo qishlash joylari burgutlarni kuzatgandek bo‘lib qoladi. Passiv shakl (*were identified by…*) ko‘pincha shu tuzoqning belgisi.","**B** — yana *wintering sites* birinchi turibdi; *according to…* qismi buni tuzatmaydi.","**C** — birinchi turgan so‘z *identifying* (aniqlash jarayoni); jarayon burgutlarni kuzata olmaydi."],"answer":"D) ornithologist Timur Saidov identified the eagles'' wintering sites."}},{"type":"watch_out","heading":"Qoidalar kitobi (2-qism): nimaga e’tibor berish kerak","items":["**Ega va kesim orasidagi uzun “to‘siq”:** *The __results__ of the survey, which included more than 2,000 participants, __show__…* — ega *results* (ko‘plik). Vergullar orasidagi qismni o‘chirib o‘qing.","**Teskari tartibli gaplar:** *There __are__ three __reasons__…*, *Among the fossils __were__ two __teeth__.* Bunday gaplarda ega kesimdan **keyin** keladi.","**Either…or, neither…nor:** kesim yaqinroq turgan egaga moslashadi: *Neither the teacher nor the __students were__ ready.*","**Jamlovchi otlar** (*team, committee, family, series, species*) odatda birlik sifatida ishlatiladi: *The __committee has__ approved __its__ report.*","**Olmoshning aniqligi:** gapda ikki ot bo‘lsa va olmosh qaysi biriga tegishli ekani noaniq qolsa, olmosh o‘rniga otning o‘zi ishlatilgan variant to‘g‘ri bo‘lishi mumkin.","**Ro‘yxatdagi fe’llar bir xil shaklda (parallel structure):** *The volunteers __collected__, __sorted__, and __labeled__ the seeds.* (*collected, sorting, and labeled* emas).","**Zamon izchilligi:** matndagi boshqa fe’llar va vaqt ko‘rsatkichlariga qarang: *In 1925, the factory __produced__…* — *produces* yoki *will produce* emas.","**Egalik olmoshlari va qisqartmalar:** *its* (uning) — *it''s* (it is); *their* (ularning) — *they''re* (they are) — *there* (u yerda); *whose* (kimning) — *who''s* (who is). Tekshiruv: qisqartmani to‘liq shaklga ochib o‘qing — ma’no buzilsa, u noto‘g‘ri."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Yaqin otga moslashtirish:** kesimni ega bilan emas, bo‘sh joyga eng yaqin turgan ko‘plikdagi ot bilan moslashtirish (Namuna 1 dagi *tiles… are*).","**Birlikdagi otga their olmoshi:** *The organization… their* — og‘zaki nutqda keng tarqalgan, lekin SAT’da birlikdagi tashkilot yoki narsa uchun *its* kerak.","**Oddiy ko‘plikka apostrof qo‘yish:** *several scientist''s* — egalik bo‘lmasa, apostrof kerak emas: *several scientists*.","**It''s va its almashinuvi** — eng mashhur tuzoqlardan biri. *It''s* faqat *it is* yoki *it has* ma’nosida.","**Passiv shakldagi “rasmiy” variant:** aniqlovchi savollarida passiv konstruksiya (*…were identified by…*) jiddiy eshitiladi, lekin ko‘pincha kirish iborasini noto‘g‘ri otga bog‘laydi.","**Asosiy fe’lsiz variant:** *-ing* shakli (*analyzing, being*) gapni kesimsiz qoldiradi — bu variant ko‘pincha “uzun va ilmiy” ko‘rinadi.","**Zamon tuzog‘i:** grammatik jihatdan to‘g‘ri, lekin matndagi zamonga zid shakl (masalan, *now* bilan *were*)."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Bu savollar uchun **30–50 soniya** yetarli. Reading and Writing’da o‘rtacha vaqt savol boshiga taxminan 71 soniya — bu yerda kamroq sarflab, vaqtni uzun matnli savollarga qoldiring.","Avval variantlarga qarab, nima o‘zgarayotganini aniqlang — bu qaysi qoidani qo‘llashni darhol aytadi va matnni maqsadli o‘qishga yordam beradi.","Ega uzun bo‘lsa, qoralamaga faqat ega va kesimni yozib ko‘ring: *collection… is*. Shunda xato darhol ko‘rinadi.","Ikki variant orasida qolsangiz, ikkalasini gapga qo‘yib o‘qing va qoidani nomlang (“ega birlikda”, “ko‘plikdagi egalik”) — “qulog‘imga yoqdi” degan sabab yetarli emas."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"subject–verb agreement","meaning":"ega va kesimning sonda moslashuvi"},{"term":"antecedent","meaning":"olmosh almashtirgan ot: *The city… its* gapida *city*"},{"term":"singular / plural","meaning":"birlik / ko‘plik"},{"term":"possessive","meaning":"egalik shakli: *the scientist''s* (bitta olimning), *the scientists''* (olimlarning)"},{"term":"verb tense","meaning":"fe’l zamoni: *past, present, future, present perfect*"},{"term":"past participle","meaning":"fe’lning III shakli: *begun, written, risen*"},{"term":"finite verb","meaning":"gapning asosiy (kesim bo‘la oladigan) fe’li; *-ing* va *to* shakllari bunday emas"},{"term":"dangling modifier","meaning":"“osilib qolgan” aniqlovchi — kirish iborasi noto‘g‘ri otni tasvirlab qoladi"},{"term":"collective noun","meaning":"jamlovchi ot: *team, committee, species* — odatda birlik"},{"term":"parallel structure","meaning":"parallel tuzilma — ro‘yxatdagi elementlar bir xil grammatik shaklda bo‘ladi"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Variantlarda nima o‘zgarayotganini (fe’l, olmosh, apostrof yoki tartib) aniqladimmi?","Haqiqiy egani yoki olmosh almashtirgan otni topib, birlik yoki ko‘plikni tekshirdimmi?","Zamon matndagi vaqt ko‘rsatkichlariga mosmi?","Kirish iborasidan keyin aynan harakatni bajargan shaxs yoki narsa turibdimi?"]}]'::jsonb
from public.guides g where g.slug = 'form-structure-sense'
on conflict (guide_id, locale) do nothing;

-- grammar-rules-cheat-sheet
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'grammar-rules-cheat-sheet', 'strategy', null, (select id from public.subjects where code = 'reading_writing'), 9, 12, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Grammatika qoidalari: SAT uchun qisqa qo‘llanma', 'Standard English Conventions savollari uchun ixcham qoidalar to‘plami: gap chegaralari (comma splice, nuqtali vergul, ikki nuqta, tire, qo‘shimcha qismlar), ega va kesim moslashuvi, olmoshlar, fe’l zamonlari, aniqlovchi iboralar, egalik va apostrof — har biri qisqa inglizcha misol va “SAT buni qanday tekshiradi” maslahati bilan.', '[{"type":"concept","heading":"Bu savollar nimani tekshiradi","body":"Standard English Conventions — Reading and Writing bo‘limining taxminan 26% i (11–15 ta savol). Savol doim bir xil: *Which choice completes the text so that it conforms to the conventions of Standard English?* Ikki ko‘nikma tekshiriladi:\n\n- **Boundaries** (gap chegaralari) — gaplar va ularning qismlari tinish belgilari bilan qanday ajratiladi.\n- **Form, Structure, and Sense** (shakl va moslik) — ega va kesim moslashuvi, olmoshlar, fe’l zamonlari va shakllari, aniqlovchi iboralar, ko‘plik va egalik.\n\nDeyarli hamma qoida bitta tushunchaga tayanadi. **Mustaqil gap** (*independent clause*) — egasi va kesimi bor, yolg‘iz tura oladigan to‘liq fikr: *The lab closed early.* **Tobe gap** (*dependent clause*) *because, although, when, while, which* kabi so‘z bilan boshlanadi va yolg‘iz tura olmaydi: *because the lab closed early*.\n\nBu savollar tez yechiladi (30–50 soniya) va qoidalar cheklangan — ularni o‘rganish ballni oshirishning eng tez yo‘llaridan biri."},{"type":"note","heading":"1. Ikki mustaqil gapni bog‘lash","items":["**To‘g‘ri usullar:** nuqta (.), nuqtali vergul (;), vergul + bog‘lovchi (*for, and, nor, but, or, yet, so* — inglizcha qisqacha FANBOYS) yoki, ikkinchi gap birinchisini tushuntirsa, ikki nuqta (:).","✗ **Comma splice:** *The lab closed early, the samples were moved.* — ikki mustaqil gap faqat vergul bilan ajratilgan.\n✓ *The lab closed early; the samples were moved.*\n✓ *The lab closed early, so the samples were moved.*","✗ **Run-on:** *The lab closed early the samples were moved.* — orada hech qanday belgi yo‘q.","✗ **Fragment:** *Because the lab closed early.* — tobe gap yolg‘iz qolgan. ✓ *Because the lab closed early, the samples were moved.*","**SAT qanday tekshiradi:** variantlarda so‘zlar bir xil, faqat tinish belgisi farq qiladi. Bo‘sh joyning **chap** va **o‘ng** tomonini alohida o‘qing. Ikkalasi ham mustaqil gap bo‘lsa — nuqta, nuqtali vergul yoki vergul + FANBOYS; bittasi mustaqil bo‘lmasa — vergul yoki hech narsa."]},{"type":"note","heading":"2. Nuqtali vergul (;) va o‘tish so‘zlari","items":["Nuqtali vergul nuqta kabi ishlaydi: **ikkala tomoni ham mustaqil gap** bo‘lishi shart. ✓ *The bridge opened in 1932; it is still in use.* ✗ *The bridge opened; in 1932.*","*however, therefore, moreover, nevertheless, for example* kabi o‘tish so‘zlari ikki mustaqil gapni o‘zi **bog‘lay olmaydi** — oldidan nuqtali vergul yoki nuqta kerak. ✓ *The data were limited; however, the trend was clear.* ✗ *The data were limited, however, the trend was clear.*","O‘tish so‘zi bitta gapning ichida kelsa, ikki tomondan vergul bilan ajratiladi: ✓ *The trend, however, was clear.*","**SAT qanday tekshiradi:** *however* yoki *therefore* atrofidagi belgilar. Avval aniqlang: o‘tish so‘zi ikki mustaqil gap chegarasidami (→ “;” yoki “.”) yoki bitta gap ichidami (→ ikki vergul)?"]},{"type":"note","heading":"3. Ikki nuqta (:)","items":["Ikki nuqtadan **oldin to‘liq mustaqil gap** bo‘lishi kerak; undan keyin ro‘yxat, tushuntirish yoki misol keladi.","✓ *The team needed one thing: more time.* ✗ *The team needed: more time.*","✗ *The recipe includes: flour, salt, and water.* — fe’ldan keyin to‘g‘ridan-to‘g‘ri ikki nuqta qo‘yilmaydi. ✓ *The recipe includes flour, salt, and water.*","**SAT qanday tekshiradi:** ikki nuqtaning chap tomonini alohida o‘qing — u yolg‘iz to‘liq gap bo‘la oladimi? Ikki nuqta “ya’ni”, “aynan” ma’nosini beradi."]},{"type":"note","heading":"4. Qo‘shimcha qismlar: vergul, tire, qavs","items":["Gapdan olib tashlansa ma’no buzilmaydigan **qo‘shimcha** (*nonessential*) qism ikki tomondan **bir xil** belgi bilan ajratiladi: ikki vergul, ikki tire yoki ikki qavs.","✓ *The mural, painted in 1998, faces the river.*\n✓ *The mural—painted in 1998—faces the river.*\n✗ *The mural, painted in 1998—faces the river.* (belgilar har xil)\n✗ *The mural, painted in 1998 faces the river.* (ikkinchi vergul yo‘q)","**Muhim** (*essential*) qism ajratilmaydi — u qaysi narsa haqida gap ketayotganini aniqlaydi: ✓ *Students who arrive late must sign in.* (faqat kech kelganlar).","**Unvon va ism:** unvon yoki kasb ismdan oldin kelsa, orada vergul qo‘yilmaydi: ✓ *The biologist Ana Ruiz spoke first.* ✗ *The biologist, Ana Ruiz spoke first.* Ism oldin, izoh keyin kelsa — ikki vergul: ✓ *Ana Ruiz, a biologist, spoke first.*","**SAT qanday tekshiradi:** qo‘shimcha qism vergul yoki tire bilan boshlangan bo‘lsa, uning oxirida **xuddi shu** belgini qidiring."]},{"type":"note","heading":"5. Keraksiz vergullar","items":["Ega va kesim orasida vergul qo‘yilmaydi — ega uzun bo‘lsa ham: ✗ *The results of the long study, were surprising.* ✓ *The results of the long study were surprising.*","Fe’l va to‘ldiruvchi orasida ham: ✗ *The team discovered, a new species.* ✓ *The team discovered a new species.*","Bitta egaga tegishli ikki kesim *and* bilan bog‘lansa, vergul kerak emas: ✓ *He opened the box and found a key.*","Gap boshidagi tobe gap yoki kirish iborasidan keyin esa vergul qo‘yiladi: ✓ *Although it rained, the race continued.*","**SAT qanday tekshiradi:** variantlar orasida keraksiz vergulli variantlar ko‘p. Har bir vergulning sababini ayta olishingiz kerak — sabab bo‘lmasa, vergul ham bo‘lmasin."]},{"type":"note","heading":"6. Ega va kesim moslashuvi (subject–verb agreement)","items":["Birlik ega — birlik kesim (*is, was, has, does*, fe’l + *-s*); ko‘plik ega — ko‘plik kesim (*are, were, have, do*).","**Ega uzoqda bo‘lishi mumkin:** *of, in, with, among* bilan boshlangan iborani xayolan o‘chirib o‘qing. ✓ *The list of names is long.* — ega **list** (birlik), shuning uchun *is*.","*each, every, either, neither, everyone, everything* — birlik: ✓ *Each of the samples was tested.*","*and* bilan bog‘langan ega — ko‘plik: ✓ *The map and the compass were missing.*","Kesim egadan oldin kelsa ham, egaga moslashadi: ✓ *Among the findings were two surprises.* — ega **surprises**.","Jamlovchi otlar (*team, committee, group, audience*) odatda birlik: ✓ *The committee has decided.*","**SAT qanday tekshiradi:** variantlar *is/are*, *was/were*, *has/have*. Avval haqiqiy egani toping — bo‘sh joyga eng yaqin ot ko‘pincha tuzoq."]},{"type":"note","heading":"7. Olmoshlar","items":["Olmosh o‘zi almashtirgan ot bilan sonda moslashadi: ✓ *The companies released their reports.* ✓ *The company released its report.* ✗ *The company released their report.*","*its* — egalik (“uning”), *it’s* — *it is* qisqartmasi: ✓ *The bird built its nest.*","*their* — egalik (“ularning”), *they’re* — *they are*, *there* — “u yerda”.","*who* — odamlar uchun, *which* — narsalar uchun; *whose* — egalik, *who’s* — *who is*.","**SAT qanday tekshiradi:** olmosh qaysi otga ishora qilayotganini toping va uning sonini tekshiring: birlik bo‘lsa *it/its*, ko‘plik bo‘lsa *they/their*."]},{"type":"note","heading":"8. Fe’l zamonlari va shakllari","items":["**Zamonni matndan oling:** matndagi boshqa fe’llar o‘tgan zamonda bo‘lsa, odatda o‘tgan zamon kerak. ✓ *In 1910, the inventor tested a prototype and recorded the results.*","**Present perfect** (*has/have* + fe’lning 3-shakli) — o‘tmishda boshlanib, hozirgacha davom etayotgan: ✓ *Since 2015, the city has planted 4,000 trees.*","**Past perfect** (*had* + 3-shakl) — o‘tmishdagi boshqa voqeadan oldin bo‘lgan: ✓ *By the time the rescuers arrived, the storm had passed.*","**Gapda asosiy fe’l bo‘lishi shart:** *-ing* shakli yoki *to* + fe’l yolg‘iz kesim bo‘la olmaydi. ✗ *The researchers analyzing the data.* ✓ *The researchers analyzed the data.*","**SAT qanday tekshiradi:** variantlar *analyzed / analyzing / to analyze / having analyzed*. Avval gapda boshqa asosiy fe’l bor-yo‘qligini aniqlang: yo‘q bo‘lsa — to‘liq kesim (*analyzed*) kerak; bor bo‘lsa — ko‘pincha *-ing* yoki *to* shakli."]},{"type":"note","heading":"9. Aniqlovchi iboralar (modifiers)","items":["Gap boshidagi aniqlovchi ibora verguldan keyingi **birinchi** otga tegishli bo‘ladi.","✗ *Walking to school, the rain started.* — yomg‘ir maktabga yurmaydi. ✓ *Walking to school, Dilnoza noticed the rain.*","✗ *Built in 1890, visitors still admire the tower.* — tashrif buyuruvchilar 1890-yilda qurilmagan. ✓ *Built in 1890, the tower is still admired by visitors.*","**SAT qanday tekshiradi:** variantlar verguldan keyingi qism qanday boshlanishi bilan farq qiladi. O‘zingizdan so‘rang: iboradagi ishni **kim** yoki **nima** bajargan? Aynan o‘sha so‘z verguldan keyin darhol kelishi kerak."]},{"type":"note","heading":"10. Ko‘plik va egalik (apostrof)","items":["**Birlik ot + ’s:** ✓ *the scientist’s notes* (bitta olim).","**-s bilan tugaydigan ko‘plik + ’:** ✓ *the scientists’ notes* (bir necha olim).","**-s siz ko‘plik + ’s:** ✓ *the children’s books*, ✓ *the women’s team*.","**Egalik olmoshlarida apostrof yo‘q:** *its, their, whose, ours, yours*.","**Oddiy ko‘plikda apostrof yo‘q:** ✓ *several samples*, ✓ *the 1990s*; ✗ *several sample’s*.","**SAT qanday tekshiradi:** variantlar *scientist’s / scientists’ / scientists / scientist*. Ikki savol bering: 1) bitta mi yoki ko‘p mi? 2) egalik bormi — ya’ni so‘zdan keyin u egalik qiladigan ot keladimi?"]},{"type":"method","heading":"Grammatika savolini 4 qadamda yechish","steps":["**Variantlarni ko‘ring:** nima farq qiladi — tinish belgisimi (Boundaries) yoki so‘z shakli (Form, Structure, and Sense)?","**Tinish belgisi bo‘lsa:** bo‘sh joyning chap va o‘ng tomonini aniqlang — mustaqil gapmi, tobe gapmi, qo‘shimcha qismmi? Keyin 1–5-qoidalarni qo‘llang.","**So‘z shakli bo‘lsa:** egani yoki olmosh almashtirgan otni toping, zamonni esa matndagi boshqa fe’llardan oling (6–10-qoidalar).","**Tanlangan variantni gapga qo‘yib, butun gapni bir marta o‘qing** va qoidani yana bir bor tekshiring. “Qulog‘imga yaxshi eshitiladi” — dalil emas: SAT tuzoqlari ko‘pincha tabiiy eshitiladi."]},{"type":"traps","heading":"SAT’ning eng ko‘p uchraydigan tuzoqlari","items":["Uzun ibora egani kesimdan uzoqlashtiradi — eng yaqin ot “yolg‘on ega” bo‘lib chiqadi.","*however* oldida vergul — ikki mustaqil gap orasida comma splice hosil qiladi.","Qo‘shimcha qism bir tomondan vergul, ikkinchi tomondan tire bilan ajratilgan.","Unvon va ism orasida vergul (*The biologist, Ana Ruiz…*).","Kesim o‘rnida *-ing* shakli — gap fe’lsiz qoladi.","*its/it’s* va *their/they’re* almashib ketadi."]},{"type":"terms","heading":"Grammatik atamalar","terms":[{"term":"independent clause","meaning":"mustaqil gap — egasi va kesimi bor, yolg‘iz tura oladi"},{"term":"dependent clause","meaning":"tobe gap — *because, although, which* kabi so‘z bilan boshlanadi, yolg‘iz tura olmaydi"},{"term":"comma splice","meaning":"ikki mustaqil gapni faqat vergul bilan ulash xatosi"},{"term":"run-on sentence","meaning":"ikki mustaqil gapni hech qanday belgisiz ulash xatosi"},{"term":"fragment","meaning":"to‘liq bo‘lmagan gap: egasi yoki asosiy fe’li yo‘q, yoki tobe gap yolg‘iz qolgan"},{"term":"nonessential element","meaning":"qo‘shimcha qism — olib tashlansa ham ma’no saqlanadi, ikki tomondan ajratiladi"},{"term":"subject–verb agreement","meaning":"ega va kesimning sonda moslashuvi"},{"term":"antecedent","meaning":"olmosh almashtirgan ot"},{"term":"modifier","meaning":"aniqlovchi ibora — o‘zi tegishli so‘zning yonida turishi kerak"},{"term":"possessive","meaning":"egalik shakli: *the scientist’s notes*"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin","items":["Variantlar nimasi bilan farq qiladi — belgi yoki so‘z shakli?","Bo‘sh joyning ikki tomonidagi qismni aniqladimmi?","Haqiqiy egani yoki olmosh almashtirgan otni topdimmi?","Qo‘shimcha qismning ikki tomonida bir xil belgi bormi?"]}]'::jsonb
from public.guides g where g.slug = 'grammar-rules-cheat-sheet'
on conflict (guide_id, locale) do nothing;

-- how-to-use-sat-master
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'how-to-use-sat-master', 'strategy', null, null, 1, 14, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'SAT MASTER’dan qanday foydalanish', 'Qayerdan boshlash va platformaning har bir bo‘limi nima uchun kerakligi: bepul diagnostika → natijalar → o‘quv reja → darslar → ko‘nikma bo‘yicha mashq → qo‘llanmalar → AI ustoz → har ikki haftada sinov imtihoni → tahlil. 8 haftalik reja va 30, 60, 90 daqiqalik kunlik tartib bilan.', '[{"type":"concept","heading":"SAT MASTER qanday ishlaydi","body":"SAT MASTER — shunchaki video darslar to‘plami emas, balki yopiq o‘quv sikli: **aniqlash → o‘rganish → mashq → o‘lchash → moslashtirish**. Har bir qadam keyingisi uchun ma’lumot beradi:\n\n- **Diagnostika** qaysi ko‘nikmalaringiz zaif ekanini ko‘rsatadi.\n- **O‘quv reja** vaqtingizni aynan shu ko‘nikmalarga taqsimlaydi.\n- **Darslar** va **qo‘llanmalar** mavzuni tushuntiradi, **Mashq** esa uni mustahkamlaydi.\n- **Sinov imtihonlari** umumiy holatingizni o‘lchaydi, **Tahlil** esa nimani o‘zgartirish kerakligini ko‘rsatadi.\n\nSavollar va matnlar haqiqiy testdagidek ingliz tilida, menyular, izohlar va maslahatlar esa o‘zbek tilida.\n\n**Muhim:** platformadagi barcha darajalar va taxminiy ballar SAT MASTER’ning o‘z hisob-kitobidir — College Board’ning rasmiy bali emas. Biz hech qachon ma’lum bir ballni kafolatlamaymiz: natija muntazam mehnatingizga bog‘liq."},{"type":"method","heading":"Yo‘l xaritasi: qayerdan boshlash va keyin nima qilish","steps":["**Profilingizni sozlang.** Ro‘yxatdan o‘tgach, 7 qadamli sozlash ochiladi: ism, interfeys tili, tayyorgarlik darajasi, maqsadli ball (400–1600), imtihon sanasi, kunlik o‘qish vaqti va fanlar. Kunlik vaqtni real belgilang: har kuni 30 daqiqa haftada bir marta 4 soat o‘qishdan samaraliroq. Bu javoblarni keyin **Sozlamalar**da o‘zgartirishingiz mumkin.","**Bepul diagnostikadan o‘ting** (**Diagnostika** bo‘limi). U barcha tariflarda bepul. Uch variant bor: ikkala bo‘lim bo‘yicha to‘liq diagnostika (taxminan 25 daqiqa), faqat Matematika (taxminan 20 daqiqa) yoki faqat O‘qish va yozish (taxminan 15 daqiqa). Qaysi birini tanlashni bilmasangiz — to‘liq diagnostikani tanlang.","**Natijalaringizni o‘qing:** har bir bo‘lim bo‘yicha daraja, eng zaif ko‘nikmalar va tavsiya etilgan darslar (quyida batafsil).","**O‘quv rejani tuzing** — natijalar sahifasidagi **O‘quv rejamni tuzish** tugmasi yoki **O‘quv reja** bo‘limi orqali (Starter, Pro va Premium tariflarida). Shundan keyin har kuni **Bosh sahifa**dagi “Bugungi o‘quv reja”dan boshlaysiz.","**Darslarni ko‘ring** (**Kurslar**): eng zaif ko‘nikmadan boshlang. Dars konspektini o‘qing va dars oxiridagi “Bu ko‘nikmani mashq qiling” havolasiga o‘ting.","**Ko‘nikma bo‘yicha mashq qiling** (**Mashq**): bitta ko‘nikma, bitta qiyinlik darajasi, 10–15 ta savol. Har bir javobdan keyin izohni o‘qing.","**Zaif ko‘nikma bo‘yicha qo‘llanmani o‘qing:** unda savolni qanday tanib olish, qadamma-qadam usul, tuzoqlar va kerakli inglizcha atamalar bor. Mashqda 60% dan past natija bergan ko‘nikmaning qo‘llanmasini qayta o‘qing.","**Tushunmagan joyingizni AI ustozdan so‘rang:** mashqdagi **AI ustozdan so‘rash** tugmasi savolni ustozga o‘zi olib boradi.","**Har ikki haftada bitta sinov imtihonini topshiring** (**Sinov imtihonlari**) — to‘liq, vaqtli va bir o‘tirishda. Ertasi kuni natijani tahlil qiling.","**Haftada bir marta Tahlil bo‘limini ko‘ring** va kerak bo‘lsa, rejani qayta tuzing. Keyin sikl 5-qadamdan yana davom etadi."]},{"type":"note","heading":"Diagnostika natijalarini qanday o‘qish","body":"Natijalar sahifasida har bir bo‘lim (masalan, Algebra yoki Craft and Structure) uchun aniqlik va daraja ko‘rsatiladi:\n\n- **Boshlang‘ich** — 40% dan past\n- **Rivojlanayotgan** — 40–59%\n- **Yaxshi** — 60–79%\n- **Yuqori** — 80% va undan yuqori\n\nUndan keyin “Ustida ishlash kerak bo‘lgan ko‘nikmalar” (eng past aniqlikdagilar) va “Boshlash uchun tavsiya etilgan darslar” keladi. “Savollarni ko‘rib chiqish” qismida har bir savolning to‘g‘ri javobi va izohi bor — xato qilgan savollaringizni albatta o‘qib chiqing.\n\nYodda tuting: diagnostika qisqa (to‘liq variantda har bir bo‘limdan atigi 2 ta savol), shuning uchun u hukm emas, balki boshlang‘ich nuqta. Bitta tasodifiy xato darajani o‘zgartirib yuborishi mumkin. Aniqroq rasm mashq va sinov imtihonlaridan keyin shakllanadi; bir necha haftadan so‘ng diagnostikani qayta topshirib, o‘zgarishni ko‘rishingiz ham mumkin.\n\nDiagnostika ball bermaydi: taxminiy ball oralig‘ini sinov imtihoni ko‘rsatadi. Diagnostika natijasi “SAT MASTER ichki diagnostikasi — rasmiy ball emas” deb belgilangan."},{"type":"note","heading":"Platformaning har bir bo‘limi nima uchun kerak","items":["**Bosh sahifa** — har kungi boshlash nuqtasi: ketma-ket kunlar, aniqlik, o‘qish vaqti, “O‘qishni davom ettirish”, “Bugungi o‘quv reja”, “Tavsiya etilgan mashqlar”, “Zaif ko‘nikmalar” va maqsadli ballingiz.","**Kurslar** — Matematika va O‘qish va yozish bo‘yicha ko‘nikmalarga ajratilgan qisqa video va matnli darslar. Video dars faqat haqiqatan ko‘rilgan qismi 90% ga yetganda tugallangan hisoblanadi: oldinga o‘tkazib yuborilgan qism hisobga olinmaydi. Matnli darsda konspektni yetarlicha vaqt o‘qish kerak.","**Mashq** — ko‘nikma, qiyinlik va savollar soni bo‘yicha o‘zingiz tuzadigan mashq, muharrirlar tayyorlagan “Mashqlar to‘plami”, xatolarni qayta ishlash va saqlangan savollar. Har bir javobdan keyin to‘g‘ri javob va izoh darhol ko‘rsatiladi.","**Diagnostika** — darajangizni aniqlaydigan qisqa vaqtli test. Javoblar va izohlar test yakunlangandan keyin ochiladi.","**Sinov imtihonlari** — to‘liq, vaqtli Digital SAT simulyatsiyasi: moslashuvchan ikkinchi modullar, bo‘limlar orasida ixtiyoriy 10 daqiqalik tanaffus va taxminiy ball oralig‘i.","**AI ustoz** — tushunchalar haqida savol berish, darajali maslahatlar va javob bergandan keyin bosqichma-bosqich tushuntirish.","**O‘quv reja** — natijalaringiz, imtihon sanasi va kunlik vaqtingiz asosida tuzilgan kunma-kun jadval.","**Tahlil** — bo‘lim va ko‘nikmalar bo‘yicha aniqlik, har bir savolga sarflangan o‘rtacha vaqt va vaqt o‘tishi bilan o‘zgarish.","**Natijalar** — barcha mashqlar, diagnostikalar va sinov imtihonlari ro‘yxati; har birini ochib, savollarni izohlari bilan qayta ko‘rish mumkin.","**Saqlanganlar** — keyinroq qaytish uchun saqlagan savol va darslaringiz. Saqlangan savollarni alohida mashq sifatida ishlash mumkin.","**Obuna** — tarifingiz va limitlaringiz; **Sozlamalar** — imtihon sanasi, kunlik vaqt, maqsadli ball va interfeys tili.","**O‘zbekcha qo‘llanma** — siz hozir o‘qiyotgan bo‘lim: har bir ko‘nikma bo‘yicha o‘zbekcha qo‘llanmalar va test strategiyasi. Darsda, mashqdagi javobdan keyin va natijalar sahifasida shu mavzuning qo‘llanmasiga havola chiqadi."]},{"type":"method","heading":"Mashq bo‘limida samarali ishlash","steps":["**Bitta ko‘nikmani tanlang:** Fan → Bo‘lim → Ko‘nikma → Qiyinlik → Savollar soni. Avval siz hali ko‘rmagan savollar, keyin xato qilganlaringiz beriladi.","**Qiyinlikni bosqichma-bosqich oshiring:** yangi ko‘nikmani **Oson** yoki **O‘rtacha** bilan boshlang; aniqlik 80% dan oshgach **Qiyin**ga o‘ting; imtihonga yaqinlashganda **Aralash**ni tanlang.","**Har bir izohni o‘qing** — to‘g‘ri javob bergan savollarnikini ham. Taxmin bilan topilgan to‘g‘ri javob — yashirin zaiflik.","**Qiyin yoki xato savolni saqlang** (**Savolni saqlash**). Izohni tushunmasangiz, **AI ustozdan so‘rash** tugmasini bosing.","**Mashq oxirida natijalarni ko‘ring:** ko‘nikmalar bo‘yicha aniqlik va har bir savolga sarflangan vaqt.","**2–3 kundan keyin** “Xatolarni qayta ishlash” orqali xato qilgan savollaringizni qayta yeching — bilimni xotirada mustahkamlashning eng ishonchli yo‘li shu."]},{"type":"method","heading":"AI ustozdan to‘g‘ri foydalanish","steps":["**Avval o‘zingiz urinib ko‘ring.** O‘zingiz o‘ylab ko‘rmagan savolning tushuntirishi tez unutiladi.","**Qotib qolsangiz — maslahat so‘rang.** Maslahatlar 1–3-darajali: har bir daraja biroz chuqurroq yordam beradi, lekin javobni aytmaydi. Mashqdagi savol bo‘yicha maslahatni javob berishdan oldin ham olish mumkin.","**Javob bergandan keyin — to‘liq tushuntirish.** “Bu savolni tushuntiring” tushuncha, xatoingiz, bosqichma-bosqich yechim va javobni beradi. Yakunlangan diagnostika va sinov imtihonlarining natijalar sahifasidan ham so‘rash mumkin.","**O‘z yechimingizni tekshirtiring:** “Xatoimni toping”ni tanlab, yechimingizni yozing — ustoz xato qayerda ekanini ko‘rsatadi.","**Tushunmasangiz — boshqacha so‘rang:** “Boshqacha tushuntiring” yoki “Soddaroq”.","**Mustahkamlang:** “O‘xshash savol yaratish” yangi savol tuzadi. U sizga ko‘rsatilishidan oldin ikkinchi mustaqil yechim bilan tekshiriladi, lekin muharrirlar ko‘rib chiqmagani uchun alohida belgi bilan beriladi.","**Cheklovlarni biling:** diagnostika yoki sinov imtihoni davomida AI ustoz bu savollar haqida gapirmaydi — avval testni yakunlang. Kunlik so‘rovlar soni tarifga bog‘liq, shuning uchun avval platformadagi izohni o‘qing va ustozdan faqat tushunmagan joyingizni so‘rang."]},{"type":"note","heading":"O‘quv reja qanday tuziladi","body":"O‘quv reja (Starter, Pro va Premium tariflarida) diagnostika va mashqdagi aniqligingiz, imtihon sanasi, kunlik o‘qish vaqti va tanlangan fanlar asosida tuziladi. Asosiy qoidalar:\n\n- Vaqt bo‘limlar orasida **aniqligingiz qanchalik past** va **bo‘limning SATdagi ulushi qanchalik katta** ekaniga qarab taqsimlanadi.\n- Oddiy kunda ko‘pi bilan bitta dars, keyin 15–25 daqiqalik mashq bloklari bo‘ladi.\n- Har yettinchi kun noto‘g‘ri javoblarni takrorlash bilan boshlanadi.\n- Oxirgi olti haftada har ikki haftada bitta to‘liq sinov imtihoni rejalashtiriladi (imtihondan 38, 24 va 10 kun oldin), agar platformada chop etilgan sinov imtihoni bo‘lsa.\n- Imtihondan oldingi oxirgi uch kun — faqat yengil takrorlash.\n- Imtihon sanasi belgilanmagan bo‘lsa, reja 8 haftaga (56 kun) tuziladi.\n\nMashq vazifasi shu ko‘nikma bo‘yicha belgilangan sondagi savolga javob berganingizda, dars vazifasi esa darsni tugatganingizda avtomatik bajariladi. Maqsadli ball, imtihon sanasi yoki kunlik vaqt o‘zgarsa, **Rejani qayta tuzish** tugmasini bosing — yangi reja so‘nggi natijalaringizni hisobga oladi.\n\nBepul tarifda o‘quv reja yo‘q: quyidagi 8 haftalik reja va kunlik tartibga o‘zingiz amal qiling."},{"type":"note","heading":"Sinov imtihonini topshirish va tahlil qilish","items":["**Real sharoit yarating:** imtihonni bir o‘tirishda, telefonsiz, tinch joyda topshiring. To‘liq imtihon tanaffussiz 2 soat 14 daqiqa davom etadi, bo‘limlar orasida esa ixtiyoriy 10 daqiqalik tanaffus bor.","**Taymer serverda ishlaydi:** sahifani yopsangiz ham modul vaqti to‘xtamaydi, vaqt tugaganda esa modul avtomatik topshiriladi. Javoblar darhol saqlanadi.","**Vositalardan foydalaning:** ko‘rib chiqish uchun belgilash, variantlarni o‘chirish, savollar navigatori, Matematikada grafik kalkulyator va formulalar ma’lumotnomasi. Batafsil — “Test ilovasidagi vositalar” qo‘llanmasida.","**Ikkinchi modul moslashadi:** 1-moduldagi natijangizga qarab 2-modul qiyinroq yoki osonroq bo‘ladi. Yo‘naltirish SAT MASTER’ning o‘z chegara qoidasiga asoslanadi va natijalar sahifasida tushuntiriladi.","**Taxminiy ball oralig‘i** har bir bo‘lim uchun ±40, jami uchun ±80 ball oralig‘ida ko‘rsatiladi. Formula ochiq — natijalar sahifasidagi “Qanday hisoblaymiz” qismida. Bu SAT MASTER bahosi, College Board’ning rasmiy bali emas: uni mashq signali sifatida qabul qiling.","**Ertasi kuni tahlil qiling:** har bir xatoni uch turdan biriga ajrating — *bilim yetishmadi* (dars va qo‘llanmaga qayting), *e’tiborsizlik* (savolni oxirigacha o‘qish va tekshirish odatini kuchaytiring), *vaqt yetmadi* (“Vaqtni boshqarish va taxmin qilish” qo‘llanmasi). Keyin rejani qayta tuzing.","**Tarif bo‘yicha limit:** Starter tarifida oyiga 1 ta, Pro’da 4 ta sinov imtihoni bor, Premium’da cheklanmagan, bepul tarifda esa sinov imtihonlari yo‘q. Starter’da imtihonlarni imtihon sanasiga yaqinroq haftalarga saqlang, oraliq haftalarda esa aralash qiyinlikdagi uzunroq mashqni vaqtni kuzatib ishlang."]},{"type":"note","heading":"Tahlil bo‘limini qanday o‘qish","items":["**Bo‘lim va ko‘nikmalar bo‘yicha aniqlik** — “Avval eng zaiflari” saralashi bilan oching: ro‘yxat boshidagi 2–3 ko‘nikma keyingi haftaning asosiy ishi bo‘ladi.","**Har bir savolga o‘rtacha vaqt** Digital SAT sur’ati bilan solishtiriladi. Aniqlik yaxshi-yu, vaqt ko‘p bo‘lsa — sur’at ustida ishlang; vaqt kam-u, aniqlik past bo‘lsa — shoshilyapsiz.","**So‘nggi 30 kun** — kunlik aniqlik va o‘qish vaqti: muntazam shug‘ullanayotganingizni shu yerda ko‘rasiz.","**Sinov imtihonlari bo‘yicha taxminlar** — bitta imtihondagi o‘zgarishga emas, umumiy yo‘nalishga qarang.","**Kam ma’lumotdan xulosa chiqarmang:** 3–4 ta javob asosidagi aniqlik tasodifiy bo‘lishi mumkin.","Bepul tarifda asosiy tahlil ochiq (umumiy aniqlik, javoblar soni, o‘qish vaqti, fanlar bo‘yicha aniqlik); batafsil tahlil pullik tariflarda."]},{"type":"time","heading":"8 haftalik reja: hafta-ba-hafta","items":["**1-hafta — Boshlash.** Profilni sozlang, to‘liq diagnostikadan o‘ting, o‘quv rejani tuzing. “Digital SAT formati” va “Vaqtni boshqarish va taxmin qilish” qo‘llanmalarini o‘qing. Eng zaif ikki ko‘nikmadan boshlang: Oson va O‘rtacha mashq.","**2-hafta — Asosni mustahkamlash.** Zaif ko‘nikmalar bo‘yicha darslar va qo‘llanmalar. O‘qish va yozishda “Grammatika qoidalari” qo‘llanmasidan boshlang — bu qoidalar tez o‘rganiladi. Har kuni 8–10 ta yangi inglizcha so‘z.","**3-hafta — 1-sinov imtihoni.** Hafta davomida mashq, hafta oxirida birinchi to‘liq sinov imtihoni. Ertasi kuni har bir xatoni tahlil qiling va rejani qayta tuzing.","**4-hafta — Kengaytirish.** Imtihonda eng ko‘p xato qilingan 3 ta bo‘limga e’tibor bering; O‘rtacha va Qiyin savollar. Matematikada “Desmos kalkulyatori” qo‘llanmasidagi usullarni mashq qiling.","**5-hafta — 2-sinov imtihoni.** Natijani birinchisi bilan bo‘limlar bo‘yicha solishtiring: qayerda o‘sish bor, qayerda yo‘q? Tahlil bo‘limida har bir savolga sarflangan vaqtni tekshiring.","**6-hafta — Qiyin savollar va sur’at.** Qiyin va Aralash mashqlar, vaqtni kuzatib ishlash. “Xatolarni qayta ishlash” bilan eski xatolarni yoping.","**7-hafta — 3-sinov imtihoni.** Imtihonni haqiqiy test boshlanadigan soatda topshiring. Tahlildan keyin faqat aniq zaif joylarni tuzating — yangi katta mavzu boshlamang.","**8-hafta — Yakuniy takrorlash.** Saqlangan savollar, xatolar, formulalar, grammatika qoidalari va javobni o‘zingiz yozadigan savollar (SPR) qoidalari. Oxirgi 3 kun — yengil takrorlash va yaxshi uyqu."]},{"type":"time","heading":"Kunlik tartib: 30, 60 yoki 90 daqiqa","items":["**30 daqiqa:** 5 daqiqa — kechagi xatolarni takrorlash (Saqlanganlar yoki Natijalar); 20 daqiqa — bitta ko‘nikma bo‘yicha 10–12 ta mashq savoli; 5 daqiqa — izohlar va 5 ta yangi so‘z. Haftada 2–3 marta mashq o‘rniga bitta dars ko‘ring.","**60 daqiqa:** 5 daqiqa — takrorlash; 15–20 daqiqa — bitta dars yoki ko‘nikma qo‘llanmasi; 25 daqiqa — shu ko‘nikma bo‘yicha mashq; 10 daqiqa — xatolar tahlili (AI ustoz bilan) va yangi so‘zlar.","**90 daqiqa:** 10 daqiqa — takrorlash; 20 daqiqa — dars; 25 daqiqa — Matematika mashq bloki; 25 daqiqa — O‘qish va yozish mashq bloki; 10 daqiqa — tahlil va yangi so‘zlar.","**Sinov imtihoni kuni** boshqa ish rejalashtirmang: imtihon tanaffus bilan taxminan ikki yarim soat oladi. Tahlilni ertasiga qoldiring.","**Bepul tarifda** kuniga 20 ta mashq savoli bor — bu 30 daqiqalik tartibga yetadi. Ko‘proq vaqtingiz bo‘lsa, qolganini qo‘llanmalarga, bepul namuna darslarga va natijalar sahifasidagi izohlarni qayta o‘qishga sarflang.","**Kun o‘tkazib yuborsangiz,** ertasi kuni ikki barobar ishlashga urinmang — odatdagi tartibni davom ettiring. Muntazamlik bir kunlik hajmdan muhimroq."]},{"type":"note","heading":"Tariflar: qaysi imkoniyat qayerda","body":"Diagnostika barcha tariflarda bepul. Qolgan imkoniyatlar tarifga bog‘liq (quyida joriy shartlar; aniq narx va limitlar **Obuna** sahifasida ko‘rsatiladi):\n\n- **Free (bepul):** diagnostika, bepul namuna darslar, kuniga 20 ta mashq savoli, kuniga 3 ta AI ustoz so‘rovi, asosiy tahlil. O‘quv reja va sinov imtihonlari yo‘q.\n- **Starter:** barcha darslar, kuniga 100 ta mashq savoli, kuniga 15 ta AI so‘rovi, oyiga 1 ta sinov imtihoni, to‘liq tahlil, o‘quv reja.\n- **Pro:** barcha darslar, cheklanmagan mashq, kuniga 50 ta AI so‘rovi, oyiga 4 ta sinov imtihoni, to‘liq tahlil, o‘quv reja.\n- **Premium:** barcha darslar, cheklanmagan mashq va sinov imtihonlari, kuniga 150 ta AI so‘rovi, to‘liq tahlil, o‘quv reja.\n\nObuna bir oyga oldindan to‘lanadi va hisobingizdan avtomatik yechib olinmaydi. Bekor qilsangiz, kirish to‘langan davr oxirigacha saqlanadi."},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Muntazamlik hajmdan muhim:** har kuni 30 daqiqa haftada bir marta uzoq o‘qishdan ko‘ra ko‘proq natija beradi. Bosh sahifadagi ketma-ket kunlar hisoblagichini uzmaslikka harakat qiling.","**Izohsiz mashq — vaqt isrofi:** savolni ishlab, izohni o‘qimasangiz, xuddi shu xatoni yana qilasiz.","**Faqat kuchli tomoningizni mashq qilmang:** bilgan mavzuda ishlash yoqimli, lekin ball zaif ko‘nikmalar hisobiga o‘sadi.","**Imtihon o‘lchaydi, o‘rgatmaydi:** tahlilsiz ketma-ket sinov imtihonlari topshirish natijani o‘zgartirmaydi.","**AI ustozdan javobni darhol so‘ramang:** avval maslahat, keyin tushuntirish.","**Taxminiy ballga haddan tashqari tayanmang:** u rasmiy emas va bir imtihondan ikkinchisiga tebranishi mumkin. Umumiy yo‘nalishga qarang.","**Inglizcha atamalarni inglizcha eslab qoling:** izohlar o‘zbekcha, lekin testda savollarni ingliz tilida o‘qiysiz."]},{"type":"checklist","heading":"Kun oxirida o‘zingizni tekshiring","items":["Bugungi reja vazifalarini bajardimmi?","Har bir xatoimning sababini bilamanmi?","Qiyin savollarni saqladimmi?","Bugun kamida 5 ta yangi inglizcha so‘z o‘rgandimmi?","Ertaga nimadan boshlashni bilamanmi?"]}]'::jsonb
from public.guides g where g.slug = 'how-to-use-sat-master'
on conflict (guide_id, locale) do nothing;

-- inference-and-margin-of-error
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'inference-and-margin-of-error', 'skill', (select id from public.skills where code = 'inference_margin_of_error'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'inference_margin_of_error'), 14, 9, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Tanlanma bo‘yicha xulosa va xatolik chegarasi', 'Tasodifiy tanlanma natijalaridan bosh to‘plam haqida qanday xulosa chiqarish mumkinligi, xatolik chegarasi (margin of error) nimani anglatishi va tanlanma hajmi unga qanday ta’sir qilishi.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Butun guruhni (masalan, shaharning barcha aholisini) so‘rab chiqish qiyin, shuning uchun uning bir qismi o‘rganiladi va natija butun guruhga tatbiq etiladi.\n\n- **Population (bosh to‘plam)** — xulosa chiqarmoqchi bo‘lgan butun guruh.\n- **Sample (tanlanma)** — haqiqatda o‘rganilgan qism. Tanlanma **tasodifiy** (random) tanlangan bo‘lsagina, uning natijasi bosh to‘plamni ifodalaydi deb hisoblash mumkin.\n- **Sample statistic** — tanlanmadagi ulush yoki o‘rtacha (masalan, $58\\%$ yoki 3.2 soat). U bosh to‘plamdagi haqiqiy qiymatning **taxmini** (estimate).\n\n**Margin of error (xatolik chegarasi)** taxmin qanchalik aniq ekanini ko‘rsatadi. Bosh to‘plamdagi haqiqiy qiymat uchun ehtimoliy (plausible) oraliq: $$\\text{estimate} \\pm \\text{margin of error}$$ Masalan, $58\\%$ va 4.5 foiz punkt → $53.5\\%$ dan $62.5\\%$ gacha. Bu oraliqdagi har qanday qiymat ehtimoliy, lekin aniq qiymat noma’lum.\n\n**Xatolik chegarasiga nima ta’sir qiladi:**\n\n- Tanlanma **kattaroq** bo‘lsa (boshqa sharoitlar bir xil), xatolik chegarasi **kichikroq** bo‘ladi.\n- Ma’lumotlar **ko‘proq tarqalgan** bo‘lsa (standart chetlanish katta), xatolik chegarasi **kattaroq** bo‘ladi.\n- Ishonch darajasi (confidence level, masalan $95\\%$) yuqoriroq bo‘lsa, oraliq kengroq bo‘ladi.\n\nBosh to‘plamdagi umumiy sonni baholash uchun tanlanmadagi ulushni bosh to‘plam hajmiga ko‘paytiring: 200 kishidan 30 tasi “ha” desa, 50 000 aholida taxminan $0.15 \\times 50\\,000 = 7500$ kishi “ha” deydi."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["*“A random sample of … was selected from …”*, *“selected at random”* — tanlanma haqidagi savol: avval qaysi bosh to‘plamdan tanlanganini aniqlang.","*“The margin of error for the estimate is 4.5 percentage points”*, *“with an associated margin of error of …”* — oraliq quring: taxmin ± xatolik.","*“Which of the following is the most appropriate conclusion?”*, *“Which statement is best supported by the data?”* — xulosa tanlash: qamrov (kim haqida) va qat’iylik darajasi (exactly yoki plausible) tekshiriladi.","*“Based on the sample, what is the best estimate of the number of …?”* — ulushni bosh to‘plam hajmiga ko‘paytirish.","*“Which change would most likely decrease the margin of error?”* — javob odatda tanlanma hajmini oshirish."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Bosh to‘plamni aniqlang.** Tanlanma aynan qaysi guruhdan olingan: shahar saylovchilari, bitta maktab o‘quvchilari, kutubxonaga kelganlar? Xulosa faqat shu guruhga tegishli bo‘lishi mumkin.","**Tanlov usulini tekshiring.** Tasodifiy (random) bo‘lsa — umumlashtirish mumkin. Ixtiyoriy javob berganlar (volunteers) yoki qo‘l ostidagi qulay guruh bo‘lsa — natija bosh to‘plamni ifodalamasligi mumkin.","**Taxminni hisoblang:** ulush yoki o‘rtachani toping; kerak bo‘lsa, bosh to‘plam hajmiga ko‘paytiring.","**Oraliq quring:** $\\text{estimate} - \\text{margin of error}$ va $\\text{estimate} + \\text{margin of error}$. Ikkala chegarani qoralamaga yozib qo‘ying.","**Har bir variantni ikki savol bilan sinang:** (1) kim haqida gapiryapti — to‘g‘ri bosh to‘plam haqidami? (2) qanchalik qat’iy — *exactly*, *all*, *proves* kabi so‘zlar bormi? To‘g‘ri javob odatda *plausible*, *likely*, *between … and …* kabi ehtiyotkor ifodalarda bo‘ladi.","**Ikki oraliqni solishtirishda** ular ustma-ust tushadimi, qarang: ustma-ust tushsa, bir guruhning qiymati ikkinchisinikidan katta deb ishonch bilan aytib bo‘lmaydi."]},{"type":"example","heading":"Namuna 1: eng to‘g‘ri xulosani tanlash","example":{"problem":"A researcher selected 400 registered voters at random from a city and asked whether they support building a new public library. Of those surveyed, 58% said they support it. The margin of error for this estimate is 4.5 percentage points. Which of the following is the most appropriate conclusion?","choices":["Exactly 58% of the city''s registered voters support building the new library.","It is plausible that between 53.5% and 62.5% of the city''s registered voters support building the new library.","It is plausible that between 53.5% and 62.5% of all adults in the country support building the new library.","Because the margin of error is 4.5 percentage points, 4.5% of the voters surveyed gave inaccurate answers."],"solution":["Bosh to‘plam — **shahardagi ro‘yxatga olingan saylovchilar**: tanlanma aynan ulardan tasodifiy olingan.","Oraliq: $58 - 4.5 = 53.5$ va $58 + 4.5 = 62.5$, ya’ni $53.5\\%$ dan $62.5\\%$ gacha.","B variant to‘g‘ri bosh to‘plam va to‘g‘ri oraliqni ehtiyotkor *“plausible”* so‘zi bilan ifodalaydi — bu eng to‘g‘ri xulosa.","Nega A xato: $58\\%$ — faqat taxmin; *“exactly”* so‘zi xatolik chegarasini butunlay e’tiborsiz qoldiradi.","Nega C xato: oraliq to‘g‘ri, lekin bosh to‘plam noto‘g‘ri — bitta shahar saylovchilari butun mamlakat kattalarini ifodalamaydi.","Nega D xato: xatolik chegarasi tanlanma tasodifiy olinganidan kelib chiqadigan noaniqlikni bildiradi, javob berganlarning xato qilganini emas."],"answer":"B"}},{"type":"example","heading":"Namuna 2: bosh to‘plam uchun taxmin (javobni o‘zingiz yozasiz)","example":{"problem":"A forest has 12,000 trees. A biologist examined a random sample of 150 trees from the forest and found that 18 of them showed signs of a fungal disease. Based on the sample, what is the best estimate of the number of trees in the forest that show signs of the disease?","solution":["Tanlanmadagi ulush: $\\frac{18}{150} = 0.12$, ya’ni $12\\%$.","Tanlanma tasodifiy, demak bu ulush butun o‘rmon uchun eng yaxshi taxmin: $0.12 \\times 12{,}000 = 1440$.","Proporsiya bilan ham yechish mumkin: $\\frac{18}{150} = \\frac{x}{12{,}000}$, bundan $x = 1440$.","Tuzoqlar: **18** — faqat tanlanmadagi son; **12** — foiz. Savol butun o‘rmondagi daraxtlar sonini so‘rayapti.","Javobni vergulsiz kiriting: **1440**.","Tekshiruv: $\\frac{1440}{12{,}000} = 0.12 = \\frac{18}{150}$ ✓."],"answer":"1440"}},{"type":"example","heading":"Namuna 3: tanlanma hajmi va xatolik chegarasi","example":{"problem":"Two researchers want to estimate the mean height of the sunflowers in the same large field. Researcher A measures a random sample of 50 sunflowers, and Researcher B measures a random sample of 200 sunflowers. Both researchers use the same method. Which of the following is most likely true?","choices":["The margin of error for Researcher A''s estimate is smaller than the margin of error for Researcher B''s estimate.","The margin of error for Researcher B''s estimate is smaller than the margin of error for Researcher A''s estimate.","The margins of error are equal because both samples come from the same field.","Researcher B''s estimate is exactly equal to the mean height of all the sunflowers in the field."],"solution":["Ikkala tanlanma ham bir xil bosh to‘plamdan tasodifiy olingan va bir xil usulda o‘lchangan — ular faqat **hajmi** bilan farq qiladi.","Tanlanma kattaroq bo‘lsa, taxmin aniqroq, ya’ni xatolik chegarasi kichikroq bo‘ladi. B tadqiqotchining tanlanmasi (200) kattaroq — B variant.","Nega A xato: munosabat teskari olingan.","Nega C xato: bir xil maydon bir xil xatolik chegarasini anglatmaydi — u tanlanma hajmiga bog‘liq.","Nega D xato: katta tanlanma ham faqat taxmin beradi; *“exactly”* hech qachon kafolatlanmaydi."],"answer":"B"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Foiz punktlari:** taxmin foizda bo‘lsa, xatolik chegarasi odatda foiz punktlarda beriladi: $58\\%$ va 4.5 punkt → $53.5\\%$–$62.5\\%$. $58$ ning $4.5\\%$ ini hisoblamang.","**Qamrov (scope):** xulosa faqat tanlanma olingan bosh to‘plamga tegishli. Sport zaliga keluvchilardan olingan tanlanma butun shahar aholisi haqida xulosa bermaydi.","**Tasodifiylik hajmdan muhimroq:** 5000 ta ixtiyoriy javob tasodifiy tanlangan 400 kishining javobidan ishonchliroq emas.","**Ishonch darajasining ma’nosi:** $95\\%$ ishonch “aholining $95\\%$ i shu oraliqda” degani emas; bu oraliq tuzish usuli haqiqiy qiymatni ko‘pchilik hollarda qamrab olishini bildiradi.","**Oraliq ichidagi qiymatlar teng darajada ehtimoliy:** “haqiqiy qiymat aynan $58\\%$” yoki “$60\\%$ dan katta bo‘lishi shart” degan xulosalar noto‘g‘ri."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Mutlaq so‘zlar:** *exactly*, *all*, *must*, *proves* — deyarli har doim noto‘g‘ri variant belgisi.","**Ortiqcha umumlashtirish:** oraliq to‘g‘ri, lekin bosh to‘plam noto‘g‘ri (namuna 1, C).","**Xatolik chegarasini noto‘g‘ri talqin qilish:** “4.5% respondent xato javob bergan” (namuna 1, D).","**Hajm va aniqlik munosabatini teskari olish** (namuna 3, A).","**Tanlanmadagi sonni javob deb berish:** bosh to‘plam uchun taxmin so‘ralganda 18 yoki 12 ni tanlash (namuna 2).","**Ustma-ust tushuvchi oraliqlardan qat’iy xulosa:** A guruhda $40\\% \\pm 5\\%$, B guruhda $44\\% \\pm 5\\%$ bo‘lsa, “B guruhda ulush kattaroq” deb ishonch bilan aytib bo‘lmaydi."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Bu savollar asosan mantiqqa tayanadi: **45–75 soniya**. Hisob kam — ko‘pi bilan bitta bo‘lish va bitta ko‘paytirish.","Avval savol matnidagi ikki narsani belgilang: *qaysi bosh to‘plam* va *qanday tanlangan*. Keyin variantlarni o‘qing — shu ikki ma’lumot bilan ko‘p variant 10–15 soniyada yo‘qqa chiqadi.","Desmos bu turda deyarli kerak emas; oddiy hisob yetarli ($18 / 150 \\cdot 12000$).","Ikki variant qolsa, ma’lumot ruxsat bergan darajadagi ehtiyotkorroq gapni tanlang: statistik xulosa savollarida to‘g‘ri javob odatda ortiqcha qat’iylikdan xoli bo‘ladi."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"population","meaning":"bosh to‘plam: xulosa chiqariladigan butun guruh"},{"term":"sample","meaning":"tanlanma: haqiqatda o‘rganilgan qism"},{"term":"random sample / selected at random","meaning":"tasodifiy tanlanma: har bir a’zoning tanlanish imkoniyati teng"},{"term":"estimate","meaning":"taxmin — tanlanmadan hisoblangan qiymat"},{"term":"margin of error","meaning":"xatolik chegarasi: taxminning ± noaniqligi"},{"term":"plausible","meaning":"ehtimoliy, ishonarli — oraliq ichida bo‘lishi mumkin"},{"term":"sample proportion / sample mean","meaning":"tanlanmadagi ulush / tanlanmadagi o‘rtacha"},{"term":"confidence level","meaning":"ishonch darajasi (masalan, 95%)"},{"term":"percentage points","meaning":"foiz punktlari: foizlar orasidagi oddiy ayirma"},{"term":"representative","meaning":"vakillik qiluvchi: bosh to‘plamni to‘g‘ri aks ettiruvchi (tanlanma)"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Xulosa tanlanma olingan bosh to‘plam haqidami?","Tanlanma tasodifiy olinganmi?","Oraliqni to‘g‘ri qurdimmi (taxmin ± xatolik chegarasi)?","Variantda “exactly”, “all” kabi ortiqcha qat’iy so‘zlar yo‘qmi?"]}]'::jsonb
from public.guides g where g.slug = 'inference-and-margin-of-error'
on conflict (guide_id, locale) do nothing;

-- inferences
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'inferences', 'skill', (select id from public.skills where code = 'inferences'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'inferences'), 26, 10, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Inferences: matndan mantiqiy xulosa chiqarish', 'Matn oxiridagi bo‘sh joyni matndagi ma’lumotlardan mantiqan kelib chiqadigan xulosa bilan to‘ldirish. To‘g‘ri javob “bo‘lishi mumkin” emas, “matnga ko‘ra shunday bo‘lishi kerak” bo‘lgan fikr.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Inferences savollari **Information and Ideas** domeniga kiradi va ko‘p o‘quvchilar uchun Reading and Writing’dagi eng qiyin savollardan biri. Matn bir nechta fakt yoki tadqiqot tavsifini beradi, oxirgi jumla esa bo‘sh joy bilan tugaydi. Siz shu bo‘shliqni **mantiqan** to‘ldiradigan variantni tanlaysiz.\n\nBu yerda *inference* — ijodiy taxmin emas. U matematikadagi isbotga o‘xshaydi: matndagi har bir jumla — shart, to‘g‘ri javob esa shu shartlardan **muqarrar ravishda** kelib chiqadigan xulosa. Agar variantni to‘g‘ri deb hisoblash uchun matnda yo‘q qo‘shimcha taxmin kerak bo‘lsa, u noto‘g‘ri.\n\nMatnlar ko‘pincha ilmiy tajribalar (gipoteza → tajriba → natija), tarixiy faktlar yoki ijtimoiy tadqiqotlar haqida bo‘ladi."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["*Which choice most logically completes the text?* — bu savolning standart shakli.","Matn bo‘sh joy bilan tugaydi, undan oldin ko‘pincha xulosa signali turadi: *This suggests that…*, *Therefore,…*, *…the researchers concluded that…*, *…most likely…*.","Variantlar — to‘liq gap bo‘laklari (ko‘pincha *that* dan keyingi qism), alohida so‘zlar emas.","Farqlang: variantlar alohida so‘zlar bo‘lsa — bu Words in Context; variantlar *However, Therefore, In addition* kabi bog‘lovchilar bo‘lsa (*most logical transition*) — bu Expression of Ideas domenidagi transitions savoli."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Savolni o‘qing va bu inference ekanini tasdiqlang** (*most logically completes the text*).","**Matnni sekin, jumlama-jumla o‘qing.** Har bir jumla — xulosa uchun bitta “g‘isht”. Ayniqsa *only, not, all, some, most, if, unless, although* so‘zlariga e’tibor bering: ular mantiqni butunlay o‘zgartiradi.","**Mantiqiy zanjirni qisqa tuzing** (xayolan yoki qog‘ozda): “Ikki taxmin bor: A va B. Tajribada A ham, B ham yo‘q. Natija baribir bor.” Zanjirda nima yetishmayapti?","**Bo‘sh joydan oldingi so‘zlarga qarang:** ular qanday xulosa kutilayotganini aytadi — natija (*therefore*), izoh (*because*), bashorat (*would most likely*) yoki tadqiqotchining xulosasi (*suggests that*).","**O‘z xulosangizni bashorat qiling,** keyin variantlarni o‘qing.","**“Albatta” testini qo‘llang:** har bir variant uchun “Matn to‘g‘ri bo‘lsa, bu ham **albatta** to‘g‘rimi?” deb so‘rang. Faqat “bo‘lishi mumkin” darajasidagi variantlarni, matnga zid variantlarni va yangi mavzu qo‘shadigan variantlarni o‘chiring."]},{"type":"example","heading":"Namuna 1: ilmiy tajribadan xulosa","example":{"problem":"Which choice most logically completes the text?","passage":"Many plants close their flowers at night, and botanists have proposed two explanations for this behavior. One is that closing protects the flowers'' pollen from cold night air. The other is that closing keeps out insects that are active only at night and that eat pollen without carrying it to other flowers. In a greenhouse kept at the same warm temperature day and night, with no night-active insects present, a team found that one such species still closed its flowers every night. This result suggests that ______","choices":["neither cold air nor night-active insects are needed to trigger the nightly closing of this species'' flowers.","the flowers of this species close at night mainly to protect their pollen from cold air.","night-active insects are the greatest threat to flowers grown in greenhouses.","this species would stop closing its flowers if it were moved outdoors."],"solution":["**Shartlar:** (1) ikki taxmin bor — gullar sovuqdan yoki tungi hasharotlardan himoyalanish uchun yopiladi. (2) Issiqxonada **sovuq ham, tungi hasharotlar ham yo‘q**. (3) Gullar baribir har kecha yopildi.","**Mantiq:** sabab deb taxmin qilingan ikkala omil olib tashlandi, lekin natija (yopilish) saqlanib qoldi. Demak, bu turda gullarning yopilishi boshlanishi uchun bu omillar **shart emas**.","**A** — aynan shu xulosa: yopilishni boshlash uchun sovuq havo ham, hasharotlar ham zarur emas. ✓","**B** noto‘g‘ri — natijadan kelib chiqmaydi: tajribada sovuq havo umuman bo‘lmagan, gullar esa baribir yopilgan. Bunday natija sovuqning asosiy rolini tasdiqlamaydi, aksincha unga shubha uyg‘otadi.","**C** noto‘g‘ri: issiqxonada tungi hasharotlar umuman bo‘lmagan, ular haqida hech qanday natija yo‘q. “Eng katta xavf” — matnda yo‘q da’vo.","**D** noto‘g‘ri: tajriba faqat issiqxonada o‘tkazilgan, ochiq havoda nima bo‘lishi haqida ma’lumot yo‘q. Gullar taxmin qilingan sabablar yo‘q joyda ham yopilgan bo‘lsa, ochiq havoda yopilmasligini kutishga asos yo‘q."],"answer":"A"}},{"type":"example","heading":"Namuna 2: tarixiy matndan xulosa","example":{"problem":"Which choice most logically completes the text?","passage":"Historians studying a fifteenth-century trading town in Central Asia have found hundreds of business letters written by its merchants. Nearly all of the letters are written in Persian, even though most of the town''s residents spoke a Turkic language at home. The letters were sent to partners in cities as distant as Tabriz and Herat, where Persian was widely used in trade and government. Based on this evidence, the historians suggest that the town''s merchants most likely ______","choices":["did not know how to write in the Turkic language they spoke at home.","had been born in Tabriz or Herat and later moved to the trading town.","stopped trading with distant cities when Persian became less common there.","wrote in Persian because it allowed them to communicate with business partners in distant cities."],"solution":["**Shartlar:** (1) xatlarning deyarli hammasi forscha; (2) shahar aholisining ko‘pchiligi uyda turkiy tilda gaplashgan; (3) xatlar Tabriz va Hirot kabi uzoq shaharlardagi sheriklarga yuborilgan; (4) u yerlarda savdo va boshqaruvda fors tili keng qo‘llanilgan.","**Bashorat:** savdogarlar uyda boshqa tilda gaplashsa ham, xatlarni forscha yozgan, chunki sheriklari bu tilni tushungan. Ya’ni fors tili — savdo aloqalari tili bo‘lgan.","**A** noto‘g‘ri — **ortiqcha kuchli**: forscha yozish ularning turkiy tilda yoza olmaganini isbotlamaydi. Ular forschani shunchaki sheriklari uchun tanlagan bo‘lishi mumkin.","**B** noto‘g‘ri: savdogarlarning qayerda tug‘ilgani haqida matnda hech narsa yo‘q. Bu — asossiz taxmin.","**C** noto‘g‘ri: matnda fors tilining kamayishi yoki savdoning to‘xtashi haqida ma’lumot yo‘q. Variant matn doirasidan butunlay chiqib ketadi.","**D** — barcha shartlarni bog‘laydi va yangi taxmin talab qilmaydi. ✓"],"answer":"D"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**“Could be true” ≠ “must be true”.** Ko‘p noto‘g‘ri variantlar hayotda bo‘lishi mumkin, lekin matndan **kelib chiqmaydi**. Inference savolida faqat matn kafolatlaydigan xulosa to‘g‘ri.","**Har bir so‘z muhim.** *only, some, most, all, not, never, unless* — bitta so‘z xulosani butunlay o‘zgartiradi. *Some plants* haqidagi matndan *all plants* haqida xulosa chiqarib bo‘lmaydi.","**Ehtiyotkor xulosa ko‘pincha to‘g‘ri.** Matn ehtiyotkor bo‘lsa (*suggests, may, likely*), to‘g‘ri javob ham odatda cheklangan bo‘ladi (*at least some, in this species*). *Always, proves, all* kabi so‘zli variantlar ko‘pincha haddan tashqari kuchli — lekin bu qat’iy qoida emas, faqat signal.","**Tajriba matnlarida** tuzilish odatda shunday: gipoteza → tajriba sharoiti → natija → xulosa. Natija gipotezani tasdiqladimi yoki rad etdimi? Qaysi omil olib tashlandi va nima o‘zgarmadi? Javob shu yerda.","**Tashqi bilim ishlatmang.** Mavzuni yaxshi bilsangiz ham, matnda berilmagan fakt asosida xulosa qilmang.","**Ingliz tili bo‘yicha maslahat — mantiq so‘zlari:** *if… then* — agar… u holda; *unless* — agar… bo‘lmasa; *only if* — faqat… bo‘lgandagina; *neither… nor* — na… na; *rather than* — …o‘rniga; *even though / although* — garchi… bo‘lsa ham; *whereas* — holbuki. Bo‘sh joydan oldingi jumlani ayniqsa diqqat bilan tarjima qiling: *This suggests that…* — “Bu shuni ko‘rsatadiki…”. Notanish ilmiy atamani (o‘simlik, kasallik, joy nomi) “X” deb qabul qiling — mantiq zanjiri uchun uning aniq ma’nosi odatda kerak emas."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Bo‘lishi mumkin, lekin asoslanmagan:** mantiqan ishonarli, ammo matndan kelib chiqmaydi (2-namunadagi B).","**Haddan tashqari kuchli xulosa:** matn kichik bir narsani ko‘rsatadi, variant esa katta da’vo qiladi (2-namunadagi A).","**Natijaga zid xulosa:** tajriba aynan shu omilni olib tashlagan bo‘lsa ham, uni asosiy sabab deb ko‘rsatish (1-namunadagi B).","**Mavzudan chiqish:** variant matnda tilga olinmagan yangi sharoit yoki vaqt haqida gapiradi (1-namunadagi D, 2-namunadagi C).","**Shartni takrorlash:** variant matnda allaqachon aytilgan faktni qayta aytadi — bu xulosa emas va bo‘sh joyning mantiqiy vazifasini bajarmaydi.","**Sabab va oqibatni almashtirish:** “A B ga olib keladi” degan matndan “B A ga olib keladi” degan xulosa chiqarish."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Reading and Writing’da bir savolga o‘rtacha **71 soniya** bor (har modulda 27 savol, 32 daqiqa). Inference savollari mantiqiy tahlil talab qiladi, shuning uchun ularga **80–100 soniya** ketishi mumkin.","Modulda o‘xshash savollar birga guruhlangan va osondan qiyinga qarab joylashtirilgan. Qiyinroq inference savollariga vaqt qolishi uchun oddiyroq savollarni tezroq yeching.","Matnni bir marta sekin va diqqat bilan o‘qish uch marta shoshib o‘qishdan samaraliroq: bu turdagi savolda e’tibordan chetda qolgan bitta so‘z (*only*, *not*) butun javobni o‘zgartiradi.","Ikki daqiqadan oshib ketsa — bir-ikki variantni chiqarib tashlang, qolganlardan birini tanlang, **Mark for Review** bilan belgilang va keyingi savolga o‘ting. Vaqt qolsa, yangi ko‘z bilan qaytasiz."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"most logically completes","meaning":"eng mantiqiy tarzda to‘ldiradi"},{"term":"infer / inference","meaning":"xulosa chiqarmoq / mantiqiy xulosa"},{"term":"suggest","meaning":"ko‘rsatmoq, ishora qilmoq — ehtiyotkor xulosa"},{"term":"imply","meaning":"bilvosita anglatmoq, nazarda tutmoq"},{"term":"assume / assumption","meaning":"taxmin qilmoq / taxmin (isbotlanmagan asos)"},{"term":"necessarily","meaning":"albatta, muqarrar ravishda"},{"term":"rule out","meaning":"istisno qilmoq — biror imkoniyatni chiqarib tashlamoq"},{"term":"account for","meaning":"izohlamoq, sababini tushuntirmoq"},{"term":"trigger","meaning":"qo‘zg‘atmoq, boshlab bermoq"},{"term":"consistent with","meaning":"…ga mos, …ga zid emas"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Tanlagan variantim matndagi **barcha** shartlardan kelib chiqadimi?","Uni to‘g‘ri deb hisoblash uchun matnda yo‘q taxmin kerak emasmi?","Variantning kuchi (*all, some, may*) matnning ehtiyotkorlik darajasiga mosmi?","Variantni bo‘sh joyga qo‘yib o‘qisam, oxirgi jumla mantiqan to‘liq bo‘ladimi?"]}]'::jsonb
from public.guides g where g.slug = 'inferences'
on conflict (guide_id, locale) do nothing;

