insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Chiziqli funksiyalar', 'Chiziqli funksiyani tenglama, jadval, grafik va matn ko‘rinishida tanib olish, qiyalik va boshlang‘ich qiymatni topish hamda ularning real vaziyatdagi ma’nosini to‘g‘ri talqin qilish.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Chiziqli funksiya — $x$ har safar bir xil miqdorga oshganda $f(x)$ ham har safar bir xil miqdorga o‘zgaradigan bog‘lanish. Uning umumiy ko‘rinishi:\n\n$$f(x) = mx + b$$\n\n- $m$ — **qiyalik (slope)**, ya’ni o‘zgarish tezligi: $x$ 1 ga oshganda $f(x)$ qanchaga o‘zgaradi. Ikki nuqta bo‘yicha: $m = \\frac{y_2 - y_1}{x_2 - x_1}$.\n- $b$ — **boshlang‘ich qiymat**: $f(0) = b$, grafikda esa chiziq $y$ o‘qini kesib o‘tadigan nuqta $(0, b)$.\n- $m > 0$ bo‘lsa funksiya o‘sadi, $m < 0$ bo‘lsa kamayadi, $m = 0$ bo‘lsa o‘zgarmaydi.\n\nSAT bitta funksiyani to‘rt xil ko‘rinishda berishi mumkin: **tenglama**, **jadval**, **grafik** yoki **matnli vaziyat**. Savollar esa uch turga bo‘linadi:\n\n- **Hisoblash:** $f(5)$ ni topish yoki $f(x) = 20$ bo‘ladigan $x$ ni topish.\n- **Tuzish:** jadval, grafik yoki matndan funksiya formulasini yozish.\n- **Talqin qilish:** $m$ va $b$ vaziyatda nimani anglatishini tushunish (masalan, “har minutda 7 litr kamayadi”, “boshida bakda 240 litr bor edi”).\n\nYodda tuting: qiyalikning birligi har doim “$y$ birligi / $x$ birligi” bo‘ladi — litr/minut, dollar/oy, km/soat. Talqin savollarida aynan shu birlik to‘g‘ri variantni ko‘rsatib beradi."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["Savolda funksiya belgisi bor: *“The function f is defined by …”*, *“What is the value of f(6)?”*","Jadval berilgan: *“For the linear function f, the table shows selected values of x and f(x).”* — qiyalik va formulani jadvaldan topish kerak.","Matnda bir tekis o‘zgarish tasvirlangan: *“increases by 3 degrees each hour”*, *“decreases at a constant rate”* — bu chiziqli model belgisi.","*“What is the best interpretation of 240 in this context?”* yoki *“… of the slope of the graph”* — talqin savoli: son vaziyatda nimani anglatishini so‘rayapti.","Grafik berilgan va *“the y-intercept of the graph”* yoki *“the graph of y = f(x) passes through …”* kabi iboralar bor."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Ma’lumot qaysi ko‘rinishda berilganini aniqlang:** tenglama, jadval, grafik yoki matn. Formula allaqachon berilgan bo‘lsa, ko‘pincha qiymat qo‘yib hisoblashning o‘zi yetarli.","**Qiyalikni toping.** Ikkita nuqta oling va $m = \\frac{y_2 - y_1}{x_2 - x_1}$ ni hisoblang. Jadvalda $x$ qadami 1 bo‘lmasa, $y$ ning o‘zgarishini $x$ ning o‘zgarishiga albatta bo‘ling.","**Boshlang‘ich qiymatni toping.** Jadvalda $x = 0$ bo‘lsa, $b$ tayyor. Bo‘lmasa, istalgan nuqtani $y = mx + b$ ga qo‘yib hisoblang: $b = y - mx$.","**Funksiyani yozing:** $f(x) = mx + b$. Matnli masalada har bir harf nimani bildirishini so‘z bilan yozib qo‘ying: “$t$ — minutlar soni, $f(t)$ — qolgan suv (litr)”.","**Savolga aniq javob bering.** $f(4)$ so‘ralsa — $x$ o‘rniga 4 ni qo‘ying; “$f(x) = 4$ bo‘ladigan $x$” so‘ralsa — tenglama tuzib $x$ ni toping. Talqin savolida birlikni (litr, dollar, minut) variantlar bilan solishtiring.","**Uchinchi nuqta bilan tekshiring:** jadval yoki grafikdagi yana bir nuqta formulangizga mos kelishi kerak."]},{"type":"example","heading":"Namuna 1: jadvaldan formula tuzish","example":{"problem":"The table shows selected values of the linear function $f$, where $f(t)$ is the number of liters of water remaining in a tank $t$ minutes after a drain was opened.\n\n$$\\begin{array}{c|ccc} t & 4 & 10 & 16 \\\\ \\hline f(t) & 212 & 170 & 128 \\end{array}$$\n\nWhich equation defines $f$?","choices":["$f(t) = 212 - 7t$","$f(t) = 240 - 7t$","$f(t) = 240 - 42t$","$f(t) = 240 + 7t$"],"solution":["Qiyalikni ikki nuqta bo‘yicha topamiz: $m = \\frac{170 - 212}{10 - 4} = \\frac{-42}{6} = -7$. Demak, har minutda bakdagi suv 7 litrga kamayadi.","Keyingi juftlik bilan tekshiramiz: $\\frac{128 - 170}{16 - 10} = \\frac{-42}{6} = -7$ — o‘zgarish tezligi bir xil, funksiya haqiqatan chiziqli.","Boshlang‘ich qiymat: $b = f(t) - mt = 212 - (-7)(4) = 212 + 28 = 240$. Ya’ni kran ochilgan paytda ($t = 0$) bakda 240 litr suv bo‘lgan.","Funksiya: $f(t) = 240 - 7t$. Tekshiruv: $f(16) = 240 - 112 = 128$ ✓.","Nega boshqa variantlar noto‘g‘ri: **A** jadvaldagi birinchi qiymatni (212) boshlang‘ich qiymat deb oladi, lekin u $t = 4$ ga tegishli, $t = 0$ ga emas. **C** dagi $-42$ — bir minutdagi emas, 6 minutdagi o‘zgarish. **D** da ishora xato: suv kamaymoqda, demak qiyalik manfiy."],"answer":"B) $f(t) = 240 - 7t$"}},{"type":"example","heading":"Namuna 2: funksiya qiymatini topish","example":{"problem":"For the linear function $g$, $g(2) = 11$ and $g(8) = 32$. What is the value of $g(-4)$?","solution":["$g(2) = 11$ yozuvi grafikdagi $(2, 11)$ nuqtani bildiradi; xuddi shunday $g(8) = 32$ — bu $(8, 32)$ nuqta.","Qiyalik: $m = \\frac{32 - 11}{8 - 2} = \\frac{21}{6} = 3.5$.","$b$ ni topamiz: $11 = 3.5 \\cdot 2 + b$, ya’ni $b = 4$. Demak, $g(x) = 3.5x + 4$.","$g(-4) = 3.5 \\cdot (-4) + 4 = -14 + 4 = -10$.","Qisqa yo‘l: $x = 2$ dan $x = -4$ gacha $x$ 6 ga kamayadi, shuning uchun $g$ ning qiymati $6 \\cdot 3.5 = 21$ ga kamayadi: $11 - 21 = -10$.","Tekshiruv: $g(8) = 3.5 \\cdot 8 + 4 = 32$ ✓. Javobni **-10** deb kiriting — manfiy javobda minus belgisi bilan birga 6 tagacha belgi kiritish mumkin."],"answer":"-10"}},{"type":"example","heading":"Namuna 3: qiyalikni talqin qilish","example":{"problem":"A taxi company uses the function $F(m) = 2.15m + 4.50$ to calculate the fare, in dollars, for a trip of $m$ miles. What is the best interpretation of $2.15$ in this context?","choices":["The fare increases by \\$2.15 for each additional mile of the trip.","The fare for a 1-mile trip is \\$2.15.","The fare charged before any distance is traveled is \\$2.15.","The fare increases by \\$2.15 for every 4.50 miles of the trip."],"solution":["$2.15$ — $m$ oldidagi koeffitsiyent, ya’ni qiyalik. Uning birligi: dollar / mil.","Demak, har bir qo‘shimcha mil uchun yo‘l haqi 2.15 dollarga oshadi — bu **A**.","**B** noto‘g‘ri: 1 millik safar narxi $F(1) = 2.15 + 4.50 = 6.65$ dollar. **C** boshlang‘ich to‘lovni tasvirlaydi — u $F(0) = 4.50$ dollar. **D** ikki sonni sun’iy bog‘laydi: 4.50 — millar emas, dollar.","Tekshiruv: $F(11) - F(10) = 28.15 - 26.00 = 2.15$ — har bir qo‘shimcha milda farq aynan 2.15 ✓."],"answer":"A"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Kirish va chiqishni adashtirmang:** $f(3)$ — $x = 3$ bo‘lgandagi qiymat; $f(x) = 3$ esa “qaysi $x$ da natija 3 ga teng?” degan savol.","**Ayirish tartibi:** $\\frac{y_2 - y_1}{x_2 - x_1}$ da surat va maxrajda nuqtalar bir xil tartibda olinishi shart, aks holda ishora teskari chiqadi.","**Jadval qadami:** $x$ qiymatlari 4, 10, 16 kabi 6 tadan oshsa, $y$ dagi o‘zgarishni 6 ga bo‘lishni unutmang.","**Grafik shkalasi:** katakchalar har doim 1 birlik emas — o‘qlardagi sonlarni o‘qing (bir katak 2, 5 yoki 10 birlik bo‘lishi mumkin).","**Boshlang‘ich qiymat** — bu $x = 0$ dagi qiymat, jadvaldagi birinchi son emas.","**Talqin savollarida so‘zlarga qarang:** qiyalik “har bir … uchun” (for each, per) ma’nosini beradi, $b$ esa “boshida”, “hali hech narsa bo‘lmaganda” ma’nosini."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Jadvaldagi birinchi qiymatni boshlang‘ich qiymat deb olish:** $x$ 0 dan boshlanmasa, bu son $b$ emas (Namuna 1 dagi A).","**Bir qatordagi o‘zgarishni qiyalik deb olish:** $-7$ o‘rniga $-42$ (Namuna 1 dagi C).","**Teskari kasr:** $\\frac{\\Delta x}{\\Delta y}$ ni hisoblash — variantlarda $\\frac{1}{m}$ ham ko‘pincha turadi.","**Qiyalik va boshlang‘ich qiymat ma’nolari almashtirilgan:** talqin savolida bir xil son ikki xil ma’noda yozilgan variantlar bo‘ladi. “For each” — qiyalik, “initial” yoki “before any …” — boshlang‘ich qiymat.","**Kirish o‘rniga chiqish:** $f(x) = 20$ bo‘ladigan $x$ so‘ralganda 20 ning o‘zini yoki $f(20)$ ni javob qilish."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Oddiy hisoblash yoki talqin savoliga **30–60 soniya**, jadval yoki grafikdan formula tuzishga **60–80 soniya** yetarli. Math bo‘limida bir savolga o‘rtacha taxminan 95 soniya to‘g‘ri keladi — bu yerda tejagan vaqtingizni qiyin savollarga qoldiring.","**Desmos — jadval savollarida:** jadval qo‘shing (+ tugmasi → table), qiymatlarni $x_1$ va $y_1$ ustunlariga kiriting, keyin alohida qatorga $y_1 \\sim mx_1 + b$ deb yozing (klaviaturadagi ~ belgisi). Desmos $m$ va $b$ ni darhol ko‘rsatadi.","**Desmos — funksiya qiymati:** $g(x) = 3.5x + 4$ ni kiriting, keyingi qatorga $g(-4)$ deb yozing — natija shu zahoti chiqadi.","Talqin savollarida Desmos kerak emas: sonning tenglamadagi o‘rnini (koeffitsiyentmi yoki ozod hadmi) aniqlash 15–20 soniya oladi."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"slope","meaning":"qiyalik (burchak koeffitsiyenti): $x$ 1 ga oshganda $y$ qanchaga o‘zgaradi"},{"term":"rate of change","meaning":"o‘zgarish tezligi — chiziqli funksiyada bu qiyalikning o‘zi"},{"term":"y-intercept","meaning":"grafikning $y$ o‘qini kesgan nuqtasi, $(0, b)$"},{"term":"initial value / starting value","meaning":"boshlang‘ich qiymat, ya’ni $f(0)$"},{"term":"for each additional","meaning":"har bir qo‘shimcha … uchun — qiyalik belgisi"},{"term":"at a constant rate","meaning":"bir xil (o‘zgarmas) tezlikda — model chiziqli ekanini bildiradi"},{"term":"best interpretation","meaning":"eng to‘g‘ri talqin — son vaziyatda nimani anglatishini so‘raydi"},{"term":"selected values","meaning":"tanlab olingan qiymatlar — jadvalda funksiyaning bir nechta nuqtasi berilgan"},{"term":"is defined by","meaning":"… formula bilan berilgan"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Qiyalikni hisoblaganda $y$ ning o‘zgarishini $x$ ning o‘zgarishiga bo‘ldimmi (aksincha emas)?","Boshlang‘ich qiymat haqiqatan $x = 0$ dagi qiymatmi?","Formulamni jadval yoki grafikdagi yana bir nuqta bilan tekshirdimmi?","Savol $f(a)$ ni so‘rayaptimi yoki $f(x) = a$ bo‘ladigan $x$ ni?"]}]'::jsonb
from public.guides g where g.slug = 'linear-functions'
on conflict (guide_id, locale) do nothing;

-- linear-inequalities
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'linear-inequalities', 'skill', (select id from public.skills where code = 'linear_inequalities'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'linear_inequalities'), 5, 10, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Chiziqli tengsizliklar', 'Matndagi “at least”, “no more than” kabi iboralarni tengsizlikka aylantirish, tengsizlikni to‘g‘ri yechish, javobni vaziyatga qarab yaxlitlash va tengsizliklar sistemasining yechimini topish.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Chiziqli tengsizlik xuddi tenglama kabi yechiladi, faqat bitta muhim farq bor: **ikkala tomonni manfiy songa ko‘paytirsangiz yoki bo‘lsangiz, tengsizlik belgisi teskarisiga o‘zgaradi.**\n\n$$-3x > 12 \\quad \\Rightarrow \\quad x < -4$$\n\nMatndagi iboralar va ularning belgilari:\n\n- *at least*, *no less than*, *a minimum of* → $\\ge$\n- *at most*, *no more than*, *a maximum of*, *cannot exceed* → $\\le$\n- *more than*, *greater than*, *exceeds* → $>$\n- *less than*, *fewer than* → $<$\n\nSAT bu mavzuda uch narsani tekshiradi:\n\n- **Tuzish:** vaziyatdan tengsizlik yozish (masalan, “xarajat 200 dollardan oshmasligi kerak”).\n- **Yechish va talqin qilish:** mumkin bo‘lgan eng katta yoki eng kichik qiymatni topish. Narsalar soni butun son bo‘lgani uchun javobni vaziyatga qarab to‘g‘ri yo‘nalishda yaxlitlash kerak.\n- **Grafik va sistemalar:** $xy$-tekislikda $y > mx + b$ — chiziqdan **yuqoridagi** soha, $y < mx + b$ — **pastdagi** soha. Qat’iy belgi ($<$ yoki $>$) bo‘lsa chegara chiziq **punktir**, $\\le$ yoki $\\ge$ bo‘lsa **uzluksiz** chiziq bo‘ladi. Tengsizliklar sistemasining yechimi — sohalarning **umumiy** qismi."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["Matnda chegara bildiruvchi iboralar bor: *“at least”*, *“at most”*, *“no more than”*, *“cannot exceed”*.","*“What is the maximum number of …”* yoki *“What is the minimum number of …”* — tengsizlikni yechib, javobni butun songa to‘g‘ri yaxlitlash kerak.","*“Which inequality represents this situation?”* — tengsizlikni tuzish so‘ralmoqda.","*“Which point (x, y) is a solution to the system of inequalities?”* — nuqtalarni tekshirish savoli.","Grafikda chiziq va bo‘yalgan soha: *“The shaded region shown represents the solutions …”*.","*“What is the greatest possible integer value of x?”* — yechimlar orasidagi eng katta (yoki eng kichik) butun son."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Iboralarni belgiga aylantiring** (yuqoridagi ro‘yxat bo‘yicha). Kim kimdan ko‘p yoki kam ekanini aniq yozing: “kattalar soni bolalar sonidan kamida 2 baravar ko‘p” → $a \\ge 2c$.","**Tengsizlikni tuzing:** odatda ko‘rinishi — o‘zgarmas qism + (birlik narxi yoki og‘irligi) × soni, chegaradan katta-kichikligi bilan.","**Tenglama kabi yeching.** Manfiy songa ko‘paytirish yoki bo‘lish kerak bo‘lsa — belgini o‘sha zahoti aylantiring.","**Vaziyatga qarab yaxlitlang:** “eng ko‘pi bilan nechta” (maximum) savolida pastga, “kamida nechta” (minimum) savolida yuqoriga. Masalan, $n \\le 57.2$ → 57; $n \\ge 12.1$ → 13.","**Chegarani tekshiring:** topilgan sonni qo‘ying — shart bajariladimi? Bir birlik ortig‘ini (yoki kamini) qo‘ysangiz, shart buzilishi kerak.","**Nuqta yoki grafik savolida** har bir variantni **barcha** tengsizliklarga qo‘ying; grafikda esa avval tengsizlikni $y$ ga nisbatan yeching, keyin yuqori yoki pastki sohani aniqlang."]},{"type":"example","heading":"Namuna 1: eng ko‘p miqdor","example":{"problem":"A freight elevator can safely carry a maximum load of 1,500 kilograms. A worker who weighs 82 kilograms rides in the elevator with a cart that weighs 46 kilograms. The worker will load identical boxes that each weigh 24 kilograms onto the cart. What is the maximum number of boxes the worker can load so that the total load does not exceed 1,500 kilograms?","choices":["57","58","59","62"],"solution":["$b$ — qutilar soni. Umumiy yuk: ishchi + arava + qutilar, ya’ni $82 + 46 + 24b = 128 + 24b$.","*“does not exceed”* — $\\le$: $128 + 24b \\le 1500$.","128 ni ayiramiz: $24b \\le 1372$; 24 ga bo‘lamiz: $b \\le \\frac{1372}{24} \\approx 57.17$.","Qutilar soni butun son va chegaradan oshmasligi kerak, shuning uchun **pastga** yaxlitlaymiz: 57.","Tekshiruv: $128 + 24 \\cdot 57 = 128 + 1368 = 1496 \\le 1500$ ✓; $128 + 24 \\cdot 58 = 1520 > 1500$ — 58 ta quti sig‘maydi.","Tuzoqlar: **B (58)** — yuqoriga yaxlitlangan. **C (59)** — aravaning og‘irligi unutilgan: $\\frac{1500 - 82}{24} \\approx 59.1$. **D (62)** — ishchi ham, arava ham unutilgan: $\\frac{1500}{24} = 62.5$."],"answer":"A) 57"}},{"type":"example","heading":"Namuna 2: tengsizliklar sistemasi","example":{"problem":"$$\\begin{aligned} y &< 2x - 3 \\\\ y &\\ge -x + 4 \\end{aligned}$$\n\nWhich point $(x, y)$ is a solution to the given system of inequalities in the $xy$-plane?","choices":["$(1, 3)$","$(3, 2)$","$(4, 5)$","$(2, 0)$"],"solution":["Har bir nuqtani **ikkala** tengsizlikka qo‘yamiz. Bittasi bajarilmasa — nuqta yechim emas.","**A** $(1, 3)$: $3 < 2 \\cdot 1 - 3 = -1$ — noto‘g‘ri. Rad etamiz.","**B** $(3, 2)$: $2 < 2 \\cdot 3 - 3 = 3$ ✓ va $2 \\ge -3 + 4 = 1$ ✓. Ikkala shart bajarildi.","**C** $(4, 5)$: $5 < 2 \\cdot 4 - 3 = 5$ — noto‘g‘ri, chunki 5 o‘zidan kichik emas. Bu nuqta punktir chegara chiziqda yotadi va qat’iy tengsizlik uni o‘z ichiga olmaydi. Eng xavfli tuzoq aynan shu.","**D** $(2, 0)$: birinchi shart bajariladi ($0 < 1$), lekin $0 \\ge -2 + 4 = 2$ — noto‘g‘ri.","Desmos’da tekshiruv: ikkala tengsizlikni kiriting va $(3, 2)$ nuqtani yozing — u ikkala soha ustma-ust tushgan (to‘qroq bo‘yalgan) qismda yotadi."],"answer":"B) $(3, 2)$"}},{"type":"example","heading":"Namuna 3: eng katta butun qiymat","example":{"problem":"What is the greatest integer value of $x$ that satisfies the inequality $-3(x - 4) > 2x - 18$?","solution":["Qavsni ochamiz: $-3x + 12 > 2x - 18$.","$x$ li hadlarni chapga, sonlarni o‘ngga o‘tkazamiz: $-5x > -30$.","$-5$ ga bo‘lamiz va belgini **aylantiramiz**: $x < 6$.","$x$ 6 dan qat’iy kichik, demak eng katta butun qiymat — **5**. 6 ni kiritish qat’iy belgini e’tiborsiz qoldirish bo‘ladi.","Tekshiruv: $x = 5$ da $-3 \\cdot 1 = -3 > 10 - 18 = -8$ ✓. $x = 6$ da $-6 > -6$ — noto‘g‘ri, demak 6 yechim emas ✓.","Belgini aylantirishni unutgan o‘quvchi $x > 6$ ni oladi va “eng katta butun son” topilmaydi — bu ham xato qilinganini bildiradi."],"answer":"5"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Manfiy songa ko‘paytirish yoki bo‘lish — belgi aylanadi.** Bu qoidani har safar ongli ravishda tekshiring, ayniqsa $-\\frac{x}{3}$ kabi hadlarda.","**Qat’iy va noqat’iy belgi:** *“more than”* — $>$, *“at least”* — $\\ge$. Chegaraviy qiymat yechimga kiradimi yoki yo‘qmi — shunga bog‘liq.","**Yaxlitlash yo‘nalishi:** maximum → pastga, minimum → yuqoriga. Odatdagi yaxlitlash qoidasi (0.5 dan boshlab yuqoriga) bu yerda ishlamaydi: natija 12.1 bo‘lsa ham minimum 13.","**Grafikda yuqori va past:** $2x - 3y > 6$ ni $y$ ga nisbatan yechsangiz, $-3$ ga bo‘lasiz va belgi aylanadi: $y < \\frac{2}{3}x - 2$ — soha chiziqdan **pastda**.","**“Kim kimdan” tartibi:** “$a$ kamida $c$ ning ikki baravari” → $a \\ge 2c$, $2a \\ge c$ emas.","**Barcha qismlarni hisobga oling:** o‘zgarmas to‘lov, boshlang‘ich og‘irlik, allaqachon bor miqdor — ularni unutish tuzoq variantlardan biriga olib boradi."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Noto‘g‘ri yaxlitlash:** 57.17 ni 58 ga yaxlitlash (Namuna 1 dagi B).","**Bir qism unutilgan:** aravaning yoki boshlang‘ich to‘lovning og‘irligi yoki narxi hisobga olinmagan javob (Namuna 1 dagi C va D).","**Chegaradagi nuqta:** qat’iy tengsizlikda chiziq ustidagi nuqta yechim emas (Namuna 2 dagi C).","**Teskari belgi:** *“at most”* uchun $\\ge$ yozilgan variant — qolgan qismi to‘liq to‘g‘ri bo‘lgani uchun aldaydi. Belgiga alohida qarang.","**Koeffitsiyent noto‘g‘ri tomonda:** $a \\ge 2c$ o‘rniga $2a \\ge c$.","**Faqat bitta shartni tekshirish:** sistemada nuqtani birinchi tengsizlikka qo‘yib to‘xtab qolish (Namuna 2 dagi D birinchi shartni qanoatlantiradi)."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Tengsizlik tuzish yoki yechish savoliga **45–75 soniya** yetarli; eng ko‘p yoki eng kam miqdor savolida yana 10 soniyani chegarani tekshirishga ajrating.","**Desmos tengsizliklarni bo‘yab chizadi:** $y < 2x - 3$ va $y \\ge -x + 4$ ni kiriting — umumiy soha to‘qroq rangda ko‘rinadi, qat’iy belgili chegara esa punktir chiziq bo‘ladi. Keyin variantdagi nuqtani, masalan $(3, 2)$ ni, alohida qatorga yozing.","**Bir o‘zgaruvchili tengsizlik:** $-3(x - 4) > 2x - 18$ ni Desmos’ga kiritsangiz, yechimlar sohasi bo‘yaladi va uning chegarasi $x = 6$ da punktir chiziq bo‘lib ko‘rinadi.","Nuqta savollarida Desmos’siz ham tez ishlash mumkin: har bir variantni qo‘yish 10–15 soniya oladi; birinchi bajarilmagan shartdan keyin darhol keyingi variantga o‘ting."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"at least","meaning":"kamida: $\\ge$"},{"term":"at most / no more than","meaning":"ko‘pi bilan, …dan oshmasin: $\\le$"},{"term":"exceed / cannot exceed","meaning":"oshib ketadi: $>$ / oshib ketmasligi kerak: $\\le$"},{"term":"maximum / minimum number","meaning":"eng ko‘p / eng kam son — javobni to‘g‘ri yo‘nalishda yaxlitlang"},{"term":"greatest / least possible integer","meaning":"mumkin bo‘lgan eng katta / eng kichik butun son"},{"term":"satisfies the inequality","meaning":"tengsizlikni qanoatlantiradi: qiymat qo‘yilganda tengsizlik to‘g‘ri bo‘ladi"},{"term":"solution to the system of inequalities","meaning":"tengsizliklar sistemasining yechimi: barcha shartlarni bajaradigan nuqta"},{"term":"shaded region","meaning":"bo‘yalgan soha — yechimlar to‘plami"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Manfiy songa ko‘paytirganda yoki bo‘lganda belgini aylantirdimmi?","Qat’iy ($<$, $>$) yoki noqat’iy ($\\le$, $\\ge$) belgini to‘g‘ri tanladimmi?","Butun son kerak bo‘lsa — to‘g‘ri yo‘nalishda yaxlitladim va chegarani tekshirdimmi?","Nuqtani barcha tengsizliklarga qo‘ydimmi?"]}]'::jsonb
from public.guides g where g.slug = 'linear-inequalities'
on conflict (guide_id, locale) do nothing;

-- lines-angles-triangles
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'lines-angles-triangles', 'skill', (select id from public.skills where code = 'lines_angles_triangles'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'lines_angles_triangles'), 17, 10, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Chiziqlar, burchaklar va uchburchaklar', 'Kesishgan va parallel chiziqlar hosil qiladigan burchaklar, uchburchak burchaklari, teng yonli, o‘xshash va teng uchburchaklar — chizma so‘z bilan tasvirlangan bo‘lsa ham uni to‘g‘ri tasavvur qilib, noma’lum burchak yoki tomonni topish.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Bu ko‘nikma burchaklar orasidagi munosabatlarni va uchburchak xossalarini qo‘llay olishingizni tekshiradi. Bilishingiz shart bo‘lgan qoidalar:\n\n- **To‘g‘ri chiziq:** bir chiziqda yonma-yon turgan burchaklar yig‘indisi $180^\\circ$; bir nuqta atrofidagi burchaklar yig‘indisi $360^\\circ$.\n- **Vertikal burchaklar** (ikki chiziq kesishganda qarama-qarshi turgan burchaklar) teng.\n- **Parallel chiziqlar va kesuvchi:** mos burchaklar (corresponding) va ichki almashinuvchi burchaklar (alternate interior) teng; bir tomonli ichki burchaklar yig‘indisi $180^\\circ$. Amaliy qoida: bunday chizmadagi istalgan ikki burchak yo **teng**, yo yig‘indisi **180°**. Ikkalasi ham o‘tkir (yoki ikkalasi ham o‘tmas) bo‘lsa — teng; biri o‘tkir, biri o‘tmas bo‘lsa — yig‘indisi $180^\\circ$.\n- **Uchburchak:** ichki burchaklar yig‘indisi $180^\\circ$; tashqi burchak unga qo‘shni bo‘lmagan ikki ichki burchak yig‘indisiga teng.\n- **Teng yonli uchburchak (isosceles):** teng tomonlar qarshisidagi burchaklar teng (va aksincha). Teng tomonli (equilateral) uchburchakning har bir burchagi $60^\\circ$.\n- **Tomonlar va burchaklar:** katta tomon qarshisida katta burchak yotadi. **Uchburchak tengsizligi:** har bir tomon qolgan ikki tomon yig‘indisidan kichik va ayirmasidan katta.\n- **O‘xshash uchburchaklar (similar):** mos burchaklari teng, mos tomonlari proporsional. Ikki burchagi mos ravishda teng bo‘lsa (AA), uchburchaklar o‘xshash. O‘xshashlik koeffitsiyenti $k$ bo‘lsa, yuzalar nisbati $k^2$.\n- **Teng uchburchaklar (congruent):** barcha mos tomonlari va burchaklari teng (SSS, SAS, ASA, AAS belgilari).\n- **Ko‘pburchak:** $n$ burchakli ko‘pburchak ichki burchaklari yig‘indisi $(n - 2) \\cdot 180^\\circ$.\n\nReference sheet’da uchburchak burchaklari yig‘indisi ($180^\\circ$) va maxsus to‘g‘ri burchakli uchburchaklar berilgan, lekin parallel chiziqlar, vertikal burchaklar va o‘xshashlik qoidalari **yo‘q** — ularni yoddan biling."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["*“In the figure, line ℓ is parallel to line m…”*, *“Lines p and q are intersected by line t”* — parallel chiziqlar va kesuvchi.","Burchaklar ifoda bilan berilgan: *“…has measure (3x + 15)°. What is the value of x?”*","*“Triangle ABC is similar to triangle DEF, where A, B, and C correspond to D, E, and F, respectively”* — o‘xshashlik va proporsiya.","*“Point D lies on side AB and point E lies on side AC such that DE is parallel to BC”* — katta uchburchak ichida kichik o‘xshash uchburchak.","*“isosceles”*, *“equilateral”*, *“AB = BC”*, *“bisects angle…”* — teng tomonlar yoki teng burchaklar haqidagi ishora.","*“Which of the following could be the length of the third side?”* — uchburchak tengsizligi.","*“Note: Figure not drawn to scale.”* — chizmaga ko‘z bilan qarab o‘lchamang, faqat berilgan ma’lumotga tayaning."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Chizmani qoralamaga chizing.** Agar chizma so‘z bilan tasvirlangan bo‘lsa, aynan matndagi tartibda chizing: qaysi nuqta qaysi chiziqda, qaysi burchak qayerda. Berilgan barcha qiymatlarni chizmaga yozing.","**Munosabatlarni belgilang:** parallel chiziqlarni strelka bilan, teng tomonlarni chiziqcha bilan, to‘g‘ri burchakni kvadratcha bilan belgilang. Matnda aytilgan, lekin chizmada ko‘rinmaydigan har bir fakt — muhim kalit.","**Qoidani tanlang:** to‘g‘ri chiziq ($180^\\circ$), vertikal burchaklar (teng), parallel chiziqlar (teng yoki $180^\\circ$), uchburchak ($180^\\circ$), tashqi burchak, teng yonli uchburchak yoki o‘xshashlik.","**Tenglama tuzing va yeching.** Ko‘pincha bitta tenglama yetarli: “bu ikki burchak teng” yoki “bu burchaklar yig‘indisi 180”.","**O‘xshash uchburchaklarda mos uchlarni juftlang.** $\\triangle ABC \\sim \\triangle DEF$ yozuvida tartib muhim: $A \\leftrightarrow D$, $B \\leftrightarrow E$, $C \\leftrightarrow F$, demak $\\frac{AB}{DE} = \\frac{BC}{EF} = \\frac{AC}{DF}$. Ichma-ich uchburchaklarda **butun** tomonni oling, bo‘lagini emas.","**Natijani mantiqan tekshiring:** burchak musbatmi, uchburchak burchaklari yig‘indisi $180^\\circ$ mi, katta tomon katta burchak qarshisidami?","**So‘ralganini bering:** $x$ so‘ralganmi yoki burchak o‘lchovi? Ikkalasi ham variantlarda bo‘lishi mumkin."]},{"type":"example","heading":"Namuna 1: parallel chiziqlar","example":{"problem":"Line $p$ is parallel to line $q$, and line $t$ intersects both lines. At the intersection of lines $t$ and $p$, the angle that lies above line $p$ and to the right of line $t$ has measure $(2x + 40)^\\circ$. At the intersection of lines $t$ and $q$, the angle that lies below line $q$ and to the left of line $t$ has measure $(3x + 10)^\\circ$. What is the value of $x$?","choices":["26","30","80","100"],"solution":["Avval chizamiz: ikki gorizontal parallel chiziq ($p$ va $q$) va ularni kesib o‘tuvchi og‘ma chiziq $t$.","$p$ dagi “yuqori-o‘ng” burchak $q$ dagi “yuqori-o‘ng” burchakka teng (mos burchaklar). $q$ dagi “yuqori-o‘ng” burchak esa $q$ dagi “pastki-chap” burchakka teng (vertikal burchaklar). Demak, berilgan ikki burchak **teng**.","Tenglama: $2x + 40 = 3x + 10$, bundan $x = 30$.","Tekshiruv: $2(30) + 40 = 100$ va $3(30) + 10 = 100$ ✓. Ikkala burchak ham o‘tmas — bu ularning teng bo‘lishi kerakligiga mos.","Xato variantlar: **A** (26) — burchaklarni yig‘indisi $180^\\circ$ deb olishdan chiqadi ($5x + 50 = 180$); lekin unda burchaklar $92^\\circ$ va $88^\\circ$ bo‘lib qoladi, holbuki ular teng bo‘lishi kerak. **D** (100) — bu $x$ emas, burchak o‘lchovi. **C** (80) — qo‘shni burchak ($180 - 100$)."],"answer":"B) 30"}},{"type":"example","heading":"Namuna 2: o‘xshash uchburchaklar (javobni o‘zingiz yozasiz)","example":{"problem":"In triangle $ABC$, point $D$ lies on side $\\overline{AB}$ and point $E$ lies on side $\\overline{AC}$ such that $\\overline{DE}$ is parallel to $\\overline{BC}$. If $AD = 6$, $DB = 4$, and $DE = 9$, what is the length of $\\overline{BC}$?","solution":["$\\overline{DE} \\parallel \\overline{BC}$ bo‘lgani uchun $\\angle ADE = \\angle ABC$ (mos burchaklar), $\\angle A$ esa umumiy. Demak $\\triangle ADE \\sim \\triangle ABC$ (AA belgisi).","Mos tomonlar: $AD \\leftrightarrow AB$, $DE \\leftrightarrow BC$. Diqqat: $AB$ — butun tomon: $AB = AD + DB = 6 + 4 = 10$.","Proporsiya: $\\frac{AD}{AB} = \\frac{DE}{BC}$, ya’ni $\\frac{6}{10} = \\frac{9}{BC}$.","$6 \\cdot BC = 90$, demak $BC = 15$.","Tipik xato: $\\frac{AD}{DB} = \\frac{DE}{BC}$ deb olish ($\\frac{6}{4} = \\frac{9}{BC}$, $BC = 6$) yoki $\\frac{6}{4} = \\frac{BC}{9}$ deb olish ($BC = 13.5$). Ikkalasi ham bo‘lakni butun tomon bilan adashtirishdan kelib chiqadi. Javob katagiga **15** ni yozing."],"answer":"15"}},{"type":"example","heading":"Namuna 3: teng yonli uchburchak va tashqi burchak","example":{"problem":"In triangle $PQR$, $PQ = PR$ and the measure of angle $P$ is $48^\\circ$. Side $\\overline{QR}$ is extended beyond point $R$ to point $S$. What is the measure of angle $PRS$?","choices":["$66^\\circ$","$84^\\circ$","$114^\\circ$","$132^\\circ$"],"solution":["$PQ = PR$ — teng tomonlar. Ularning qarshisidagi burchaklar teng: $PR$ qarshisida $\\angle Q$, $PQ$ qarshisida $\\angle R$. Demak $\\angle Q = \\angle R$.","$\\angle Q + \\angle R = 180^\\circ - 48^\\circ = 132^\\circ$, har biri $66^\\circ$.","$\\angle PRS$ — $R$ uchidagi tashqi burchak: $180^\\circ - 66^\\circ = 114^\\circ$. Tashqi burchak qoidasi bilan tekshiramiz: $\\angle P + \\angle Q = 48^\\circ + 66^\\circ = 114^\\circ$ ✓.","Xato variantlar: **A** (66°) — ichki burchak, tashqi emas. **D** (132°) — ikki asos burchagining yig‘indisi yoki $\\angle R$ ni $48^\\circ$ deb olib, $180^\\circ - 48^\\circ$ hisoblash. **B** (84°) — teng burchaklarni noto‘g‘ri juftlab, $\\angle Q = \\angle P = 48^\\circ$ deb olsangiz, $\\angle R = 84^\\circ$ chiqadi; bu ham ichki burchak va u ham noto‘g‘ri."],"answer":"C) $114^\\circ$"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**“Not drawn to scale” bo‘lsa, chizmaga ishonmang.** To‘g‘ri burchakka o‘xshagan burchak $90^\\circ$ bo‘lmasligi, teng ko‘ringan tomonlar teng bo‘lmasligi mumkin. Faqat matnda yoki belgilarda berilgan narsaga tayaning.","**O‘xshashlikda uchlar tartibi:** $\\triangle ABC \\sim \\triangle DEF$ — birinchi harf birinchisiga, ikkinchisi ikkinchisiga mos. Tomonlarni chizmadagi joylashuvidan emas, shu tartibdan juftlang.","**Teng yonli uchburchakda teng burchaklar teng tomonlar qarshisida yotadi** — ular har doim ham “pastda” emas. Avval qaysi tomonlar teng ekanini toping, keyin ularning qarshisidagi uchlarni.","**Tashqi burchak** unga qo‘shni bo‘lmagan ikki ichki burchak yig‘indisiga teng: burchaklari $40^\\circ$ va $75^\\circ$ bo‘lgan uchburchakda uchinchi uchdagi tashqi burchak $115^\\circ$. Bu $180^\\circ$ ni ikki marta ayirishdan tezroq.","**Uchburchak tengsizligi qat’iy:** tomonlari 3, 5 va 8 bo‘lgan uchburchak **mavjud emas**, chunki $3 + 5 = 8$ (yig‘indi kattaroq bo‘lishi shart). Uchinchi tomon $c$ uchun: $|a - b| < c < a + b$.","**Yashirin tenglamalar beradigan so‘zlar:** *bisects* (bissektrisa burchakni teng ikkiga bo‘ladi), *perpendicular* ($90^\\circ$), *midpoint* (o‘rta nuqta kesmani teng ikkiga bo‘ladi).","**O‘xshash figuralar yuzasi:** tomonlar nisbati $k$ bo‘lsa, yuzalar nisbati $k^2$. Tomonlar 2 marta katta bo‘lsa, yuza 4 marta katta."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**“Teng” va “yig‘indisi 180” ni adashtirish:** test tuzuvchilar ikkala holatdan chiqadigan javobni ham variantlarga qo‘yadi (Namuna 1 dagi 26 va 30).","**x o‘rniga burchak o‘lchovi (yoki aksincha):** $x = 30$ bo‘lsa, $100^\\circ$ ham variantda turadi.","**Bo‘lak va butun tomon:** ichma-ich o‘xshash uchburchaklarda $\\frac{AD}{AB}$ o‘rniga $\\frac{AD}{DB}$ ni ishlatish.","**Noto‘g‘ri juftlangan tomonlar:** proporsiyani uchlar tartibiga qarab tuzmaslik — natijada teskari nisbat chiqadi va u ham variantda bor.","**Ichki va tashqi burchakni adashtirish:** tashqi burchak so‘ralganda ichki burchak (yoki aksincha) variantlarda tayyor turadi.","**Uchburchak tengsizligida chegaraviy son:** tomonlar 4 va 9 bo‘lsa, uchinchi tomon 5 yoki 13 bo‘lishi **mumkin emas** — faqat $5 < c < 13$."]},{"type":"time","heading":"Vaqt, Desmos va reference sheet","items":["Bu turdagi savolga odatda **45–75 soniya** yetarli. Ko‘p vaqt chizmani tushunishga ketadi — shuning uchun avval chizib oling, keyin hisoblang.","**Reference sheet:** uchburchak burchaklari yig‘indisi va maxsus to‘g‘ri burchakli uchburchaklar bor, ammo parallel chiziqlar qoidalari yo‘q — ularni yoddan biling.","**Desmos** bu mavzuda asosan tenglamani tekshirish uchun kerak: masalan, $2x + 40 = 3x + 10$ ni kiritsangiz, Desmos $x = 30$ ni ko‘rsatadi. Chizma uchun esa qoralama tezroq.","Burchaklar ko‘p bo‘lsa va qayerdan boshlashni bilmasangiz, ma’lum burchaklarni chizmaga ketma-ket yozib chiqing: har bir topilgan burchak keyingisini ochadi. 90 soniyadan oshsa, **Mark for Review** bilan belgilab, oldinga o‘ting."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"parallel lines","meaning":"parallel chiziqlar — hech qachon kesishmaydi"},{"term":"transversal","meaning":"kesuvchi — ikki (yoki undan ko‘p) chiziqni kesib o‘tuvchi chiziq"},{"term":"vertical angles","meaning":"vertikal burchaklar — kesishgan ikki chiziqning qarama-qarshi burchaklari, ular teng"},{"term":"supplementary angles","meaning":"yig‘indisi $180^\\circ$ bo‘lgan ikki burchak"},{"term":"corresponding angles","meaning":"mos burchaklar — parallel chiziqlarda bir xil joylashgan burchaklar, ular teng"},{"term":"alternate interior angles","meaning":"ichki almashinuvchi burchaklar — kesuvchining turli tomonida, parallel chiziqlar orasida; ular teng"},{"term":"isosceles triangle","meaning":"teng yonli uchburchak — kamida ikki tomoni teng"},{"term":"similar triangles","meaning":"o‘xshash uchburchaklar — burchaklari teng, tomonlari proporsional"},{"term":"congruent","meaning":"teng (kongruent) — shakli ham, o‘lchami ham bir xil"},{"term":"exterior angle","meaning":"tashqi burchak — tomonni davom ettirganda hosil bo‘ladigan burchak"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Chizmani (yoki matndagi tavsifni) qoralamaga to‘g‘ri chizdimmi va barcha berilganlarni yozdimmi?","Burchaklar teng bo‘lishi kerakmi yoki yig‘indisi 180 — buni qoida asosida tekshirdimmi?","O‘xshash uchburchaklarda mos tomonlarni uchlar tartibi bo‘yicha va butun tomon bilan juftladimmi?","So‘ralgan narsani ($x$, burchak yoki tomon) aynan topdimmi?"]}]'::jsonb
from public.guides g where g.slug = 'lines-angles-triangles'
on conflict (guide_id, locale) do nothing;

-- math-section-strategy
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'math-section-strategy', 'strategy', null, (select id from public.subjects where code = 'math'), 7, 10, 'draft'
