insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Math bo‘limi strategiyasi', 'Math savolini to‘g‘ri o‘qish, “nima so‘ralayotganini” aniqlash, variantlarni qo‘yib tekshirish (backsolving), son tanlash usuli, birliklar, javobni tekshirish, qaysi savollarni avval ishlash va ma’lumotnomada yo‘q, lekin yod bilish kerak bo‘lgan formulalar.', '[{"type":"concept","heading":"Math bo‘limi qanday tuzilgan","body":"Math bo‘limida 44 ta savol, 2 ta modul, har birida 22 ta savol va 35 daqiqa — o‘rtacha **≈95 soniya** bir savolga. Har bir modulda savollar **osondan qiyinga** joylashgan.\n\n- **Algebra** — 13–15 ta savol; **Advanced Math** — 13–15 ta; **Problem-Solving and Data Analysis** — 5–7 ta; **Geometry and Trigonometry** — 5–7 ta.\n- Taxminan **75%** savol to‘rt variantli, taxminan **25%** ida javobni o‘zingiz yozasiz (SPR).\n- Savollarning taxminan **30%** i hayotiy vaziyat (kontekst) asosida.\n- Kalkulyator butun bo‘lim davomida ruxsat etilgan; formulalar ma’lumotnomasi ochiq.\n- Ko‘rsatmalarga ko‘ra, boshqacha aytilmagan bo‘lsa, chizmalar **masshtabda** chizilgan va barcha o‘zgaruvchilar haqiqiy sonlar.\n\nDemak, Algebra va Advanced Math — bo‘limning deyarli to‘rtdan uch qismi. Tayyorgarlik vaqtingizning katta qismi shu ikkisiga ketishi kerak."},{"type":"method","heading":"Har bir savol uchun 5 qadam","steps":["**Savolni oxirigacha o‘qing.** Oxirgi gap — haqiqiy savol. Unda nima so‘ralgan: $x$ mi, $2x$ mi, ifoda mi, birlik nima?","**Berilganlarni yozing.** Qoralama qog‘ozga o‘zgaruvchilarni so‘z bilan belgilang (“$t$ — soatlar soni”), muhim sonlarni ko‘chiring.","**Usulni 10 soniyada tanlang:** to‘g‘ridan-to‘g‘ri algebra, Desmos, variantlarni qo‘yib tekshirish yoki son tanlash.","**Yeching** — har bir qadamni yozib boring. Boshda hisoblangan qadam — xatoning eng ko‘p uchraydigan joyi.","**Tekshiring:** so‘ralgan narsani topdimmi? Javob mantiqiymi (manfiy uzunlik, 300% ehtimollik bo‘lmaydi)? Birliklar to‘g‘rimi? Javobni dastlabki shartga qo‘yib ko‘ring."]},{"type":"note","heading":"“Nima so‘ralyapti?” — kalit iboralar","items":["*What is the value of $3x$?* — $x$ ni topib to‘xtamang, $3x$ ni hisoblang. Ko‘pincha $3x$ ni $x$ ni topmasdan ham olish mumkin.","*in terms of $a$* — javob son emas, $a$ qatnashgan ifoda.","*Which expression is equivalent to…* — ifodani soddalashtiring yoki ochib chiqing; tekshirish uchun $x$ ga son qo‘yib ko‘ring.","*must be true* — har doim to‘g‘ri; *could be true* — kamida bitta holatda to‘g‘ri.","*best interpretation of 12 in this context* — 12 vaziyatda nimani anglatadi: boshlang‘ich qiymat, har birlikka o‘zgarish va hokazo.","*How many more…* / *How much greater…* — ayirma so‘ralgan, qiymatning o‘zi emas.","*percent increase* — o‘zgarish ÷ boshlang‘ich qiymat; *percent of* — qismi.","*positive solution*, *integer value*, *$x > 0$* — topilgan yechimlardan shartga mosini tanlang."]},{"type":"method","heading":"Backsolving: variantlarni qo‘yib tekshirish","steps":["**Qachon ishlatiladi:** variantlar oddiy sonlar, savol “qiymati qancha?” deb so‘raydi, tenglama tuzish esa murakkab yoki uzun.","**O‘rtadagi variantdan boshlang.** Son variantlar ko‘pincha o‘sish tartibida beriladi — B yoki C dan boshlasangiz, natija katta yoki kichik chiqqaniga qarab qaysi tomonga borishni bilasiz.","**Variantni masala shartiga qo‘ying** va qadamma-qadam tekshiring.","**Mos kelsa — to‘xtang.** Qolgan variantlarni tekshirishga vaqt sarflamang.","**Ehtiyot bo‘ling:** savol oraliq natijani emas, aynan so‘ralgan kattalikni topishni talab qiladi."]},{"type":"example","heading":"Namuna 1: backsolving","example":{"problem":"The price of a jacket was increased by 15%. Later, the new price was decreased by 20%, and the final price of the jacket was \\$46. What was the original price of the jacket, in dollars?","choices":["48","50","52","57.5"],"solution":["O‘rtadagi B variantdan boshlaymiz: $50 \\cdot 1.15 = 57.5$, keyin $57.5 \\cdot 0.80 = 46$ ✓. To‘xtaymiz.","Algebraik yo‘l: $x \\cdot 1.15 \\cdot 0.80 = 46$, ya’ni $0.92x = 46$, $x = 50$.","**57.5** — tuzoq: bu narx oshgandan keyingi oraliq qiymat, boshlang‘ich narx emas.","Yana bir tipik xato: “+15% va −20% = −5%” deb hisoblash. Foizlar har xil asosdan olingani uchun ularni shunchaki qo‘shib bo‘lmaydi."],"answer":"B) 50"}},{"type":"method","heading":"Son tanlash (picking numbers)","steps":["**Qachon ishlatiladi:** variantlarda o‘zgaruvchilar bor, foiz noma’lum miqdordan olinadi yoki savol “qaysi biri doim to‘g‘ri?” deb so‘raydi.","**Qulay, lekin “maxsus” bo‘lmagan son tanlang:** 2, 3, 5 yoki foizlar uchun 100. 0 va 1 dan qoching — ular ko‘p variantni bir vaqtda to‘g‘ri qilib qo‘yadi.","**Savolni shu son bilan hisoblang** — maqsad qiymatni toping.","**Har bir variantga shu sonni qo‘ying.** Maqsad qiymatni bermaganlarini chiqarib tashlang.","**Ikki variant mos kelsa** — boshqa son bilan faqat shu ikkitasini qayta tekshiring."]},{"type":"example","heading":"Namuna 2: son tanlash","example":{"problem":"If $p$ is 25% greater than $q$, where $q > 0$, which of the following is equal to $q$?","choices":["$0.75p$","$0.8p$","$1.25p$","$p - 0.25$"],"solution":["Son tanlaymiz: $q = 100$. Unda $p$ undan 25% katta: $p = 125$.","Maqsad: $p = 125$ bo‘lganda 100 ni beradigan ifoda.","A: $0.75 \\cdot 125 = 93.75$ ✗. B: $0.8 \\cdot 125 = 100$ ✓. C: $1.25 \\cdot 125 = 156.25$ ✗. D: $125 - 0.25 = 124.75$ ✗.","**0.75p** — eng ko‘p tanlanadigan tuzoq: “25% katta” teskarisi “25% kichik” emas, chunki foizlar har xil asosdan olinadi. To‘g‘risi: $q = \\frac{p}{1.25} = 0.8p$."],"answer":"B) $0.8p$"}},{"type":"watch_out","heading":"Birliklar va o‘lchovlar","items":["**Bir xil birlikka keltiring:** daqiqa va soat, santimetr va metr, sent va dollar aralashgan bo‘lsa, hisobdan oldin birini tanlang.","**Birlik konversiyasi — kasrlar zanjiri:** 72 km/soat ni m/s ga: $72 \\cdot \\frac{1000}{3600} = 20$. Kerakmas birliklar qisqarib ketishi kerak.","**Yuza va hajm:** $1\\ \\text{m} = 100\\ \\text{cm}$, lekin $1\\ \\text{m}^2 = 10\\,000\\ \\text{cm}^2$ va $1\\ \\text{m}^3 = 1\\,000\\,000\\ \\text{cm}^3$. Konversiya koeffitsiyentini kvadrat yoki kubga oshiring.","**Grafik va jadvallar:** o‘q nomi va birligini o‘qing — *in thousands*, *in millions* kabi izohlar javobni 1000 marta o‘zgartiradi.","**Foiz va o‘nli kasr:** $7\\% = 0.07$, $0.5\\% = 0.005$."]},{"type":"time","heading":"Qaysi savollarni avval ishlash kerak","items":["Modulda savollar osondan qiyinga borgani uchun **tartib bilan** boring, lekin 1-o‘tishda 2–3 daqiqadan uzoq cho‘ziladigan savolni taxminiy javob bilan belgilab, keyinga qoldiring.","**Tez savollar** — har biri 30–60 soniya: chiziqli tenglama, foiz, funksiya qiymati, oddiy birlik konversiyasi, ma’lumotnomadagi formula bilan geometriya.","**Uzoq savollar** — keyinga: uzun matnli masalalar, ko‘p qadamli geometriya, $k$ yoki $c$ o‘zgarmasli parametrik savollar, murakkab ifodalar.","Modulning oxirgi 4–5 savoli odatda eng qiyini. Ularga vaqt qoldiring, lekin ular uchun oson savolni shoshib, xato ishlamang.","Javobni tekshirish — 10–15 soniya: topilgan qiymatni shartga qo‘yish. Bu qiyin savoldagi bitta urinishdan ko‘ra ko‘proq ball saqlaydi."]},{"type":"concept","heading":"Ma’lumotnomada yo‘q, lekin yod bilish kerak bo‘lgan formulalar","items":["**To‘g‘ri chiziq:** qiyalik $m = \\frac{y_2 - y_1}{x_2 - x_1}$; tenglama $y = mx + b$; parallel chiziqlar — qiyaliklar teng; perpendikulyar — $m_1 \\cdot m_2 = -1$.","**Kvadrat tenglama:** $x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}$; diskriminant $D = b^2 - 4ac$ ($D > 0$ — 2 ta, $D = 0$ — 1 ta, $D < 0$ — 0 ta haqiqiy yechim); parabola uchi $x = -\\frac{b}{2a}$; ildizlar yig‘indisi $-\\frac{b}{a}$, ko‘paytmasi $\\frac{c}{a}$.","**Qisqa ko‘paytirish:** $(a + b)^2 = a^2 + 2ab + b^2$, $(a - b)^2 = a^2 - 2ab + b^2$, $a^2 - b^2 = (a - b)(a + b)$.","**Daraja qoidalari:** $a^m \\cdot a^n = a^{m+n}$, $(a^m)^n = a^{mn}$, $a^{-n} = \\frac{1}{a^n}$, $a^{\\frac{m}{n}} = \\sqrt[n]{a^m}$.","**Foiz va o‘sish:** foiz o‘zgarishi $= \\frac{\\text{new} - \\text{old}}{\\text{old}} \\cdot 100\\%$; eksponensial o‘sish $y = a(1 + r)^t$, kamayish $y = a(1 - r)^t$.","**Koordinatalar:** masofa $d = \\sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2}$; o‘rta nuqta $\\left(\\frac{x_1 + x_2}{2}, \\frac{y_1 + y_2}{2}\\right)$.","**Aylana:** tenglama $(x - h)^2 + (y - k)^2 = r^2$, markaz $(h, k)$; yoy uzunligi $\\frac{\\theta}{360^\\circ} \\cdot 2\\pi r$; sektor yuzasi $\\frac{\\theta}{360^\\circ} \\cdot \\pi r^2$; $180^\\circ = \\pi$ radian.","**Trigonometriya:** $\\sin = \\frac{\\text{opposite}}{\\text{hypotenuse}}$, $\\cos = \\frac{\\text{adjacent}}{\\text{hypotenuse}}$, $\\tan = \\frac{\\text{opposite}}{\\text{adjacent}}$; $\\sin x^\\circ = \\cos(90^\\circ - x^\\circ)$.","**O‘xshash shakllar:** tomonlar nisbati $k$ bo‘lsa, yuzalar nisbati $k^2$, hajmlar nisbati $k^3$.","**Statistika va ehtimollik:** o‘rtacha $=$ yig‘indi ÷ soni; mediana — tartiblangan qatorning o‘rtasi; ehtimollik $=$ qulay holatlar ÷ barcha holatlar."]},{"type":"traps","heading":"Keng tarqalgan xatolar","items":["**Oraliq natija variantlar orasida:** yarim yo‘lda to‘xtab qolganingizni tekshiring.","**Kvadrat tenglamaning faqat bitta ildizi:** $x^2 = 16$ ning ikkita yechimi bor — $4$ va $-4$.","**Tengsizlikni manfiy songa bo‘lish:** ishora teskarisiga o‘zgaradi: $-2x > 6 \\Rightarrow x < -3$.","**Foizlarni qo‘shish:** ketma-ket foiz o‘zgarishlari ko‘paytiriladi, qo‘shilmaydi.","**Chizmaga ortiqcha ishonish:** chizma masshtabda bo‘lsa (*not drawn to scale* deyilmagan bo‘lsa), u taxminiy baho uchun yaxshi, lekin aniq hisob o‘rnini bosmaydi.","**Manfiy sonni qavsga ko‘paytirish:** $-3(x - 4) = -3x + 12$."]},{"type":"checklist","heading":"Javobni tanlashdan oldin","items":["Savol aynan nimani so‘raganini qayta o‘qidimmi?","Birliklar bir xilmi?","Javob mantiqiymi (ishora, kattalik)?","Topgan qiymatimni shartga qo‘yib tekshirdimmi?"]}]'::jsonb
from public.guides g where g.slug = 'math-section-strategy'
on conflict (guide_id, locale) do nothing;

-- nonlinear-equations-and-systems
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'nonlinear-equations-and-systems', 'skill', (select id from public.skills where code = 'nonlinear_equations_systems'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'nonlinear_equations_systems'), 7, 11, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Nochiziqli tenglamalar va sistemalar', 'Kvadrat, ildizli, kasrli va modulli tenglamalarni yechish, diskriminant yordamida yechimlar sonini aniqlash, begona ildizlarni tashlab yuborish hamda chiziq va parabola sistemasini yechish.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Bu ko‘nikma bir o‘zgaruvchili nochiziqli tenglamalarni va ikki o‘zgaruvchili nochiziqli sistemalarni qamrab oladi.\n\n**Kvadrat tenglama** $ax^2 + bx + c = 0$ uch usulda yechiladi:\n\n- **Ko‘paytuvchilarga ajratish:** $x^2 - 10x + 9 = (x - 1)(x - 9) = 0$ → $x = 1$ yoki $x = 9$.\n- **Kvadrat ildiz chiqarish** ($x$ li had bo‘lmasa): $(x - 2)^2 = 25$ → $x - 2 = \\pm 5$ → $x = 7$ yoki $x = -3$.\n- **Kvadrat tenglama ildizlari formulasi:** $x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}$.\n\n**Diskriminant** $D = b^2 - 4ac$ yechimlar sonini ko‘rsatadi: $D > 0$ — ikkita haqiqiy yechim, $D = 0$ — bitta, $D < 0$ — haqiqiy yechim yo‘q.\n\n**Viyet teoremasi:** yechimlar yig‘indisi $-\\frac{b}{a}$, ko‘paytmasi $\\frac{c}{a}$. Bu yechimlarni topmasdan javob olish imkonini beradi.\n\nBoshqa turlar:\n\n- **Ildizli tenglama**, masalan $\\sqrt{2x + 7} = x - 4$: ikkala tomon kvadratga ko‘tariladi, lekin bu **begona ildiz** paydo qilishi mumkin. Har bir javobni dastlabki tenglamaga qo‘yib tekshirish shart.\n- **Kasrli tenglama:** maxrajni nolga aylantiradigan qiymat yechim bo‘la olmaydi.\n- **Modulli tenglama:** $|x - 3| = 5$ → $x - 3 = 5$ yoki $x - 3 = -5$.\n\n**Nochiziqli sistema** (masalan, chiziq va parabola) o‘rniga qo‘yish bilan yechiladi: natijada kvadrat tenglama hosil bo‘ladi. Chiziq parabolani 0, 1 yoki 2 nuqtada kesishi mumkin — buni ham diskriminant aniqlaydi."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["Tenglamada $x^2$, ildiz, modul yoki maxrajda $x$ bor: *“What is the positive solution to the given equation?”*","*“How many distinct real solutions does the given equation have?”* — diskriminant savoli.","*“… has exactly one real solution”*, *“… has no real solutions”* — konstantani diskriminant orqali topish.","*“What is the sum of the solutions to the given equation?”* yoki *“… the product of the solutions”* — Viyet teoremasi.","Ikki tenglama, biri nochiziqli: *“The given system of equations has two solutions …”*, *“The graphs of the equations intersect at exactly one point …”*.","*“What is the solution set of the equation?”* va ildizli tenglama — begona ildiz tuzog‘iga tayyor turing."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Nolga tenglang:** barcha hadlarni bir tomonga o‘tkazib, $ax^2 + bx + c = 0$ ko‘rinishiga keltiring. Tenglamani $x$ ga bo‘lmang — $x = 0$ yechimini yo‘qotasiz.","**Usulni tanlang:** butun sonli ko‘paytuvchilar tez topilsa — ajrating (10–15 soniya); topilmasa — formula yoki Desmos.","**Yig‘indi yoki ko‘paytma so‘ralsa** — tenglamani yechmang, $-\\frac{b}{a}$ yoki $\\frac{c}{a}$ dan foydalaning (avval standart shaklga keltiring).","**Yechimlar soni yoki konstanta so‘ralsa** — diskriminantni yozing va kerakli shartni qo‘ying: $D = 0$, $D > 0$ yoki $D < 0$.","**Ildizli va kasrli tenglamalarda** har bir topilgan qiymatni **dastlabki** tenglamaga qo‘ying: begona ildizlarni va maxrajni nolga aylantiradigan qiymatlarni tashlab yuboring.","**Sistemada** bir o‘zgaruvchini ifodalab, ikkinchi tenglamaga qo‘ying; kvadrat tenglamani yeching, keyin ikkinchi koordinatani toping.","**So‘ralgan narsani yozing:** musbat yechimmi, $x$ lar yig‘indisimi yoki $y$ lar yig‘indisimi — savolni oxirgi marta qayta o‘qing."]},{"type":"example","heading":"Namuna 1: ildizli tenglama va begona ildiz","example":{"problem":"What is the solution set of the equation $\\sqrt{2x + 7} = x - 4$?","choices":["$\\{1\\}$","$\\{9\\}$","$\\{1, 9\\}$","$\\{-1, -9\\}$"],"solution":["Ikkala tomonni kvadratga ko‘taramiz: $2x + 7 = (x - 4)^2 = x^2 - 8x + 16$.","Nolga tenglaymiz: $x^2 - 10x + 9 = 0$, ya’ni $(x - 1)(x - 9) = 0$. Nomzodlar: $x = 1$ va $x = 9$.","Dastlabki tenglamaga qo‘yamiz. $x = 9$: $\\sqrt{25} = 5$ va $9 - 4 = 5$ ✓.","$x = 1$: $\\sqrt{9} = 3$, lekin $1 - 4 = -3$, $3 \\ne -3$. Bu **begona ildiz** — u kvadratga ko‘targanda paydo bo‘ldi. Kvadrat ildiz hech qachon manfiy son bermaydi.","**C** — begona ildizni tekshirmasdan qoldirish (eng keng tarqalgan tuzoq). **A** — aynan begona ildizning o‘zi. **D** — ko‘paytuvchilardan ildizlarni olishda ishora xatosi."],"answer":"B) $\\{9\\}$"}},{"type":"example","heading":"Namuna 2: aynan bitta yechim","example":{"problem":"In the equation $3x^2 - 12x + c = 0$, $c$ is a constant. If the equation has exactly one real solution, what is the value of $c$?","solution":["Aynan bitta haqiqiy yechim — diskriminant nolga teng: $D = b^2 - 4ac = 0$.","Bu yerda $a = 3$, $b = -12$, ozod had esa $c$: $D = (-12)^2 - 4 \\cdot 3 \\cdot c = 144 - 12c$.","$144 - 12c = 0$, demak $c = 12$.","Tekshiruv: $3x^2 - 12x + 12 = 3(x^2 - 4x + 4) = 3(x - 2)^2$ — yagona yechim $x = 2$ ✓.","Tuzoqlar: $(-12)^2$ ni $-144$ deb hisoblash (manfiy sonning kvadrati musbat!) yoki $4ac$ dagi $a = 3$ ni unutib, $c = 36$ ni olish."],"answer":"12"}},{"type":"example","heading":"Namuna 3: chiziq va parabola sistemasi","example":{"problem":"$$\\begin{aligned} y &= x^2 - 4x + 1 \\\\ y &= 2x - 4 \\end{aligned}$$\n\nThe given system of equations has two solutions, $(x_1, y_1)$ and $(x_2, y_2)$. What is the value of $y_1 + y_2$?","solution":["Ikkala ifoda $y$ ga teng, demak ularni tenglaymiz: $x^2 - 4x + 1 = 2x - 4$.","Nolga keltiramiz: $x^2 - 6x + 5 = 0$, ya’ni $(x - 1)(x - 5) = 0$; $x_1 = 1$, $x_2 = 5$.","$y$ larni **chiziqli** tenglamadan topamiz (osonroq): $y_1 = 2 \\cdot 1 - 4 = -2$, $y_2 = 2 \\cdot 5 - 4 = 6$.","$y_1 + y_2 = -2 + 6 = 4$.","Tekshiruv paraboladan: $1 - 4 + 1 = -2$ ✓ va $25 - 20 + 1 = 6$ ✓. Tuzoq: $x$ lar yig‘indisini (6) javob qilish — savol $y$ larni so‘rayapti.","Qisqa yo‘l: Viyet bo‘yicha $x_1 + x_2 = 6$, keyin $y_1 + y_2 = 2(x_1 + x_2) - 8 = 12 - 8 = 4$."],"answer":"4"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Begona ildizlar:** kvadratga ko‘tarish tenglamaga yangi “yechim” qo‘shib qo‘yishi mumkin. Ildizli tenglamada tekshiruv — majburiy qadam.","**Ikkala ildiz:** $x^2 = 49$ dan $x = 7$ yoki $x = -7$. Savolda *“positive solution”* deyilgan bo‘lsagina manfiysini tashlang.","**O‘zgaruvchiga bo‘lmang:** $x^2 = 5x$ ni $x$ ga bo‘lsangiz, $x = 0$ yechimi yo‘qoladi. To‘g‘ri yo‘l: $x^2 - 5x = 0$, $x(x - 5) = 0$.","**Diskriminantda ishoralar:** $b$ manfiy bo‘lsa ham $b^2$ musbat; $a$ va $c$ ni esa o‘z ishorasi bilan qo‘ying.","**Viyet teoremasidan oldin** tenglamani $ax^2 + bx + c = 0$ ko‘rinishiga keltiring va $a \\ne 1$ bo‘lsa, $a$ ga bo‘lishni unutmang.","**Har xil (distinct) yechimlar:** $(x - 2)^2 = 0$ da ildiz ikki marta takrorlansa ham, u bitta yechim hisoblanadi.","**Sistemada so‘ralgan koordinata:** $x$ lar, $y$ lar yoki ularning kombinatsiyasi — oxirgi qadamda savolni qayta o‘qing."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Begona ildiz qoldirilgan:** “ikkalasi ham” varianti, masalan $\\{1, 9\\}$ (Namuna 1 dagi C).","**Faqat musbat ildiz:** $x^2 = 49$ da $-7$ ni yo‘qotib, “nechta yechim bor” savoliga 1 deb javob berish.","**Viyetda ishora:** yig‘indini $\\frac{b}{a}$ deb olish. $x^2 - 6x + 5 = 0$ da yig‘indi $6$ ga teng, $-6$ ga emas.","**Noto‘g‘ri koordinata:** $y$ lar yig‘indisi o‘rniga $x$ lar yig‘indisi (Namuna 3 dagi 6).","**Diskriminant sharti almashgan:** *“no real solutions”* uchun $D > 0$ yoki $D = 0$ ni yozish. To‘g‘risi: $D < 0$."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Oson ajraladigan tenglama — **40–60 soniya**; diskriminant yoki sistema savoli — **60–100 soniya**.","**Desmos ildizli tenglamada:** chap va o‘ng tomonni alohida kiriting: $y = \\sqrt{2x + 7}$ va $y = x - 4$. Grafiklar faqat $x = 9$ da kesishadi — begona ildiz grafikda umuman ko‘rinmaydi.","**Desmos sistemada:** ikkala tenglamani kiriting va kesishish nuqtalariga bosing — ikkala koordinata ham chiqadi.","**Konstantali savollarda slayder:** $y = 3x^2 - 12x + c$ ni kiriting, $c$ uchun slayder qo‘shing va parabola $x$ o‘qiga faqat bitta nuqtada tegadigan holatni qidiring. Algebraik yo‘l (diskriminant) baribir tezroq — Desmos’ni tekshirish uchun ishlating.","**Irratsional javob:** Desmos o‘nli kasr ko‘rsatadi (masalan, $2.414$). Variantlarda $1 + \\sqrt{2}$ kabi ifoda bo‘lsa, uni ham kalkulyatorda hisoblab solishtiring."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"solution set","meaning":"yechimlar to‘plami — tenglamaning barcha yechimlari"},{"term":"real solution","meaning":"haqiqiy yechim"},{"term":"distinct","meaning":"har xil, takrorlanmaydigan"},{"term":"exactly one / no real solutions","meaning":"aynan bitta / haqiqiy yechim yo‘q — diskriminant savoli"},{"term":"positive solution","meaning":"musbat yechim"},{"term":"sum / product of the solutions","meaning":"yechimlar yig‘indisi / ko‘paytmasi"},{"term":"intersect at","meaning":"… nuqtada kesishadi — sistemaning yechimi"},{"term":"constant","meaning":"o‘zgarmas son"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Tenglamani nolga tenglab, standart shaklga keltirdimmi?","Ildizli yoki kasrli tenglamada har bir yechimni dastlabki tenglamaga qo‘ydimmi?","Diskriminant shartini ($>$, $=$ yoki $<$) to‘g‘ri tanladimmi?","Javobim aynan so‘ralgan narsami — $x$, $y$, yig‘indi yoki musbat yechim?"]}]'::jsonb
from public.guides g where g.slug = 'nonlinear-equations-and-systems'
on conflict (guide_id, locale) do nothing;

