insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'nonlinear-functions', 'skill', (select id from public.skills where code = 'nonlinear_functions'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'nonlinear_functions'), 6, 11, 'draft'
