insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Nisbatlar, rate, proporsiyalar va o‘lchov birliklari', 'Nisbat va proporsiya tuzish, “birlik uchun miqdor” (rate) bilan ishlash hamda o‘lchov birliklarini xatosiz almashtirish. Asosiy qurol — birliklarni kasr ko‘rinishida yozib, keraksizlarini qisqartirish: shunda noto‘g‘ri ko‘paytirish yoki bo‘lish deyarli imkonsiz bo‘ladi.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Bu ko‘nikma Problem-Solving and Data Analysis domeniga kiradi (butun Math bo‘limida bu domendan 5–7 ta savol bo‘ladi) va kundalik hayotdagi miqdorlar o‘rtasidagi bog‘liqlikni tekshiradi. To‘rtta asosiy g‘oya bor:\n\n- **Nisbat (ratio):** “$a$ ning $b$ ga nisbati” $a : b$ yoki $\\frac{a}{b}$ deb yoziladi. Nisbat $3 : 5$ bo‘lsa, miqdorlarni $3k$ va $5k$ deb olasiz, jami esa $8k$ bo‘ladi — ya’ni birinchi guruh butunning $\\frac{3}{8}$ qismi.\n- **Proporsiya (proportion):** ikki nisbatning tengligi, $\\frac{a}{b} = \\frac{c}{d}$. U o‘zaro ko‘paytirish (cross-multiplication) bilan yechiladi: $ad = bc$. To‘g‘ri proporsional bog‘liqlik $y = kx$ ko‘rinishida bo‘ladi, bunda $k$ — o‘zgarmas koeffitsiyent.\n- **Rate (birlik uchun miqdor):** bir miqdorning boshqa miqdor birligiga to‘g‘ri keladigan qismi — km/soat, so‘m/kg, sahifa/minut. Asosiy formula: miqdor = rate × vaqt, masalan, masofa = tezlik × vaqt.\n- **Birliklarni almashtirish (unit conversion):** har bir munosabatni qiymati 1 ga teng kasr sifatida yozasiz, masalan $\\frac{60 \\text{ min}}{1 \\text{ h}}$, va keraksiz birlik qisqarib ketadigan qilib ko‘paytirasiz.\n\nShu ko‘nikmaga **zichlik** (density = massa ÷ hajm; aholi zichligi = odamlar soni ÷ maydon) va **masshtab** (xaritada 1 cm = 5 km kabi) savollari ham kiradi."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["*“the ratio of … to …”*, *“for every 3 … there are 5 …”* — nisbat savoli. So‘zlar tartibiga e’tibor bering: “ratio of A to B” — bu $A : B$.","*“per”*, *“at this rate”*, *“at a constant rate of …”* — rate savoli: birlik uchun miqdor berilgan, jami miqdor yoki vaqt so‘raladi.","*“is proportional to”*, *“directly proportional”* — $y = kx$ ko‘rinishidagi bog‘liqlik; avval $k$ ni toping.","Masalada qavs ichida munosabat berilgan: *“(1 mile = 5,280 feet)”*, *“1 kilogram is approximately 2.2 pounds”* — birliklarni almashtirish savoli, berilgan munosabat esa yechimning kaliti.","*“square feet”*, *“cubic centimeters”*, *“per square mile”* — kvadrat yoki kub birliklar: almashtirish koeffitsiyentini kvadratga yoki kubga ko‘tarishga to‘g‘ri keladi.","*“On the map, 1 inch represents 20 miles”* — masshtab savoli; aslida bu oddiy proporsiya."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Yakuniy birlikni aniqlang.** Savol oxirida nima so‘ralayotganini o‘qing: soatmi yoki minutmi, metrmi yoki kilometrmi, litrmi yoki kub metrmi. Shu birlikni qoralamada aylana ichiga oling — butun yechim shu tomonga qarab yuradi.","**Nisbatni qismlar orqali yozing.** $a : b$ nisbatda miqdorlar $ak$ va $bk$ bo‘ladi. Jami berilgan bo‘lsa: $(a + b)k$; farq berilgan bo‘lsa: $(b - a)k$. Avval bitta qismning qiymatini ($k$) toping.","**Proporsiyani bir xil tartibda tuzing.** Ikkala kasrning suratida bir xil birlik, maxrajida ham bir xil birlik tursin (masalan, ikkalasida ham km/soat). Keyin o‘zaro ko‘paytiring.","**Birliklarni kasr zanjiri bilan almashtiring.** Berilgan qiymatni yozing va har bir munosabatni keraksiz birlik qisqaradigan tarzda qo‘ying: $$12 \\, \\frac{\\text{L}}{\\text{s}} \\times \\frac{3600 \\text{ s}}{1 \\text{ h}} \\times \\frac{1 \\text{ m}^3}{1000 \\text{ L}}$$ Kvadrat birlikda koeffitsiyentni kvadratga, kub birlikda kubga ko‘taring.","**Faqat oxirida hisoblang va yaxlitlang.** Zanjirni to‘liq yozib, keyin kalkulyatorda bitta ifoda sifatida hisoblang. Oraliq yaxlitlash javobni qo‘shni variantga “siljitib” yuborishi mumkin.","**Mantiqiy tekshiruv qiling.** Kattaroq birlikka o‘tsangiz son kichrayadi (minut → soat), kichikroq birlikka o‘tsangiz kattalashadi. Javob shu qoidaga zid bo‘lsa, kasrni teskari qo‘ygansiz."]},{"type":"example","heading":"Namuna 1: ikki bosqichli almashtirish","example":{"problem":"A water pump moves water at a constant rate of 12 liters per second. At this rate, how many cubic meters of water does the pump move in 1 hour? (1 cubic meter = 1,000 liters)","choices":["0.72","43.2","720","43,200"],"solution":["Yakuniy birlik — **kub metr**. Bizda litr/soniya bor: soniyani soatga, litrni kub metrga o‘tkazishimiz kerak.","1 soatda $60 \\times 60 = 3600$ soniya bor. Kasr zanjiri: $$12 \\, \\frac{\\text{L}}{\\text{s}} \\times \\frac{3600 \\text{ s}}{1 \\text{ h}} \\times \\frac{1 \\text{ m}^3}{1000 \\text{ L}} = \\frac{12 \\times 3600}{1000} \\, \\frac{\\text{m}^3}{\\text{h}}$$ Soniya (s) va litr (L) qisqarib ketadi.","Hisoblaymiz: $12 \\times 3600 = 43{,}200$ litr, $43{,}200 \\div 1000 = 43.2$ kub metr.","Nega boshqa variantlar xato: **43,200** — litr kub metrga o‘tkazilmagan; **720** — bu 1 **minutda** haydaladigan litrlar ($12 \\times 60$); **0.72** — 1 minutdagi hajm kub metrda, soatga o‘tilmagan ($720 \\div 1000$).","Tekshiruv: $43.2 \\text{ m}^3 = 43{,}200 \\text{ L}$ va $43{,}200 \\div 3600 = 12$ litr/soniya ✓."],"answer":"B) 43.2"}},{"type":"example","heading":"Namuna 2: nisbat va farq (javobni o‘zingiz yozasiz)","example":{"problem":"In a school''s robotics club, the ratio of juniors to seniors is 4 to 7. There are 12 more seniors than juniors in the club. If the club has only juniors and seniors, how many members does the club have?","solution":["Nisbatni qismlar bilan yozamiz: juniors $= 4k$, seniors $= 7k$, bunda $k$ — bitta qismning qiymati.","Farq berilgan: $7k - 4k = 12$, ya’ni $3k = 12$ va $k = 4$.","Juniors: $4 \\times 4 = 16$, seniors: $7 \\times 4 = 28$. Jami: $16 + 28 = 44$ (yoki darhol $11k = 44$).","Tuzoqlar: **11** — bu qismlar soni, a’zolar soni emas; **16** yoki **28** — faqat bitta guruh, savol esa butun klubni so‘rayapti.","Tekshiruv: $16 : 28 = 4 : 7$ ✓ va $28 - 16 = 12$ ✓. Javob maydoniga **44** deb yozasiz."],"answer":"44"}},{"type":"example","heading":"Namuna 3: kvadrat birliklar","example":{"problem":"A rectangular rug has an area of 54 square feet. What is the area of the rug, in square yards? (1 yard = 3 feet)","choices":["6","18","162","486"],"solution":["Bu **kvadrat birlik**. 1 yard = 3 fut bo‘lsa, 1 kvadrat yard — tomoni 3 fut bo‘lgan kvadrat: $1 \\text{ yd}^2 = 3 \\times 3 = 9 \\text{ ft}^2$.","Kvadrat futdan kvadrat yardga o‘tish — kattaroq birlikka o‘tish, demak son kichrayadi: $54 \\div 9 = 6$.","Kasr zanjiri bilan: $54 \\text{ ft}^2 \\times \\left(\\frac{1 \\text{ yd}}{3 \\text{ ft}}\\right)^2 = \\frac{54}{9} = 6 \\text{ yd}^2$.","Nega boshqa variantlar xato: **18** — koeffitsiyent kvadratga ko‘tarilmagan ($54 \\div 3$), bu eng ko‘p uchraydigan tuzoq; **162** va **486** — bo‘lish o‘rniga ko‘paytirilgan ($54 \\times 3$ va $54 \\times 9$).","Tekshiruv: gilam, masalan, $9 \\text{ ft} \\times 6 \\text{ ft}$ bo‘lsa, u $3 \\text{ yd} \\times 2 \\text{ yd} = 6 \\text{ yd}^2$ bo‘ladi ✓."],"answer":"A) 6"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Nisbat tartibi:** “the ratio of boys to girls” — bu o‘g‘il bolalar : qizlar. Tartib almashsa, javob teskari kasrga aylanadi — u ham variantlar orasida bo‘ladi.","**Qism va butun:** $3 : 5$ nisbatda birinchi guruh butunning $\\frac{3}{8}$ qismi, $\\frac{3}{5}$ emas. *“What fraction of all …”* savollarida maxraj — barcha qismlar yig‘indisi.","**Kvadrat va kub birliklar:** 1 m = 100 cm bo‘lsa, $1 \\text{ m}^2 = 10{,}000 \\text{ cm}^2$ va $1 \\text{ m}^3 = 1{,}000{,}000 \\text{ cm}^3$.","**O‘rtacha tezlik = umumiy masofa ÷ umumiy vaqt.** Borishda 60 km/soat, qaytishda 40 km/soat bo‘lsa, o‘rtacha tezlik 50 emas, **48** km/soat: yo‘l uzunligi $d$ bo‘lsa, umumiy vaqt $\\frac{d}{60} + \\frac{d}{40} = \\frac{d}{24}$, tezlik esa $2d \\div \\frac{d}{24} = 48$.","**Berilgan munosabatni ishlating:** masalada “1 kilogram ≈ 2.2 pounds” kabi qiymat berilgan bo‘lsa, aynan shuni qo‘llang — boshqa joydan eslab qolgan aniqroq son variantlarga mos kelmasligi mumkin. Vaqt (1 soat = 60 minut = 3600 soniya) va metrik birliklar (1 km = 1000 m, 1 m = 100 cm) orasidagi oddiy munosabatlarni esa yoddan bilishingiz kerak.","**Javob formati (SPR):** javob maydoniga birlik, vergul yoki \\$ belgisini yozmang — faqat sonni kiriting: 1,440 emas, **1440**."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Teskari koeffitsiyent:** bo‘lish o‘rniga ko‘paytirish (yoki aksincha). Natija haddan tashqari katta yoki kichik chiqadi, test tuzuvchilar esa ikkala variantni ham qo‘yadi (namuna 3 dagi 162 va 486).","**Yarim almashtirish:** ikki birlikdan faqat bittasi almashtirilgan (namuna 1 dagi 43,200 va 0.72).","**Kvadratga ko‘tarilmagan koeffitsiyent:** maydonni chiziqli koeffitsiyentga bo‘lish (namuna 3 dagi 18).","**Qismlar soni yoki bitta guruh javob sifatida:** nisbat savolida $k$, $a + b$ yoki faqat bitta guruh soni variantlarda turadi (namuna 2 dagi 11, 16, 28).","**Tezliklarning oddiy o‘rtachasi:** ikki tezlikni qo‘shib 2 ga bo‘lish — har bir tezlikda sarflangan vaqt teng bo‘lmasa, bu noto‘g‘ri."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Oddiy nisbat yoki bitta almashtirish: **30–60 soniya**. Ikki-uch bosqichli almashtirish: **60–90 soniya**. Math’da har bir savolga o‘rtacha 95 soniya to‘g‘ri keladi, shuning uchun bu yerda tejalgan vaqt qiyinroq savollarga qoladi.","Kasr zanjirini qoralamaga yozib, hisobni kalkulyatorda **bitta ifoda** sifatida bajaring: masalan, Desmos’ga $12 \\cdot 3600 / 1000$ ni yozing — natija darhol chiqadi va oraliq yaxlitlash bo‘lmaydi.","Oddiy proporsiyani o‘zaro ko‘paytirish Desmos’dan tezroq. Lekin noma’lum ikki joyda qatnashsa (masalan, $\\frac{x + 4}{x} = \\frac{7}{5}$), tenglamani Desmos’ga yozing — u yechimni $x = 10$ vertikal chizig‘i sifatida ko‘rsatadi.","Variantlar bir-biridan 10, 100 yoki 1000 marta farq qilsa, bu birlik almashtirish tuzog‘i belgisi: hisoblashdan oldin javob taxminan qancha bo‘lishini baholang."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"ratio","meaning":"nisbat: “ratio of A to B” — $A : B$"},{"term":"for every","meaning":"har … ga: “for every 3 cats there are 5 dogs” — nisbat $3 : 5$"},{"term":"rate","meaning":"birlik uchun miqdor (km/soat, litr/minut, so‘m/kg)"},{"term":"per","meaning":"har bir … uchun; kasr chizig‘i: “miles per hour” — $\\frac{\\text{miles}}{\\text{hour}}$"},{"term":"at this rate / at a constant rate","meaning":"shu sur’atda / o‘zgarmas sur’atda: rate butun vaqt davomida bir xil"},{"term":"proportional to","meaning":"proporsional: $y = kx$ — biri necha marta oshsa, ikkinchisi ham shuncha marta oshadi"},{"term":"convert / conversion","meaning":"bir birlikdan boshqasiga o‘tkazish (almashtirish)"},{"term":"density","meaning":"zichlik: massa ÷ hajm yoki odamlar soni ÷ maydon (population density)"},{"term":"square feet / cubic meters","meaning":"kvadrat fut / kub metr — maydon va hajm birliklari"},{"term":"scale","meaning":"masshtab: xarita yoki chizmadagi o‘lchamning haqiqiy o‘lchamga nisbati"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Javob so‘ralgan birlikdami (soat yoki minut, m² yoki m³)?","Nisbat tartibi to‘g‘rimi va qism bilan butun aralashib ketmadimi?","Kvadrat yoki kub birlikda koeffitsiyentni darajaga ko‘tardimmi?","Javobning kattaligi mantiqqa to‘g‘ri keladimi?"]}]'::jsonb
from public.guides g where g.slug = 'ratios-rates-proportions-units'
on conflict (guide_id, locale) do nothing;

-- reading-writing-strategy
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'reading-writing-strategy', 'strategy', null, (select id from public.subjects where code = 'reading_writing'), 8, 10, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Reading and Writing bo‘limi strategiyasi', 'Reading and Writing savollari qanday ko‘rinadi va modulda qanday tartibda keladi, nega avval savolni o‘qish kerak, variantlarga qaramasdan javobni bashorat qilish, noto‘g‘ri variantlarni chiqarib tashlash va ingliz tili ona tilingiz bo‘lmasa, notanish so‘zlar bilan qanday ishlash.', '[{"type":"concept","heading":"Savollar qanday ko‘rinadi","body":"Reading and Writing bo‘limida 54 ta savol bor: 2 ta modul, har birida 27 ta savol va 32 daqiqa — o‘rtacha **≈71 soniya** bir savolga.\n\n- Har bir savol **bitta qisqa matn** (25–150 so‘z) yoki **bir juft matn** bilan beriladi, ba’zan jadval yoki grafik bilan.\n- **Har bir matnga faqat bitta savol** — uzun matn o‘qib, unga 10 ta savol ishlash yo‘q.\n- Barcha savollar to‘rt variantli, har birining **bitta eng to‘g‘ri** javobi bor va u matnga asoslanishi kerak.\n- Matnlar adabiyot, tarix va ijtimoiy fanlar, gumanitar fanlar va tabiiy fanlardan olinadi.\n\nBu format ingliz tili ona tili bo‘lmagan o‘quvchi uchun qulay: har bir savolda yangi, qisqa matn — bitta qiyin matn butun bo‘limni buzmaydi."},{"type":"concept","heading":"Modulda savollar qanday tartibda keladi","body":"Har bir modulda to‘rttala yo‘nalish bor va ular **doim shu tartibda** keladi:\n\n- **1. Craft and Structure** (≈28%) — so‘zning kontekstdagi ma’nosi (*Words in Context*), matn tuzilishi va maqsadi, ikki matn orasidagi bog‘liqlik.\n- **2. Information and Ideas** (≈26%) — asosiy g‘oya va tafsilotlar, matn va jadval/grafikdan dalil, xulosa chiqarish.\n- **3. Standard English Conventions** (≈26%) — gap chegaralari va tinish belgilari, so‘z shakllari (grammatika).\n- **4. Expression of Ideas** (≈20%) — bog‘lovchi so‘zlar (*transitions*) va eslatmalardan maqsadga mos gap tuzish (*rhetorical synthesis*).\n\nO‘xshash ko‘nikmani tekshiradigan savollar birga guruhlangan va **har bir guruh ichida osondan qiyinga** joylashgan. Grammatika savollari esa qaysi qoida tekshirilishidan qat’i nazar osondan qiyinga tartiblangan.\n\n**Strategik xulosa:** qiyinlik faqat modul oxirida emas, har bir guruh oxirida ko‘tariladi. Bir guruhning qiyin oxirgi savolida qotib qolsangiz — belgilab o‘ting: keyingi guruhning birinchi savollari yana osonroq bo‘ladi."},{"type":"method","heading":"Asosiy usul: savol → matn → bashorat → variantlar","steps":["**Avval savolni o‘qing** (matn ostidagi so‘roq gap). U nimani izlashni aytadi: so‘z ma’nosi, gapning vazifasi, asosiy g‘oya, dalil yoki grammatika.","**Matnni maqsadli o‘qing.** Matn qisqa — uni to‘liq o‘qing, lekin savol so‘ragan joyga alohida e’tibor bering. Grammatika savollarida bo‘sh joy turgan gap va uning qo‘shnisi ko‘pincha yetarli.","**Bashorat qiling.** Variantlarga qaramasdan javobni o‘z so‘zlaringiz bilan ayting — o‘zbekcha bo‘lsa ham bo‘ladi: “bu yerda *ataylab* ma’nosidagi so‘z kerak”, “ikkinchi gap birinchisiga zid”.","**Variantlarni bashoratingiz bilan solishtiring.** Unga eng yaqinini tanlang.","**Chiqarib tashlang.** Har bir noto‘g‘ri variantning **aniq sababini** toping va Option Eliminator bilan o‘chiring.","**Dalilni tekshiring.** Tanlagan javobingizni matndagi aniq so‘z yoki gap bilan tasdiqlay olasizmi? Ololmasangiz — qayta qarang."]},{"type":"note","heading":"Noto‘g‘ri variantlarning belgilari","items":["**Matnda yo‘q:** hayotda to‘g‘ri bo‘lishi mumkin, lekin matnda aytilmagan yoki nazarda tutilmagan. Javob faqat matnga asoslanadi.","**Haddan tashqari kuchli:** *always*, *never*, *proves*, *completely*, *all* — matn ehtiyotkor (*suggests*, *may*, *some*) bo‘lsa, bunday variant noto‘g‘ri.","**Yarim to‘g‘ri:** birinchi yarmi matnga mos, ikkinchi yarmi esa yo‘q. Variantni oxirigacha o‘qing.","**Teskari:** matnning aksini aytadi — ayniqsa *however*, *although*, *despite* dan keyingi fikrni noto‘g‘ri o‘qishdan chiqadi.","**So‘zlar mos, ma’no emas:** matndagi so‘zlarni takrorlaydi, lekin savolga javob bermaydi.","**Juda tor yoki juda keng:** asosiy g‘oya savolida bitta tafsilotni yoki matndan ancha keng mavzuni aytadigan variant."]},{"type":"recognize","heading":"Savol turini tanib olish va qisqa yo‘l","items":["*Which choice completes the text with the most logical and precise word or phrase?* — **Words in Context.** Bo‘sh joyga o‘z so‘zingizni qo‘ying, keyin variantlardan eng yaqinini toping. Zidlik (*although*, *but*) va davom (*and*, ikki nuqta) signallariga qarang.","*Which choice best states the main purpose of the text?* / *best describes the function of the underlined sentence* / *best describes the overall structure* — **matn tuzilishi va maqsadi.** Har bir gapning vazifasini aniqlang: da’vo, misol, qarshi fikr, xulosa.","*Based on the texts, how would… most likely respond…?* — **ikki matn.** Avval har bir matnning asosiy fikrini bir gap bilan ayting, keyin ikkinchi muallifning birinchisiga munosabatini: rozi, qisman rozi yoki qarshi.","*Which choice best states the main idea of the text?* — **asosiy g‘oya.** Butun matnni qamraydigan, lekin undan kengaymaydigan variant.","*Which finding, if true, would most directly support…?* / *Which quotation… most effectively illustrates the claim?* — **matndan dalil.** Avval da’voni aniq ajrating; variant aynan shu da’voni tasdiqlashi kerak, shunchaki mavzuga yaqin bo‘lishi emas.","*Which choice most effectively uses data from the graph/table…?* — **raqamli dalil.** Avval matndagi da’voni o‘qing, keyin jadvalni. To‘g‘ri variant ham ma’lumotga, ham da’voga mos bo‘ladi. Jadvalda to‘g‘ri, lekin da’voga aloqasi yo‘q variant — eng ko‘p uchraydigan tuzoq.","*Which choice most logically completes the text?* — **xulosa chiqarish.** Matndagi mantiqiy zanjirni davom ettiring; eng kam qo‘shimcha taxmin talab qiladigan variantni tanlang.","*Which choice completes the text so that it conforms to the conventions of Standard English?* — **grammatika.** “Eshitilishi”ga emas, qoidaga tayaning — “Grammatika qoidalari” qo‘llanmasiga qarang.","*Which choice completes the text with the most logical transition?* — **bog‘lovchi.** Ikki gap orasidagi munosabatni o‘zbekcha ayting: “lekin”, “shuning uchun”, “masalan”, “bundan tashqari” — keyin mos inglizcha so‘zni tanlang.","*Which choice most effectively uses relevant information from the notes to accomplish this goal?* — **eslatmalar.** Avval faqat **maqsadni** o‘qing (*The student wants to…*). Odatda barcha variantlar eslatmalarga to‘g‘ri keladi — farq faqat maqsadga mosligida."]},{"type":"example","heading":"Namuna 1: so‘zning kontekstdagi ma’nosi","example":{"problem":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Although critics initially dismissed the composer’s early works as overly simple, later listeners came to see that simplicity as ______: each spare melody had been carefully constructed to leave room for the performer’s interpretation.","choices":["accidental","deliberate","excessive","temporary"],"solution":["Savolni o‘qidik: bo‘sh joyga so‘z kerak. Matnda ikki signal bor: *Although* (tanqidchilarga zid fikr keladi) va ikki nuqta (keyingi qism bo‘sh joyni tushuntiradi).","Ikki nuqtadan keyin: har bir ohang **ehtiyotkorlik bilan tuzilgan** (*carefully constructed*). Bashorat: “ataylab qilingan”.","*accidental* (tasodifiy) — bashoratga teskari. *excessive* (haddan tashqari) — tanqidchilarning fikri, keyingi tinglovchilarniki emas. *temporary* (vaqtinchalik) — matnda vaqt haqida gap yo‘q.","*deliberate* (ataylab qilingan) — bashoratga to‘liq mos."],"answer":"B) deliberate"}},{"type":"example","heading":"Namuna 2: bog‘lovchi so‘z","example":{"problem":"Which choice completes the text with the most logical transition?","passage":"For decades, many city planners assumed that adding lanes to a crowded highway would permanently reduce traffic congestion. ______ studies of several widened highways found that traffic often returned to its earlier levels within a few years, as the extra road space encouraged more people to drive.","choices":["Similarly,","However,","For example,","Therefore,"],"solution":["1-gap: rejalashtiruvchilar yo‘l kengaytirilsa tirbandlik **doimiy kamayadi** deb hisoblashgan.","2-gap: tadqiqotlar tirbandlik **qaytib kelganini** ko‘rsatgan. Munosabat — zidlik: “lekin”.","*Similarly* (o‘xshashlik), *For example* (misol), *Therefore* (natija) — zidlikni bildirmaydi.","*However* — zidlikni bildiradi."],"answer":"B) However,"}},{"type":"note","heading":"Notanish so‘zlar: ingliz tili ona tilingiz bo‘lmasa","items":["**Har bir so‘zni bilish shart emas.** Savol odatda butun gapning mantig‘ini tekshiradi. Notanish so‘zni “X” deb qabul qilib, o‘qishda davom eting.","**Kontekstdan taxmin qiling:** oldingi va keyingi gapga, zidlik so‘zlariga (*however*, *but*, *unlike*), misolga (*for example*) va qo‘shimchaga (*moreover*) qarang. Ko‘pincha so‘zning ijobiy yoki salbiy ekanini bilish yetarli.","**So‘z tarkibidan foydalaning:** *un-*, *in-*, *dis-*, *mis-* — inkor yoki xato; *re-* — qayta; *pre-* — oldin; *-less* — -siz; *-ful* — -li; *-able* — mumkin bo‘lgan. Masalan, *unprecedented* — “avval misli ko‘rilmagan”.","**Notanish so‘zli variant:** bilgan uchta variantingiz aniq noto‘g‘ri bo‘lsa, notanish so‘zni tanlang — bu chiqarib tashlash orqali topilgan javob.","**Har bir gapni to‘liq tarjima qilmang.** Bu vaqt oladi. Asosiy fikrni 3–5 so‘z bilan ayting: “olim A ni da’vo qiladi, lekin B buni rad etadi”.","**Ilmiy atamalar va nomlar** (hayvon, kimyoviy modda, olim ismi) odatda javobga ta’sir qilmaydi — ularga qotib qolmang.","**Adabiy matnlar** eskiroq uslubda bo‘lishi mumkin: har bir so‘zdan ko‘ra qahramonning kayfiyati va voqealar rivojiga e’tibor bering."]},{"type":"note","heading":"Jadval va grafikli savollar","items":["Avval sarlavha, o‘q nomlari, birliklar va izohni (*legend*) o‘qing.","Keyin matndagi **da’voni** toping — savol aynan nimani ko‘rsatish kerakligini aytadi.","Variantdagi har bir raqamni jadval bilan solishtiring: kattaroq yoki kichikroq, qaysi yil, qaysi guruh.","To‘g‘ri variant ikki shartga javob beradi: ma’lumotga mos va da’voni qo‘llab-quvvatlaydi."]},{"type":"traps","heading":"Keng tarqalgan xatolar","items":["**Tashqi bilimga tayanish:** “men bilaman, bu to‘g‘ri” — lekin matnda yo‘q.","**Variantlarni matndan oldin o‘qish:** to‘rtta variant fikringizni chalg‘itadi. Avval bashorat qiling.","**So‘zning eng mashhur ma’nosini tanlash:** *Words in Context* savollarida so‘z ko‘pincha kamroq ma’lum ma’nosida ishlatiladi.","**Burilish so‘zini o‘tkazib yuborish:** *however* yoki *yet* dan keyingi gap ko‘pincha muallifning asl fikri.","**Eslatmalar savolida eslatmalarni to‘liq o‘qish:** vaqt ketadi. Maqsadni o‘qing va variantlarni unga solishtiring."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["O‘rtacha ≈71 soniya bir savolga. Grammatika va bog‘lovchi savollari ko‘pincha 30–50 soniyada yechiladi — tejalgan vaqt dalil, xulosa va ikki matnli savollarga qoladi.","Matnni ikki-uch marta o‘qimang: avval savol, keyin bir marta maqsadli o‘qish.","Bitta savolga 2 daqiqadan ko‘p ketmasin — ikki variant qolsa, birini tanlang, belgilang va o‘ting.","Eslatmalar (*rhetorical synthesis*) savollari maqsadni avval o‘qisangiz, tez yechiladi — ular uchun alohida vaqt zaxirasi kerak emas."]},{"type":"checklist","heading":"Javobni tanlashdan oldin","items":["Savol aynan nimani so‘raganini bilamanmi?","Variantlarga qarashdan oldin bashorat qildimmi?","Javobimni matndagi aniq so‘z yoki gap bilan tasdiqlay olamanmi?","Qolgan uchta variantning noto‘g‘riligi sababini ayta olamanmi?"]}]'::jsonb
from public.guides g where g.slug = 'reading-writing-strategy'
on conflict (guide_id, locale) do nothing;

-- rhetorical-synthesis
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'rhetorical-synthesis', 'skill', (select id from public.skills where code = 'rhetorical_synthesis'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'rhetorical_synthesis'), 29, 9, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Rhetorical Synthesis: qaydlardan maqsadga mos gap tanlash', 'Talaba yozib olgan qaydlar (notes) asosida berilgan maqsadni aynan bajaradigan gapni tanlash. Asosiy sir — avval maqsadni o‘qish va to‘g‘ri, lekin maqsaddan chetga chiqqan variantlarni chiqarib tashlash.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Bu savolda sizga talaba biror mavzuni o‘rganayotganda yozib olgan **qaydlar** (notes) ro‘yxati beriladi. Keyin talabaning **maqsadi** aytiladi va sizdan shu maqsadni eng yaxshi bajaradigan gapni tanlash so‘raladi.\n\nEng muhim tushuncha: **odatda barcha variantlar qaydlarga mos va faktik jihatdan to‘g‘ri.** Savol “qaysi gap to‘g‘ri?” emas, balki “qaysi gap **aynan shu maqsadni** bajaradi?” degan savol. Shuning uchun javob kaliti qaydlarda emas, **maqsad jumlasida**.\n\nKo‘p uchraydigan maqsad turlari va ular nimani talab qiladi:\n\n- **O‘xshashlikni ta’kidlash** (*emphasize a similarity*): gapda ikkala obyekt ham bo‘lishi va ularning umumiy jihati aytilishi kerak (*both, similarly, like*).\n- **Farqni ta’kidlash** (*emphasize a difference*): ikkala obyekt va ular orasidagi zidlik (*whereas, while, unlike, but*).\n- **Bilmaydigan auditoriyaga tanishtirish** (*introduce… to an audience unfamiliar with…*): obyekt nima ekanini tushuntiruvchi izoh bo‘lishi shart (masalan, *the saiga, an antelope of Central Asia, …*).\n- **Tanish auditoriya uchun** (*an audience already familiar with…*): uzun izoh shart emas, asosiy e’tibor yangi ma’lumotda.\n- **Tadqiqotni yoki uning natijasini taqdim etish** (*present the study''s aim / methodology / findings*): gapda aynan so‘ralgan qism — maqsad, usul yoki natija — bo‘lishi kerak.\n- **Umumlashma qilish yoki aniq misol keltirish** (*make a generalization / provide a specific example*): umumlashma — ko‘p holatga tegishli umumiy xulosa; misol — bitta aniq holat.\n\nTashqi bilimingizni ishlatmang: faqat qaydlardagi ma’lumot va maqsad muhim."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["Matn o‘rnida **nuqtali ro‘yxat** (bullet list) turadi va u shunday boshlanadi: *“While researching a topic, a student has taken the following notes:”*","Savol maqsadni aytadi: *“The student wants to emphasize a difference between the two…”*, *“…to introduce the novel to an audience unfamiliar with it”*, *“…to present the study''s main finding”*.","Savol oxiri deyarli har doim bir xil: *“Which choice most effectively uses relevant information from the notes to accomplish this goal?”*","Variantlar — to‘liq gaplar; ko‘pincha uzunligi bir xil va hammasi qaydlardagi faktlarni takrorlaydi."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Avval savolni (maqsadni) o‘qing — qaydlarni emas.** Maqsad jumlasi — sizning javob kalitingiz. Qaydlarni birinchi o‘qisangiz, ular ichidan “eng qiziq” faktni izlab, vaqt yo‘qotasiz.","**Maqsadni kichik nazorat ro‘yxatiga aylantiring.** Masalan, *difference between A and B* → (1) A bor, (2) B bor, (3) zidlik so‘zi yoki ma’nosi bor. *Unfamiliar audience* → obyekt nima ekani tushuntirilgan.","**Qaydlarni tez ko‘zdan kechiring** — faqat atamalarni va kim yoki nima haqida gap ketayotganini tushunish uchun. Ularni yodlash shart emas: variantlarni tekshirganda qaydlarga qaytasiz.","**Har bir variantni nazorat ro‘yxati bo‘yicha tekshiring.** Bitta bandni bajarmagan variantni — u qanchalik to‘g‘ri va chiroyli bo‘lmasin — o‘chiring. Bunda Option Eliminator vositasi qulay.","**Qolgan variantni qaydlar bilan solishtiring:** ma’lumot buzilmaganmi, munosabat (sabab, zidlik) qaydlardagidek berilganmi?","**Ikki variant qolsa** — qaysi biri maqsadni **asosiy fikr** sifatida aytadi? Qo‘shimcha ma’lumot zarar qilmaydi, lekin maqsadning bir qismi yetishmasa, variant noto‘g‘ri."]},{"type":"example","heading":"Namuna 1: o‘xshashlikni ta’kidlash","example":{"problem":"The student wants to emphasize a similarity between rammed earth and fired brick. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n\n- Rammed earth is a building technique in which damp soil is packed tightly between temporary wooden frames.\n- Fired brick is made by baking blocks of shaped clay in a kiln at high temperatures.\n- Producing rammed-earth walls requires almost no fuel.\n- Producing fired brick requires large amounts of fuel to heat the kiln.\n- Walls made of either material absorb heat during the day and release it at night, which helps keep indoor temperatures stable.","choices":["Rammed earth is a building technique in which damp soil is packed tightly between temporary wooden frames.","Unlike fired brick, which requires large amounts of fuel to produce, rammed earth requires almost no fuel.","Walls of rammed earth and walls of fired brick both help keep indoor temperatures stable by absorbing heat during the day and releasing it at night.","Fired brick is made by baking blocks of shaped clay in a kiln, a process that requires large amounts of fuel."],"solution":["Maqsadni nazorat ro‘yxatiga aylantiramiz: (1) rammed earth bor, (2) fired brick bor, (3) ularning **umumiy** jihati aytilgan.","Qaydlarda o‘xshashlik faqat oxirgi bandda: ikkala material ham kunduzi issiqlikni yutib, kechasi qaytaradi. Shu ma’lumotni ikkala material bilan birga beradigan yagona variant — **C**; *both* so‘zi ham o‘xshashlikka ishora qiladi.","**A** — faqat rammed earth haqida; fired brick umuman yo‘q, o‘xshashlik ham yo‘q.","**B** — ikkala material bor, lekin bu **farq** (*Unlike…*), o‘xshashlik emas. Faktik jihatdan to‘g‘ri, ammo boshqa maqsad uchun yozilgan — eng xavfli tuzoq.","**D** — faqat fired brick haqida, taqqoslash yo‘q."],"answer":"C"}},{"type":"example","heading":"Namuna 2: bilmaydigan auditoriya uchun tushuntirish","example":{"problem":"The student wants to explain the function of the saiga''s nose to an audience unfamiliar with the saiga. Which choice most effectively uses relevant information from the notes to accomplish this goal?","passage":"While researching a topic, a student has taken the following notes:\n\n- The saiga is an antelope that lives in the dry grasslands of Central Asia.\n- The saiga has a large, flexible nose that hangs over its mouth.\n- In summer, the saiga''s nose filters out dust kicked up by the herd.\n- In winter, the nose warms cold air before the air reaches the lungs.\n- Saiga herds can travel long distances between summer and winter pastures.","choices":["The saiga''s large nose filters out dust in summer and warms cold air in winter.","The saiga, an antelope of Central Asia''s dry grasslands, has a large, flexible nose that filters out dust in summer and warms cold air in winter.","The saiga is an antelope that lives in the dry grasslands of Central Asia and travels long distances between pastures.","Each year, saiga herds travel long distances between summer and winter pastures in the dry grasslands of Central Asia."],"solution":["Maqsadda ikki qism bor: (1) burunning **vazifasini** tushuntirish; (2) sayg‘oqni **bilmaydigan** auditoriya uchun yozish — ya’ni sayg‘oq nima ekanini ham aytish.","**B** ikkala shartni bajaradi: *an antelope of Central Asia''s dry grasslands* — tanishtiruvchi izoh, *filters out dust… warms cold air* — burunning vazifasi.","**A** — vazifani to‘liq tushuntiradi, lekin sayg‘oq nima ekanini aytmaydi. Sayg‘oqni bilmaydigan o‘quvchi “bu qushmi yoki hayvonmi?” deb o‘ylab qoladi. Maqsadning faqat yarmi bajarilgan — bu ham juda tipik tuzoq.","**C** — sayg‘oqni tanishtiradi, lekin burun haqida umuman gapirmaydi.","**D** — mavsumiy ko‘chish haqida; burunning vazifasi ham, tanishtiruv ham yo‘q."],"answer":"B"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Maqsadning har bir so‘zi muhim.** *Similarity* va *difference*, *the study''s method* va *the study''s finding*, *familiar* va *unfamiliar* — bitta so‘z javobni butunlay o‘zgartiradi.","**Auditoriya sharti:** *unfamiliar* bo‘lsa, obyekt izohlanishi shart (*X, a … that …,*). *Already familiar* bo‘lsa, uzun izoh shart emas — muhimi so‘ralgan yangi ma’lumot.","**Taqqoslash maqsadida ikkala obyekt ham bo‘lishi shart.** Bitta obyekt haqidagi gap, qanchalik to‘liq bo‘lmasin, taqqoslay olmaydi.","**Emphasize — ta’kidlash:** so‘ralgan fikr gapning asosiy qismi bo‘lishi kerak, ikkinchi darajali qismda “yashirinib” qolmasligi kerak.","**Qaydlardagi munosabatni buzmang:** qaydlarda sabab–oqibat yoki zidlik bo‘lmasa, uni o‘zidan qo‘shgan variant noto‘g‘ri.","**Tashqi bilim va shaxsiy fikr kerak emas.** “Qaysi fakt qiziqroq?” emas, “qaysi gap maqsadni bajaradi?” deb so‘rang."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**To‘g‘ri, lekin maqsaddan tashqari** — eng ko‘p uchraydigan tuzoq: qaydlarni aniq takrorlaydi, ammo boshqa maqsadga xizmat qiladi (o‘xshashlik so‘ralganda farq — Namuna 1 dagi B).","**Yarim bajarilgan maqsad:** ikki obyektdan bittasi yo‘q yoki mazmun bor, lekin auditoriya uchun izoh yo‘q (Namuna 2 dagi A).","**Teskari munosabat:** kerakli kalit so‘zlar bor, lekin farq o‘xshashlik sifatida (yoki aksincha) berilgan.","**Ko‘p faktli “to‘ldirilgan” variant:** qaydlardagi uch-to‘rt faktni sanab chiqadi, lekin maqsaddagi fikrni aniq aytmaydi. Uzunlik — sifat belgisi emas.","**Eng “chiroyli” yozilgan variant:** uslubi yaxshi, lekin maqsadga javob bermaydi. Bu savolda uslub emas, maqsadning bajarilishi baholanadi."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Bu savollarga **45–60 soniya** sarflang. Maqsadni birinchi o‘qish vaqtni ancha tejaydi: qaydlarning hammasini batafsil o‘qish shart emas.","Reading and Writing’da o‘rtacha vaqt savol boshiga taxminan 71 soniya. Qaydlar uzun ko‘rinsa ham, usulni bilsangiz bu savol tez yechiladi — shoshilmang, lekin tiqilib ham qolmang.","Maqsaddagi kalit so‘zlarni (*similarity, unfamiliar, finding*) **Highlights & Notes** vositasi bilan belgilab qo‘ying va har bir variantni ularga solishtiring.","**Option Eliminator** bilan maqsadni bajarmagan variantlarni o‘chiring — odatda ikki-uchtasi 20 soniya ichida tushib qoladi."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"notes","meaning":"qaydlar — talaba yozib olgan faktlar ro‘yxati"},{"term":"goal","meaning":"maqsad — savolda talaba nimani qilmoqchi ekani"},{"term":"emphasize","meaning":"ta’kidlamoq — fikrni gapning asosiy qismi sifatida ko‘rsatmoq"},{"term":"similarity / difference","meaning":"o‘xshashlik / farq"},{"term":"audience unfamiliar with…","meaning":"… ni bilmaydigan auditoriya — obyektni izohlash kerak"},{"term":"introduce","meaning":"tanishtirmoq — obyekt nima ekanini aytib, uni o‘quvchiga taqdim etmoq"},{"term":"finding(s)","meaning":"tadqiqot natijasi (natijalari)"},{"term":"aim","meaning":"maqsad — tadqiqot nimaga erishmoqchi bo‘lgani"},{"term":"generalization","meaning":"umumlashma — ko‘p holatga tegishli umumiy xulosa"},{"term":"accomplish this goal","meaning":"shu maqsadni bajarmoq"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Maqsad jumlasini birinchi o‘qib, uni nazorat ro‘yxatiga aylantirdimmi?","Tanlagan variantim maqsadning **har bir** qismini (ikkala obyekt, auditoriya, so‘ralgan ma’lumot) bajaradimi?","Variant qaydlardagi ma’lumotni buzmaganmi?","“To‘g‘ri, lekin boshqa maqsad uchun” degan variantga aldanmadimmi?"]}]'::jsonb
from public.guides g where g.slug = 'rhetorical-synthesis'
on conflict (guide_id, locale) do nothing;

