insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Test ilovasidagi vositalar va ulardan foydalanish', 'Digital SAT topshiriladigan Bluebook ilovasida qanday vositalar bor: taymer, ko‘rib chiqish uchun belgilash, variantlarni o‘chirish, belgilash va eslatmalar, savollar menyusi, Desmos kalkulyatori, formulalar ma’lumotnomasi va ko‘rsatmalar — har birini qachon va qanday ishlatish.', '[{"type":"concept","heading":"Bluebook nima va bu qo‘llanma nima haqida","body":"Digital SAT College Board’ning **Bluebook** ilovasida topshiriladi. Ilova va undagi vositalar College Board’ga tegishli; SAT MASTER u bilan bog‘liq emas. Quyida vositalar College Board’ning rasmiy tavsiflari asosida tushuntirilgan.\n\nVositalarni bilish — vaqt tejash demak. Test kuni “bu tugma nima qiladi?” deb o‘ylashga vaqt yo‘q: har bir vositadan foydalanish odati testdan oldin shakllangan bo‘lishi kerak. SAT MASTER sinov imtihonlarida asosiy vositalarning o‘xshashlari bor, Bluebook’ning o‘zida esa College Board’ning bepul rasmiy mashq testlari mavjud — haqiqiy interfeysga o‘rganish uchun ularni ham ishlab ko‘ring."},{"type":"note","heading":"Taymer (Testing Timer)","items":["Har bir modulda qancha vaqt qolganini ko‘rsatadi.","Taymerni **yashirish** mumkin. 5 daqiqa qolganda ilova ogohlantirish beradi.","Taymer nolga yetganda ilova sizni avtomatik ravishda keyingi qismga o‘tkazadi.","**Qanday ishlatish:** taymer sizni xavotirga solsa, yashirib qo‘ying va faqat nazorat nuqtalarida oching (masalan, Reading and Writing’da har 9 savoldan keyin). 5 daqiqalik ogohlantirish chiqqanda oxirgi 5 daqiqa rejimiga o‘ting: avval javobsiz savollar, keyin belgilanganlar."]},{"type":"note","heading":"Mark for Review (ko‘rib chiqish uchun belgilash)","items":["Xatcho‘p (bookmark) belgisi bilan qaytmoqchi bo‘lgan istalgan savolni belgilaysiz.","Belgilangan savollar savollar menyusida ko‘rinadi — ularga bir bosishda qaytasiz.","**Belgilash javob emas:** belgilangan savolga ham doim taxminiy javob qo‘ying. Vaqt tugasa, javobsiz belgilangan savol bo‘sh qoladi.","**Qanday ishlatish:** ikki o‘tishli usulning asosi. Uzun hisob yoki ikki variant orasidagi ikkilanish — belgilab, keyingisiga o‘ting."]},{"type":"note","heading":"Option Eliminator (variantlarni o‘chirish)","items":["Noto‘g‘ri deb hisoblagan javob variantlaringizni chizib qo‘yasiz. Fikringiz o‘zgarsa, bekor qilish mumkin.","O‘chirish javobni tanlash emas: javobni alohida belgilashingiz kerak.","**Qanday ishlatish:** Reading and Writing’da har bir variantni aniq sabab bilan o‘chiring (“matnda yo‘q”, “juda kuchli”, “teskari”). Belgilangan savolga qaytganingizda o‘chirilgan variantlarni qayta o‘qishingiz shart emas — faqat qolganlarini solishtirasiz."]},{"type":"note","heading":"Highlights & Notes (belgilash va eslatmalar)","items":["Savol matnining bir qismini rang bilan belgilash (highlight) yoki o‘zingizga eslatma qoldirish imkonini beradi.","**Qanday ishlatish:** Reading and Writing’da 1–2 ta kalit joyni belgilang: muallif da’vosi, *however* yoki *although* kabi burilish so‘zlari, savol so‘ragan aniq qism. Hamma narsani belgilasangiz, hech narsa ajralib turmaydi.","Eslatmaga qisqa xulosa yozing (masalan, “2-matn 1-matnga qarshi”) — belgilangan savolga qaytganingizda matnni qayta o‘qishga vaqt ketmaydi.","Math’dagi hisob-kitoblar uchun qoralama qog‘ozdan foydalaning."]},{"type":"note","heading":"Question Menu (savollar menyusi)","items":["Qaysi savollarni o‘tkazib yuborganingizni (javobsiz) va qaysilarini ko‘rib chiqish uchun belgilaganingizni ko‘rsatadi.","Undan modul ichidagi istalgan savolga to‘g‘ridan-to‘g‘ri o‘tish mumkin.","**Qanday ishlatish:** 2-o‘tishni shu menyudan boshlang; oxirgi 5 daqiqada esa avvalo javobsiz savol qolmaganini shu yerda tekshiring."]},{"type":"note","heading":"Calculator: Desmos","items":["Bluebook’da Desmos kalkulyatori o‘rnatilgan, u ikki rejimga ega: **grafik** va **ilmiy**. Math bo‘limi davomida ular orasida istalgan vaqtda almashish mumkin. Kalkulyator oynasini ekranning istalgan joyiga surish mumkin.","Kalkulyatordan **butun Math bo‘limi davomida** foydalanish mumkin, Reading and Writing bo‘limida esa yo‘q.","Ruxsat etilgan o‘z kalkulyatoringizni ham olib kelishingiz mumkin (faqat CAS funksiyasiz modellar; telefon ilovalari va internetga ulanadigan qurilmalar taqiqlangan). College Board testda qaysi kalkulyatordan foydalansangiz, mashqda ham o‘shandan foydalanishni maslahat beradi.","**Qanday ishlatish:** tenglamalar, sistemalar, kvadrat funksiyalar va jadval ma’lumotlari uchun grafik rejim juda tez. Batafsil usullar — “Desmos kalkulyatori: tezkor strategiyalar” qo‘llanmasida."]},{"type":"note","heading":"Reference Sheet (formulalar ma’lumotnomasi)","body":"Math bo‘limida ko‘p ishlatiladigan formulalar ro‘yxati test davomida ochiq. Unda quyidagilar bor:\n\n- Yuzalar: to‘g‘ri to‘rtburchak $A = \\ell w$, uchburchak $A = \\frac{1}{2}bh$, doira $A = \\pi r^2$; aylana uzunligi $C = 2\\pi r$.\n- Pifagor teoremasi: $c^2 = a^2 + b^2$.\n- Maxsus to‘g‘ri burchakli uchburchaklar: $45^\\circ$–$45^\\circ$–$90^\\circ$ (tomonlar $s$, $s$, $s\\sqrt{2}$) va $30^\\circ$–$60^\\circ$–$90^\\circ$ (tomonlar $x$, $x\\sqrt{3}$, $2x$).\n- Hajmlar: to‘g‘ri burchakli parallelepiped $V = \\ell wh$, silindr $V = \\pi r^2 h$, shar $V = \\frac{4}{3}\\pi r^3$, konus $V = \\frac{1}{3}\\pi r^2 h$, piramida $V = \\frac{1}{3}\\ell wh$.\n- Aylana yoyi $360^\\circ$, ya’ni $2\\pi$ radian; uchburchak burchaklari yig‘indisi $180^\\circ$.\n\n**Qanday ishlatish:** bu formulalarni baribir yod biling — ma’lumotnomani har safar ochish vaqt oladi. Undan faqat kam ishlatiladigan formulani (masalan, konus yoki shar hajmini) tekshirish uchun foydalaning."},{"type":"note","heading":"Directions (ko‘rsatmalar)","items":["Math bo‘limida ko‘rsatmalar ham test davomida ochiq.","Math ko‘rsatmalaridagi muhim shartlar (boshqacha aytilmagan bo‘lsa): barcha o‘zgaruvchilar va ifodalar haqiqiy sonlarni bildiradi; berilgan chizmalar masshtabda chizilgan; barcha shakllar tekislikda yotadi; $f$ funksiyaning aniqlanish sohasi — $f(x)$ haqiqiy son bo‘ladigan barcha $x$ lar.","Javobni o‘zingiz yozadigan savollarning kiritish qoidalari ham ko‘rsatmalarda bor — ularni testdan oldin “SPR: kiritish qoidalari” qo‘llanmasidan o‘rganib oling.","**Qanday ishlatish:** ko‘rsatmalarni testda o‘qishga vaqt sarflamang — ularni oldindan biling va faqat shubha tug‘ilganda oching."]},{"type":"note","heading":"Line Reader va Zoom","items":["**Line Reader** — o‘qiyotgan qatoringizga diqqatni jamlashga yordam beradi. Uzun yoki zich matnda qator adashib ketsa, foydali.","**Zoom** — noutbukda klaviatura tugmalari, planshetda esa ikki barmoq bilan savolning istalgan qismini kattalashtirish mumkin. Kichik grafik yoki jadval raqamlarini o‘qishda ishlating."]},{"type":"method","heading":"Vositalarni bitta savolda birga ishlatish","steps":["**Savolni o‘qing** va Reading and Writing’da kalit joyni belgilang (highlight).","**Variantlarni ko‘ring** va aniq noto‘g‘rilarini Option Eliminator bilan o‘chiring.","**Bitta qolsa** — tanlang va davom eting. **Ikkita qolsa** va 30–40 soniyada hal bo‘lmasa — ehtimolligini tanlang va **Mark for Review** bilan belgilang.","**Math’da** 5 soniyada qaror qiling: qo‘lda yechish tezmi yoki Desmos’dami? Formula esdan chiqsa — ma’lumotnomani oching.","**Modul oxirida** savollar menyusini oching: avval javobsiz savollar, keyin belgilanganlar."]},{"type":"note","heading":"SAT MASTER sinov imtihonlarida nima bor","items":["Taymer (yashirish mumkin), 5 va 1 daqiqa qolganda ogohlantirish.","Ko‘rib chiqish uchun belgilash va variantlarni o‘chirish.","Savollar navigatori va modul oxiridagi tekshirish sahifasi: javobsiz va belgilangan savollar soni ko‘rinadi.","Matematikada grafik kalkulyator va formulalar ma’lumotnomasi, har bir bo‘limda ko‘rsatmalar (jumladan, javobni yozish qoidalari).","Belgilash va eslatmalar (highlight) vositasi bizning sinov imtihonlarimizda hozircha yo‘q — buni Bluebook’dagi rasmiy mashq testlarida mashq qiling.","SAT MASTER interfeysi Bluebook’ning nusxasi emas, tugmalar joylashuvi farq qilishi mumkin. Maqsad — vositalardan foydalanish **odatini** shakllantirish."]},{"type":"checklist","heading":"Testdan oldin o‘zingizni tekshiring","items":["Taymerni yashirish va 5 daqiqalik ogohlantirishdan keyin nima qilishni bilamanmi?","Mark for Review va savollar menyusi bilan ikki o‘tishli usulni mashq qildimmi?","Option Eliminator’dan har bir savolda foydalanish odatim bormi?","Desmos’ning grafik va ilmiy rejimlarini sinab ko‘rdimmi?","Ma’lumotnomadagi formulalarni ochmasdan bilamanmi?"]}]'::jsonb
from public.guides g where g.slug = 'test-tools'
on conflict (guide_id, locale) do nothing;

-- text-structure-and-purpose
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'text-structure-and-purpose', 'skill', (select id from public.skills where code = 'text_structure_purpose'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'text_structure_purpose'), 21, 10, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Text Structure and Purpose: matn tuzilishi va maqsadi', 'Muallif matnni nima uchun yozgani, matn qanday tuzilgani va tagiga chizilgan jumla matnda qanday vazifa bajarishini aniqlash. Bu savollarda “matn nima deydi?” emas, “muallif nima qilyapti?” degan savolga javob izlaysiz.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Text Structure and Purpose savollari **Craft and Structure** domeniga kiradi. Ular matnning mazmunini emas, **tuzilishi va maqsadini** tekshiradi. Uch xil savol bor:\n\n- **Asosiy maqsad (main purpose):** muallif bu matnni nima uchun yozgan — biror narsani tasvirlash, tushuntirish, isbotlash yoki tanqid qilish uchunmi?\n- **Jumlaning vazifasi (function):** tagiga chizilgan jumla butun matnda qanday rol o‘ynaydi — misol keltiradimi, oldingi fikrga e’tiroz bildiradimi, natijani tushuntiradimi?\n- **Umumiy tuzilish (overall structure):** matn qanday ketma-ketlikda qurilgan — masalan, “avval keng tarqalgan fikr, keyin unga zid dalil”.\n\nMatnlar ilmiy, tarixiy, ijtimoiy mavzularda yoki badiiy (hikoya, she’r) bo‘lishi mumkin. Har qanday holatda ham o‘zingizga bitta savol berasiz: **“Muallif bu yerda nima qilyapti?”**"},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["*Which choice best states the main purpose of the text?* — butun matnning maqsadi.","*Which choice best describes the function of the underlined sentence in the text as a whole?* — matnda bitta jumla tagiga chizilgan bo‘ladi; uning **vazifasi** so‘ralmoqda.","*Which choice best describes the overall structure of the text?* — matn qismlarining ketma-ketligi.","Maqsad savollarida variantlar odatda fe’l bilan boshlanadi: *To explain…, To argue…, To describe…, To criticize…*. Vazifa va tuzilish savollarida esa *It provides an example…, It introduces…, The text presents a claim and then…* kabi tavsiflar bo‘ladi.","Badiiy matnda ham xuddi shu savollar beriladi; javob esa ko‘pincha qahramon xarakteri, kayfiyat yoki voqeadagi burilish bilan bog‘liq bo‘ladi."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Savolni o‘qing va turini aniqlang:** maqsad, vazifa yoki tuzilish. Vazifa savoli bo‘lsa, tagiga chizilgan jumlani darhol toping.","**Butun matnni o‘qing va har bir jumlaga qisqa “yorliq” qo‘ying** (o‘zbekcha, xayolan): “fon”, “keng tarqalgan fikr”, “da’vo”, “dalil yoki misol”, “e’tiroz”, “xulosa”. Bu matnning skeletini ko‘rsatadi.","**Maqsad savolida:** “Muallif bu matnni nima uchun yozdi?” degan savolga bitta fe’l va obyekt bilan javob bering: “olimning yangi topilmasini tushuntirish uchun”. Maqsad ko‘pincha matnning burilish nuqtasida (*however, but*) yoki oxirgi jumlada ko‘rinadi.","**Vazifa savolida:** jumlaning **o‘zi nima deyishini** emas, **oldingi va keyingi jumlalarga nisbatan nima qilishini** aniqlang. Masalan: “oldingi da’voga misol keltiradi” yoki “birinchi jumladagi fikrga qarshi dalil beradi”.","**Avval variantlardagi fe’lni tekshiring.** Muallif shunchaki tasvirlayaptimi (*describe*), biror pozitsiyani himoya qilyaptimi (*argue*) yoki tanqid qilyaptimi (*criticize*)? Fe’l noto‘g‘ri bo‘lsa, variantning qolgan qismi to‘g‘ri bo‘lsa ham u noto‘g‘ri.","**Keyin variantning har bir qismini matn bilan solishtiring.** Bitta so‘z ham matnga zid bo‘lsa yoki matnda bo‘lmasa, variantni o‘chiring. Yarim to‘g‘ri variant — noto‘g‘ri variant."]},{"type":"example","heading":"Namuna 1: tagiga chizilgan jumlaning vazifasi","example":{"problem":"Which choice best describes the function of the underlined sentence in the text as a whole?","passage":"Many people imagine deserts as empty places where very little can survive. Ecologist Dilnoza Karimova set out to test this image during two springs in a section of the Kyzylkum Desert. __In a single square kilometer, her team recorded dozens of species of flowering plants, along with lizards, beetles and nesting birds.__ Most of the plants, Karimova notes, sprout, bloom and release their seeds within a few weeks after the spring rains, so visitors who arrive in summer see only dry ground and conclude that the land is lifeless.","choices":["It explains why most visitors choose to arrive in the desert during the summer.","It introduces a claim that the rest of the text argues is mistaken.","It describes the method Karimova used to choose the location of her study.","It presents evidence that challenges the common view described in the first sentence."],"solution":["**Savol turi:** vazifa (function). Jumla nima deyishini emas, matnda **nima qilishini** aniqlaymiz.","**Jumlalarga yorliq:** 1-jumla — keng tarqalgan fikr (“cho‘l — bo‘m-bo‘sh joy”). 2-jumla — olima shu fikrni tekshirmoqchi. 3-jumla (tagiga chizilgan) — u topgan natija: o‘nlab o‘simlik turlari va hayvonlar. 4-jumla — nega odamlar cho‘lni jonsiz deb o‘ylashini tushuntiradi.","**Bashorat:** tagiga chizilgan jumla birinchi jumladagi fikrga **qarshi dalil** beradi.","**A** noto‘g‘ri: yozda keladiganlar haqida oxirgi jumla gapiradi, tagiga chizilgan jumla emas. Bundan tashqari, matn ular **nega** aynan yozda kelishini umuman tushuntirmaydi.","**B** noto‘g‘ri — teskari munosabat: matnning qolgan qismi bu natijani rad etmaydi, aksincha uni qo‘llab-quvvatlaydi va tushuntiradi.","**C** noto‘g‘ri: jumla tadqiqot joyi qanday tanlanganini emas, **natijani** — nima topilganini aytadi.","**D** — “birinchi jumladagi keng tarqalgan fikrni shubha ostiga qo‘yadigan dalil keltiradi”. Bashoratga to‘liq mos. ✓"],"answer":"D"}},{"type":"example","heading":"Namuna 2: matnning asosiy maqsadi","example":{"problem":"Which choice best states the main purpose of the text?","passage":"In many cities, old factory buildings stand empty for years before they are finally torn down. Architect Tomas Reyes argues that demolition is often the more wasteful choice. Tearing down a sturdy brick building, he points out, throws away the energy and materials already invested in it, and constructing a replacement releases large amounts of carbon. Reyes''s firm has turned three abandoned textile mills into apartments and libraries while keeping their original walls and beams. He urges city planners to treat old industrial buildings as resources to be reused rather than as problems to be removed.","choices":["To criticize city planners for allowing factory buildings to stand empty for many years","To present an architect''s argument for reusing old industrial buildings instead of demolishing them","To describe the steps Reyes''s firm followed to turn textile mills into apartments and libraries","To show that new buildings release more carbon than any other kind of construction project"],"solution":["**Savol turi:** butun matnning maqsadi. Bitta fe’l va obyekt bilan bashorat qilamiz.","**Skelet:** 1-jumla — fon (eski zavodlar bo‘sh turadi, keyin buziladi). 2-jumla — Reyesning asosiy da’vosi (buzish ko‘pincha isrofgarchilik). 3-jumla — da’voning sabablari. 4-jumla — misol (uchta to‘qimachilik fabrikasi). 5-jumla — chaqiriq (shahar rejalashtiruvchilariga murojaat).","**Bashorat:** “arxitektorning eski binolarni buzish o‘rniga qayta ishlatish kerakligi haqidagi fikrini bayon qilish”.","**B** — bashoratga aynan mos: fe’l (*present an argument*) ham, mazmun ham to‘g‘ri. ✓","**A** noto‘g‘ri: binolarning bo‘sh turishi faqat fon sifatida tilga olingan. Reyes rejalashtiruvchilarni tanqid qilmaydi, balki ularga taklif beradi; uning asosiy e’tirozi binolarni **buzishga** qarshi.","**C** noto‘g‘ri — **juda tor** (*too narrow*): fabrikalar faqat bitta misol, matnda esa qayta qurish bosqichlari umuman tasvirlanmagan.","**D** noto‘g‘ri — **haddan tashqari kuchli** (*extreme*): matn yangi bino qurish ko‘p uglerod chiqarishini aytadi, lekin “boshqa har qanday qurilishdan ko‘proq” degan taqqoslash yo‘q. Bu matnning maqsadi ham emas."],"answer":"B"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Fe’l — eng muhim so‘z.** *Describe* — neytral tasvir, *explain* — nima uchun yoki qanday ekanini tushuntirish, *argue* — pozitsiyani himoya qilish, *criticize* — salbiy baho, *celebrate / praise* — ijobiy baho. Muallifning ohangi neytral bo‘lsa, *criticize* yoki *celebrate* bilan boshlangan variant deyarli har doim noto‘g‘ri.","**“Nima deydi?” emas, “nima qiladi?”** Vazifa savolida tagiga chizilgan jumlaning mazmunini qayta aytgan variant ko‘pincha tuzoq. To‘g‘ri javob jumlaning **boshqa jumlalarga munosabatini** tasvirlaydi: *provides an example of…*, *offers a reason for…*, *presents a contrast to…*.","**Burilish nuqtasini toping.** Ko‘p matnlar “ko‘pchilik shunday o‘ylaydi… **however** tadqiqot boshqacha ko‘rsatdi” tuzilishida bo‘ladi. Muallifning asl maqsadi odatda burilishdan keyin keladi.","**Badiiy matnlarda** maqsad ko‘pincha qahramonni yoki kayfiyatni ko‘rsatish bo‘ladi: *to portray a character''s growing doubt*, *to convey the speaker''s admiration*. Qahramonning his-tuyg‘usini bildiruvchi so‘zlarga (*hesitated, smiled, frowned*) e’tibor bering.","**Ingliz tili bo‘yicha maslahat:** har bir jumlaning faqat egasi va kesimini (kim? nima qildi?) toping va unga o‘zbekcha yorliq qo‘ying. Notanish so‘zni “X” deb qabul qilib o‘qishda davom eting — jumlaning **vazifasini** aniqlash uchun ko‘pincha har bir so‘z shart emas. Signal so‘zlar yorliqni tez topishga yordam beradi: *for example, for instance* → misol; *however, yet, in contrast* → burilish yoki e’tiroz; *as a result, therefore* → natija; *some argue, it was long assumed* → keyin rad etilishi mumkin bo‘lgan fikr.","**Savol so‘zlarini tez “tarjima qiling”:** *purpose* — maqsad (nima uchun yozilgan), *function* — vazifa (matnda qanday rol o‘ynaydi), *structure* — tuzilish (qismlar qanday ketma-ketlikda), *as a whole* — butun matn doirasida."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Mazmuni to‘g‘ri, fe’li noto‘g‘ri:** muallif faqat tasvirlagan narsani “isbotlash” yoki “tanqid qilish” deb ko‘rsatgan variant (2-namunadagi A).","**Juda tor (too narrow):** matndagi bitta tafsilot yoki misolni butun matnning maqsadi qilib ko‘rsatish (2-namunadagi C).","**Juda keng (too broad):** *To discuss modern architecture* kabi umumiy variant — mavzu to‘g‘ri, lekin matn aynan nima qilayotganini aytmaydi.","**Yarim to‘g‘ri variant:** birinchi yarmi matnga mos, ikkinchi yarmi esa matnda yo‘q yoki unga zid. Variantning **har bir so‘zini** tekshiring.","**Teskari munosabat:** jumla oldingi fikrni qo‘llab-quvvatlaydi, variant esa “rad etadi” deydi yoki aksincha (1-namunadagi B).","**Noto‘g‘ri joyga ishora:** variant matnda haqiqatan bor narsani tasvirlaydi, lekin u boshqa jumlaga tegishli (1-namunadagi A).","**Haddan tashqari kuchli so‘zlar:** *proves, always, any other, completely* — matnda bunday kuchli da’vo bo‘lmasa, variant noto‘g‘ri (2-namunadagi D)."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Reading and Writing’da bir savolga o‘rtacha **71 soniya** bor (har modulda 27 savol, 32 daqiqa).","Text Structure and Purpose savollariga **60–75 soniya** yetarli. Matnni bir marta diqqat bilan o‘qib, yorliqlarni xayolan qo‘ysangiz, variantlarni tez tekshirasiz; matnni uch marta qayta o‘qish esa vaqtni yeydi.","Variantlar uzun bo‘lsa, avval faqat **fe’llarni** solishtiring: ko‘pincha bir-ikki variant shu bosqichdayoq tushib qoladi.","Ikki variant orasida 20 soniyadan ortiq ikkilanib qolsangiz, matndan aynan qaysi so‘z har biriga zid ekanini qidiring. Topa olmasangiz, yaxshiroq ko‘ringanini tanlang, **Mark for Review** bilan belgilang va keyinroq qayting."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"main purpose","meaning":"asosiy maqsad: muallif matnni nima uchun yozgan"},{"term":"function","meaning":"vazifa: jumla yoki qism matnda qanday rol o‘ynaydi"},{"term":"underlined sentence","meaning":"tagiga chizilgan jumla"},{"term":"overall structure","meaning":"umumiy tuzilish: matn qismlarining ketma-ketligi"},{"term":"as a whole","meaning":"butunligicha, butun matn doirasida"},{"term":"illustrate","meaning":"misol bilan ko‘rsatmoq"},{"term":"elaborate on","meaning":"batafsilroq tushuntirmoq, fikrni kengaytirmoq"},{"term":"qualify (a claim)","meaning":"da’voni cheklamoq — uni rad etmasdan, shart yoki istisno qo‘shmoq"},{"term":"acknowledge","meaning":"(qarshi fikrni yoki kamchilikni) tan olmoq"},{"term":"challenge / refute","meaning":"shubha ostiga qo‘ymoq / to‘liq rad etmoq"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Savol maqsad, vazifa yoki tuzilish haqidami — aniqladimmi?","Variantdagi fe’l muallifning haqiqiy ohangiga (neytral, ijobiy, salbiy) mosmi?","Vazifa savolida jumlaning mazmunini emas, boshqa jumlalarga munosabatini tanladimmi?","Variantning har bir qismi matnda bormi?"]}]'::jsonb
from public.guides g where g.slug = 'text-structure-and-purpose'
on conflict (guide_id, locale) do nothing;

-- time-management-and-guessing
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
