on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'O‘tish so‘zlari (Transitions)', 'Ikki gap yoki fikr orasidagi mantiqiy munosabatni aniqlab, uni to‘g‘ri ifodalaydigan o‘tish so‘zini tanlash: zidlik, sabab–oqibat, qo‘shimcha, misol, ketma-ketlik va boshqalar. Asosiy usul — variantlarga qarashdan oldin munosabatni o‘zingiz aytib olish.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Transitions savoli ikki fikr orasidagi **mantiqiy munosabatni** tekshiradi. Bo‘sh joy odatda gap boshida (ba’zan nuqtali verguldan keyin) turadi va siz shu munosabatni to‘g‘ri ifodalaydigan so‘z yoki iborani tanlaysiz. Grammatik jihatdan barcha variantlar to‘g‘ri — farq faqat **ma’noda**.\n\nO‘tish so‘zlari oilalari (o‘zbekcha ma’nosi — inglizcha so‘zlar — qachon ishlatiladi):\n\n- **Zidlik (contrast) — “lekin, biroq”:** *however, nevertheless, nonetheless, by contrast, in contrast, on the other hand, conversely, still, yet, even so*. Ikkinchi fikr birinchisiga qarshi yoki kutilmagan natija.\n- **Almashtirish — “aksincha, uning o‘rniga”:** *instead, rather*. Birinchi gapda inkor (A emas), ikkinchisida uning o‘rnida nima bo‘lgani (B).\n- **Tan olish (concession) — “to‘g‘ri, … (lekin)”:** *admittedly, granted, of course*. Qarshi fikrni qisman tan olish.\n- **Sabab–oqibat (cause and effect) — “shuning uchun, natijada”:** *therefore, thus, consequently, as a result, hence, accordingly, for this reason*. Ikkinchi fikr birinchisining natijasi.\n- **Qo‘shimcha (addition) — “bundan tashqari”:** *moreover, furthermore, in addition, additionally, also, besides*. Xuddi shu yo‘nalishdagi yangi fikr.\n- **O‘xshashlik (similarity) — “xuddi shunday”:** *similarly, likewise, in the same way*. Ikki xil obyektda bir xil holat.\n- **Misol (example) — “masalan”:** *for example, for instance*. Ikkinchi gap birinchi gapdagi umumiy fikrning aniq holati.\n- **Aniqlashtirish va kuchaytirish — “aniqrog‘i, aslida”:** *specifically, in particular, in other words, that is, in fact, indeed*. Ikkinchi gap birinchisini aniqlashtiradi, boshqacha aytadi yoki kuchaytiradi.\n- **Ketma-ketlik va vaqt (sequence) — “keyin, so‘ngra”:** *first, then, next, subsequently, afterward, later, finally, meanwhile, previously*. Voqealarning vaqt bo‘yicha tartibi.\n- **Xulosa (summary) — “qisqasi, umuman olganda”:** *in short, in sum, ultimately, overall*. Oldingi fikrlarni yakunlaydi."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["Savol so‘zi: *“Which choice completes the text with the most logical transition?”*","To‘rtala variant ham o‘tish so‘zi yoki iborasi: *However, / Therefore, / For example, / Similarly,*","Bo‘sh joy oxirgi (yoki ikkinchi) gapning boshida turadi; ba’zan esa nuqtali verguldan keyin, gap o‘rtasida.","Variantlar grammatik jihatdan bir xil ishlaydi (hammasi vergul bilan tugaydi) — demak bu grammatika emas, mantiq savoli."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Variantlarga hali qaramang.** Avval munosabatni o‘zingiz aniqlang, aks holda “ilmiy” eshitiladigan so‘z sizni chalg‘itadi.","**Bo‘sh joydan oldingi gapni va bo‘sh joy turgan gapni o‘qing.** Matn qisqa bo‘lsa — hammasini. Munosabat ko‘pincha aynan shu ikki gap orasida bo‘ladi, lekin ba’zan birinchi gapdagi umumiy fikr bilan bog‘liq.","**Munosabatni o‘zbekcha bitta so‘z bilan ayting:** “lekin”, “shuning uchun”, “masalan”, “bundan tashqari”, “keyin”, “xuddi shunday”, “aksincha”. Bu sizning bashoratingiz.","**Bashoratga mos oilani toping** (yuqoridagi ro‘yxatdan) va variantlar ichidan shu oiladagi so‘zni tanlang.","**Bir oiladan ikki variant bo‘lsa — nozik farqni tekshiring:** *however* (oddiy zidlik) va *instead* (inkordan keyin almashtirish); *for example* (misol) va *in other words* (boshqacha aytish); *moreover* (yangi qo‘shimcha) va *similarly* (o‘xshash holat).","**Bir xil ma’noli ikki variant bo‘lsa** (masalan, *therefore* va *thus*), to‘g‘ri javob faqat bitta bo‘lgani uchun ikkalasi ham javob emas.","**Tanlovingizni joyiga qo‘yib, ikki gapni birga o‘qing:** “A. Shuning uchun, B.” — mantiqan to‘g‘ri eshitiladimi?"]},{"type":"example","heading":"Namuna 1: zidlik","example":{"problem":"Which choice completes the text with the most logical transition?","passage":"Many home gardeners assume that tomato plants need full sun all day to produce a large harvest. ______ in a two-year trial, horticulturist Sevara Aliyeva found that plants shaded during the hottest afternoon hours produced slightly more fruit than plants left in full sun.","choices":["However,","Similarly,","For example,","Therefore,"],"solution":["Birinchi gap — keng tarqalgan **taxmin**: pomidorga kun bo‘yi to‘liq quyosh kerak. Ikkinchi gap — tajriba natijasi: tushdan keyin soyada qolgan o‘simliklar **ko‘proq** hosil bergan. Natija taxminga zid.","O‘zbekcha bashorat: “**lekin**”. Zidlik oilasidan — *However* — **A**.","**B** (*Similarly*) — o‘xshash holatni bildiradi, lekin tajriba natijasi taxminni tasdiqlamaydi, aksincha rad etadi.","**C** (*For example*) — ikkinchi gap birinchi gapdagi fikrning misoli bo‘lishi kerak edi; tajriba esa bu fikrga misol emas, unga qarshi dalil.","**D** (*Therefore*) — tajriba natijasi bog‘bonlarning taxminidan **kelib chiqmaydi**; sabab–oqibat munosabati yo‘q."],"answer":"A) However,"}},{"type":"example","heading":"Namuna 2: sabab va oqibat","example":{"problem":"Which choice completes the text with the most logical transition?","passage":"When a honeybee finds a rich patch of flowers, it returns to the hive and performs a movement known as the waggle dance. The angle of the dance shows the direction of the flowers relative to the sun, and the length of the dance shows how far away they are. ______ other bees from the hive can locate the flowers without searching the area at random.","choices":["Nevertheless,","For instance,","As a result,","Previously,"],"solution":["Oldingi gaplar: raqs gullarning **yo‘nalishi** va **masofasini** ko‘rsatadi. Oxirgi gap: boshqa asalarilar gullarni tasodifiy qidirmasdan topa oladi.","Oxirgi gap — raqs bergan ma’lumotning **natijasi**. Bashorat: “shuning uchun / natijada”. To‘g‘ri javob — *As a result* — **C**.","**A** (*Nevertheless*) — “shunga qaramay” degan zidlikni bildiradi, go‘yo raqsdan keyin gullarni topish qiyin bo‘lishi kutilgandek. Bunday zidlik matnda yo‘q.","**B** (*For instance*) — oxirgi gap oldingi fikrga misol emas, balki undan kelib chiqqan oqibat.","**D** (*Previously*) — vaqt munosabati (“ilgari”); asalarilar gullarni raqsdan **keyin** topadi, oldin emas."],"answer":"C) As a result,"}},{"type":"example","heading":"Namuna 3: umumiy fikr va misol","example":{"problem":"Which choice completes the text with the most logical transition?","passage":"Some desert plants survive long droughts by storing water in their thick tissues. ______ the pleated stems of certain cactus species can expand like an accordion, allowing the plants to absorb large amounts of water after a rare rainstorm.","choices":["Consequently,","For instance,","However,","Instead,"],"solution":["Birinchi gap — **umumiy** fikr: ba’zi cho‘l o‘simliklari suvni qalin to‘qimalarida saqlaydi. Ikkinchi gap — **aniq** holat: ba’zi kaktus turlarining poyasi kengayib, ko‘p suv yig‘a oladi.","Umumiy fikrdan keyin uning aniq namunasi kelyapti — bashorat: “masalan”. To‘g‘ri javob — *For instance* — **B**.","**A** (*Consequently*) — kaktus poyasining kengayishi birinchi gapdagi fikrning **natijasi** emas, balki uning namunasi; sabab–oqibat yo‘q.","**C** (*However*) — ikkinchi gap birinchisiga zid emas, aksincha uni tasdiqlaydi.","**D** (*Instead*) — birinchi gapda inkor qilingan biror narsa yo‘q, shuning uchun “uning o‘rniga” ma’nosi mos kelmaydi."],"answer":"B) For instance,"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Munosabat so‘zlar orasida emas, fikrlar orasida.** Bir xil so‘zning takrorlanishi hali o‘xshashlik degani emas; gaplarning **ma’nosini** solishtiring.","**However va instead farqi:** *instead* birinchi gapda biror narsa inkor qilinganda yoki rad etilganda ishlatiladi: *The builders did not use concrete. Instead, they used rammed earth.* (beton o‘rniga).","**Moreover va similarly farqi:** *moreover* — xuddi shu fikrni qo‘llab-quvvatlovchi **yangi** dalil; *similarly* — **boshqa obyektda** kuzatilgan xuddi shunday holat.","**For example va specifically farqi:** *for example* — umumiy fikrning bitta namunasi; *specifically* — oldingi fikrni aniqroq qilib, tafsilotini beradi.","**In fact va indeed** oldingi fikrni kuchaytiradi yoki undan ham kuchliroq dalil keltiradi: *The plan was popular. In fact, nearly every resident voted for it.*","**Meanwhile** — “shu vaqtning o‘zida” (ko‘pincha boshqa joyda yoki boshqa obyekt bilan); oddiy “keyin” ma’nosida emas.","**Ba’zan munosabat uzoqroq gap bilan bo‘ladi:** matnda uch-to‘rt gap bo‘lsa, bo‘sh joyli gap birinchi gapdagi asosiy fikrga javob berishi mumkin. Qisqa matnni butunlay o‘qing."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Yo‘nalishni adashtirish:** zidlik kerak bo‘lgan joyda qo‘shimcha (*moreover*) yoki aksincha. Avval “fikr shu yo‘nalishda davom etyaptimi yoki burilyaptimi?” deb so‘rang.","**Therefore’ni haddan tashqari ishlatish:** ikkinchi gap birinchisidan **keyin** kelgani — hali undan **kelib chiqqani** degani emas.","**“Akademik” eshitiladigan so‘zlar:** *Furthermore, Consequently, Nevertheless* jiddiy ko‘rinadi, lekin to‘g‘ri javob har doim ham murakkab so‘z emas.","**Misol va natijani adashtirish:** aniq holat umumiy fikrning **misolimi** yoki **oqibatimi** — Namuna 2 va 3 ni solishtiring.","**Noto‘g‘ri gap bilan bog‘lash:** bo‘sh joyli gapni faqat oldingi gapning oxirgi so‘zlari bilan solishtirib, butun fikrni e’tiborsiz qoldirish."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Transitions — Reading and Writing’dagi eng tez savollardan biri: **25–45 soniya**. O‘rtacha vaqt savol boshiga taxminan 71 soniya, shuning uchun bu yerda tejalgan vaqtni uzun matnli savollarga qoldiring.","Variantlarga qarashdan oldin bashorat qilish odati vaqtni tejaydi: bashorat aniq bo‘lsa, javob bir qarashda topiladi.","Ikki variant orasida qolsangiz, ikkala gapni o‘zbekchaga o‘girib, har bir variant bilan o‘qib ko‘ring: “… Shuning uchun …” yoki “… Masalan …” — qaysi biri mantiqli?","60 soniyadan oshib ketsa, eng ehtimolli variantni belgilang, savolni **Mark for Review** bilan belgilab qo‘ying va keyinroq qayting."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"transition","meaning":"o‘tish so‘zi — ikki fikrni mantiqan bog‘laydigan so‘z yoki ibora"},{"term":"logical relationship","meaning":"mantiqiy munosabat — fikrlar bir-biriga qanday bog‘langani"},{"term":"contrast","meaning":"zidlik: *however, by contrast, nevertheless*"},{"term":"cause and effect","meaning":"sabab–oqibat: *therefore, as a result, consequently*"},{"term":"addition","meaning":"qo‘shimcha: *moreover, furthermore, in addition*"},{"term":"example","meaning":"misol: *for example, for instance*"},{"term":"sequence","meaning":"ketma-ketlik: *then, subsequently, finally*"},{"term":"concession","meaning":"tan olish: *admittedly, granted*"},{"term":"similarity","meaning":"o‘xshashlik: *similarly, likewise*"},{"term":"most logical","meaning":"eng mantiqiy — grammatika emas, ma’no bo‘yicha tanlang"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Variantlarga qarashdan oldin munosabatni o‘zbekcha bitta so‘z bilan aytdimmi?","Ikkinchi fikr birinchisiga qarshimi, uni davom ettiradimi yoki undan kelib chiqadimi?","Tanlagan so‘zim shu oiladanmi va nozik farqlar (*instead, similarly, specifically*) mos keladimi?","Tanlovni joyiga qo‘yib, ikki gapni birga o‘qidimmi?"]}]'::jsonb
from public.guides g where g.slug = 'transitions'
on conflict (guide_id, locale) do nothing;

-- two-variable-data-scatterplots
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'two-variable-data-scatterplots', 'skill', (select id from public.skills where code = 'two_variable_data'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'two_variable_data'), 12, 11, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Ikki o‘zgaruvchili ma’lumotlar: modellar va scatterplot’lar', 'Scatterplot’ni o‘qish, line of best fit (eng mos to‘g‘ri chiziq) yordamida bashorat qilish, qiyalik va boshlang‘ich qiymatni kontekstda talqin qilish hamda chiziqli va eksponensial modellarni bir-biridan ajratish.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Bu ko‘nikma ikki miqdor o‘rtasidagi bog‘liqlikni ma’lumotlar orqali tahlil qilishni tekshiradi. Asosiy vosita — **scatterplot**: har bir nuqta bitta kuzatuv, $x$ — bir miqdor, $y$ — ikkinchisi.\n\n- **Bog‘liqlik turi:** $x$ oshganda $y$ ham oshsa — musbat (positive), kamaysa — manfiy (negative) bog‘liqlik. Nuqtalar chiziqqa yaqin to‘plangan bo‘lsa — kuchli (strong), sochilib ketgan bo‘lsa — kuchsiz (weak) bog‘liqlik.\n- **Line of best fit:** $y = mx + b$ ko‘rinishidagi model. Qiyalik $m$ — $x$ bir birlikka oshganda $y$ ning **bashorat qilingan** (predicted) o‘zgarishi; $b$ — $x = 0$ bo‘lgandagi bashorat qilingan qiymat.\n- **Bashorat va haqiqiy qiymat:** $x$ ni model tenglamasiga qo‘yib, $y$ ning taxminiy qiymatini topasiz. Haqiqiy (actual) qiymat — nuqtaning o‘zi. Ularning farqi $\\text{actual} - \\text{predicted}$ (residual): nuqta chiziqdan yuqorida bo‘lsa, haqiqiy qiymat bashoratdan katta.\n- **Model turlari:** chiziqli $y = mx + b$ — har teng qadamda **bir xil son qo‘shiladi**; eksponensial $y = a \\cdot b^x$ — har teng qadamda **bir xil songa ko‘paytiriladi** ($b > 1$ — o‘sish, $0 < b < 1$ — kamayish; $b = 1 + r$, bunda $r$ — har qadamdagi foiz o‘zgarish); kvadratik — nuqtalar parabola shaklida joylashadi.\n\nModel faqat taxmin beradi, shuning uchun to‘g‘ri talqinlarda doim *“predicted”*, *“estimated”*, *“approximately”* kabi so‘zlar bo‘ladi."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["*“The scatterplot shows …”*, *“A line of best fit is shown.”* — grafik bilan ishlash: avval o‘qlar va masshtabni o‘qing.","*“Based on the line of best fit, what is the predicted …?”* — tenglamaga $x$ ni qo‘ying yoki qiymatni chiziqdan o‘qing (nuqtadan emas!).","*“Which of the following is the best interpretation of the slope in this context?”* — qiyalik yoki boshlang‘ich qiymatni so‘z bilan talqin qilish.","*“Which equation best models the data?”*, *“Which type of model is most appropriate?”* — chiziqli, eksponensial yoki kvadratik modelni tanlash.","*“How many data points are above the line of best fit?”*, *“By how much does the actual … exceed the predicted …?”* — haqiqiy va bashorat qiymat farqi."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**O‘qlarni o‘qing.** Har bir o‘q qaysi miqdor, qaysi birlikda (*“in thousands”*, *“in millions”*) va bitta katak nechaga teng? O‘q 0 dan boshlanmasligi ham mumkin.","**Bog‘liqlik shaklini aniqlang:** nuqtalar to‘g‘ri chiziq bo‘ylabmi yoki egri (tobora tezlashib o‘sadigan yoki sekinlashib kamayadigan) chiziq bo‘ylabmi? Yo‘nalish musbatmi yoki manfiy?","**Variantlarni ishora bo‘yicha saralang.** Manfiy bog‘liqlikda qiyalik manfiy bo‘lishi kerak; chiziq $y$ o‘qini qayerda kesishiga qarab $b$ ni baholang. Ko‘pincha shu ikki tekshiruv ikki-uch variantni yo‘qqa chiqaradi.","**Qiyalikni ikki nuqtadan hisoblang.** Chiziq ustidagi, kataklar kesishmasiga aniq tushgan ikki nuqtani tanlang (ma’lumot nuqtalarini emas): $m = \\frac{y_2 - y_1}{x_2 - x_1}$.","**Talqin qolipidan foydalaning:** “$x$ har bir birlikka oshganda, $y$ taxminan $m$ birlikka oshadi (kamayadi)”; boshlang‘ich qiymat uchun: “$x = 0$ bo‘lganda $y$ ning bashorat qilingan qiymati $b$”.","**Jadval berilgan bo‘lsa, ayirma va nisbatlarni tekshiring:** ketma-ket $y$ lar ayirmasi o‘zgarmas — chiziqli model; nisbati o‘zgarmas — eksponensial model."]},{"type":"example","heading":"Namuna 1: qiyalikni talqin qilish","example":{"problem":"A café manager recorded the number of hours the café was open, $x$, and the number of cups of coffee sold, $y$, on each of 20 days. A scatterplot of the data has a line of best fit with equation $y = 38x + 15$. Which of the following is the best interpretation of 38 in this context?","choices":["The café sells about 38 cups of coffee each day.","For each additional hour the café is open, the predicted number of cups of coffee sold increases by about 38.","For each additional cup of coffee sold, the café is predicted to be open about 38 more hours.","The predicted number of cups of coffee sold when the café is open for 0 hours is 38."],"solution":["$y = 38x + 15$ da 38 — $x$ oldidagi koeffitsiyent, ya’ni **qiyalik**: $x$ (soat) 1 ga oshganda $y$ (stakanlar) qanchaga o‘zgarishini ko‘rsatadi.","Birligi — “stakan/soat”: har bir qo‘shimcha soatga taxminan 38 stakan. Bu B variant.","Nega A xato: 38 — kunlik savdo emas; kunlik bashorat $38x + 15$ bo‘lib, ochiq soatlar soniga bog‘liq.","Nega C xato: yo‘nalish teskari. Qiyalik $y$ ning $x$ ga nisbatan o‘zgarishini bildiradi, aksincha emas.","Nega D xato: $x = 0$ dagi bashorat — boshlang‘ich qiymat, ya’ni 15, 38 emas. Bu qiyalik bilan $y$-kesishmani adashtirish tuzog‘i.","Tekshiruv: $x = 8$ da $y = 319$, $x = 9$ da $y = 357$; farq $357 - 319 = 38$ ✓."],"answer":"B"}},{"type":"example","heading":"Namuna 2: haqiqiy va bashorat qiymat (javobni o‘zingiz yozasiz)","example":{"problem":"A scatterplot shows the age $x$, in years, and the price $y$, in thousands of dollars, of 12 used cars of the same model. The line of best fit for the data is $y = -1.8x + 24.5$. One of the cars in the data set is 5 years old and has a price of 17.2 thousand dollars. By how many thousand dollars does the actual price of this car exceed the price predicted by the line of best fit?","solution":["Bashorat qilingan narx — tenglamaga $x = 5$ ni qo‘yamiz: $y = -1.8 \\cdot 5 + 24.5 = -9 + 24.5 = 15.5$ ming dollar.","Haqiqiy narx — nuqtaning o‘zi: 17.2 ming dollar.","Farq: $\\text{actual} - \\text{predicted} = 17.2 - 15.5 = 1.7$.","E’tibor bering: $y$ **ming dollarda** o‘lchanadi va javob ham ming dollarda so‘ralgan, shuning uchun 1700 emas, **1.7** kiritiladi.","Tekshiruv: farq musbat — demak bu mashinaning nuqtasi chiziqdan **yuqorida** joylashgan, bu “exceed” so‘ziga mos ✓."],"answer":"1.7"}},{"type":"example","heading":"Namuna 3: chiziqli yoki eksponensial model","example":{"problem":"The list shows the number of bacteria, $y$, in a sample $t$ hours after an experiment began.\n\n- $t = 0$: 500\n- $t = 1$: 600\n- $t = 2$: 720\n- $t = 3$: 864\n\nWhich equation best models the data?","choices":["$y = 500 + 100t$","$y = 500(1.2)^t$","$y = 500(0.2)^t$","$y = 600(1.2)^t$"],"solution":["Ayirmalarni tekshiramiz: $600 - 500 = 100$, $720 - 600 = 120$, $864 - 720 = 144$ — o‘zgarmas emas, demak model chiziqli emas. A variant faqat birinchi ayirmaga mos keladi.","Nisbatlarni tekshiramiz: $\\frac{600}{500} = \\frac{720}{600} = \\frac{864}{720} = 1.2$ — o‘zgarmas. Demak model eksponensial, ko‘paytuvchi $b = 1.2$ (har soatda $20\\%$ o‘sish).","Boshlang‘ich qiymat — $t = 0$ dagi qiymat: $a = 500$. Model: $y = 500(1.2)^t$.","Nega C xato: $0.2$ — o‘sish **foizi** ($20\\%$), ko‘paytuvchi esa $1 + 0.2 = 1.2$; asosi $0.2$ bo‘lsa, miqdor keskin kamayardi. Nega D xato: 600 — $t = 1$ dagi qiymat, boshlang‘ich qiymat emas.","Tekshiruv: $t = 3$ da $500 \\cdot 1.2^3 = 500 \\cdot 1.728 = 864$ ✓."],"answer":"B) $y = 500(1.2)^t$"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Masshtab va birlik:** bitta katak 1 emas, 2, 5 yoki 10 ga teng bo‘lishi mumkin; *“in thousands”* bo‘lsa, javobni ham shu birlikda bering.","**Bashorat chiziqdan, haqiqiy qiymat nuqtadan olinadi.** *“According to the line of best fit”* — faqat tenglama yoki chiziq.","**Residual ishorasi:** $\\text{actual} - \\text{predicted}$. Nuqta chiziqdan yuqorida — musbat, pastda — manfiy.","**Boshlang‘ich qiymat har doim ham ma’noli emas:** $x = 0$ ma’lumotlar oralig‘idan ancha uzoqda bo‘lsa (masalan, 0 yoshli daraxtning balandligi), $b$ ni talqin qilishda ehtiyot bo‘ling.","**Ma’lumot oralig‘idan tashqaridagi bashorat (extrapolation) ishonchsiz:** 1–10 soatlik ma’lumot 50 soat uchun yaxshi bashorat bermaydi.","**Bog‘liqlik sabab emas:** kuchli bog‘liqlik $x$ ning $y$ ga sabab bo‘lishini isbotlamaydi."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Qiyalikni teskari talqin qilish:** “har bir stakan uchun 38 soat” (namuna 1, C).","**Qiyalik va boshlang‘ich qiymatni almashtirish** (namuna 1, D).","**Bashorat o‘rniga ma’lumot nuqtasini o‘qish** yoki, aksincha, haqiqiy qiymat so‘ralganda chiziqdan o‘qish.","**O‘sish foizi va ko‘paytuvchini adashtirish:** $0.2$ va $1.2$ (namuna 3, C); $15\\%$ kamayishda ko‘paytuvchi $0.85$, $0.15$ emas.","**Faqat birinchi ikki qiymatga qarab model tanlash** (namuna 3, A) — kamida uchta qiymatni tekshiring.","**Masshtabni noto‘g‘ri o‘qish:** har bir katakni 1 deb hisoblash."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Talqin savoli: **30–50 soniya**; grafikdan qiyalik yoki bashorat topish: **60–90 soniya**.","Ma’lumotlar jadval ko‘rinishida berilsa, Desmos’da jadval yarating ($x_1$ va $y_1$ ustunlari) va $y_1 \\sim mx_1 + b$ deb yozing — Desmos eng mos to‘g‘ri chiziqning $m$ va $b$ qiymatlarini hisoblab beradi. Eksponensial model uchun: $y_1 \\sim ab^{x_1}$.","Variantlardagi tenglamalarni Desmos’da nuqtalar ustiga chizing — qaysi chiziq nuqtalarga eng yaxshi tushishini darhol ko‘rasiz.","Talqin savollarida hisob kerak emas: variantlarni “qaysi son — qiyalik, qaysi — boshlang‘ich qiymat, yo‘nalish to‘g‘rimi” degan uch savol bilan saralang."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"scatterplot","meaning":"nuqtali grafik: har bir nuqta bitta kuzatuvning ($x$, $y$) juftligi"},{"term":"line of best fit","meaning":"ma’lumotlarga eng mos keluvchi to‘g‘ri chiziq (trend chizig‘i)"},{"term":"predicted / estimated","meaning":"bashorat qilingan / taxminiy qiymat — modeldan olinadi"},{"term":"actual / observed","meaning":"haqiqiy / kuzatilgan qiymat — ma’lumot nuqtasi"},{"term":"slope","meaning":"qiyalik: $x$ 1 ga oshganda $y$ ning o‘zgarishi"},{"term":"y-intercept","meaning":"$y$ o‘qi bilan kesishish nuqtasi: $x = 0$ dagi qiymat"},{"term":"positive / negative association","meaning":"musbat / manfiy bog‘liqlik"},{"term":"linear / exponential model","meaning":"chiziqli (har qadamda bir xil son qo‘shiladi) / eksponensial (har qadamda bir xil songa ko‘paytiriladi) model"},{"term":"growth factor / growth rate","meaning":"o‘sish ko‘paytuvchisi ($1.2$) / o‘sish sur’ati ($20\\%$)"},{"term":"best models","meaning":"ma’lumotlarni eng yaxshi ifodalaydi"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["O‘qlarning masshtabi va birliklarini (thousands, millions) to‘g‘ri o‘qidimmi?","Bashorat chiziq yoki tenglamadan, haqiqiy qiymat esa nuqtadan olindimi?","Talqinda $x$ va $y$ ning roli (qaysi biri qaysiga bog‘liq) to‘g‘rimi?","Model turini (chiziqli yoki eksponensial) kamida uchta qiymat bilan tekshirdimmi?"]}]'::jsonb
from public.guides g where g.slug = 'two-variable-data-scatterplots'
on conflict (guide_id, locale) do nothing;

-- words-in-context
insert into public.guides (slug, kind, skill_id, subject_id, position, reading_minutes, status)
select 'words-in-context', 'skill', (select id from public.skills where code = 'words_in_context'), (select d.subject_id from public.skills s join public.domains d on d.id = s.domain_id where s.code = 'words_in_context'), 20, 10, 'draft'
on conflict (slug) do nothing;
insert into public.guide_contents (guide_id, locale, title, summary, sections)
select g.id, 'uz', 'Words in Context: so‘zning matndagi ma’nosi', 'Matndagi bo‘sh joyga eng mantiqiy va aniq so‘zni tanlash yoki berilgan so‘zning aynan shu matndagi ma’nosini topish. Bu savollarda lug‘at bilimi muhim, lekin asosiy kalit — so‘z ma’nosini atrofidagi jumlalardan oldindan “bashorat qilish”.', '[{"type":"concept","heading":"Bu ko‘nikma nimani tekshiradi","body":"Words in Context savollari Reading and Writing bo‘limidagi to‘rt domendan biri — **Craft and Structure** ga kiradi va ikki ko‘rinishda keladi:\n\n- **Bo‘sh joyni to‘ldirish:** matnda bitta bo‘sh joy bor, siz unga eng mantiqiy va eng aniq so‘z yoki iborani tanlaysiz. Bu eng ko‘p uchraydigan shakl.\n- **So‘zning ma’nosi:** savol matndagi bitta so‘zni keltiradi va u **aynan shu matnda** qaysi ma’noda ishlatilganini so‘raydi.\n\nIkkala holatda ham SAT lug‘atni yodlaganingizni emas, so‘zni **kontekst ichida** tushunishingizni tekshiradi. Ingliz tilida bitta so‘zning bir nechta ma’nosi bo‘lishi mumkin; to‘g‘ri javob — faqat shu matn mantiqiga mos keladigan ma’no. College Board bu savollarda kamdan-kam ishlatiladigan “ekzotik” so‘zlarni emas, akademik matnlarda ko‘p uchraydigan (*high-utility*) so‘z va iboralarni tanlaydi.\n\nMatnlar qisqa (25–150 so‘z) va har bir matnga faqat bitta savol beriladi. Demak, matnni boshidan oxirigacha o‘qishga doim vaqtingiz bor — faqat bo‘sh joyli jumlani o‘qib javob berish eng katta xato."},{"type":"recognize","heading":"Savolni qanday tanib olasiz","items":["*Which choice completes the text with the most logical and precise word or phrase?* — matnda bo‘sh joy bor, variantlarda to‘rtta so‘z yoki ibora. Bu Words in Context’ning asosiy savoli.","*As used in the text, what does the word “…” most nearly mean?* — matndagi tayyor so‘zning aynan shu kontekstdagi ma’nosi so‘ralmoqda.","To‘rtala variant odatda **bir xil so‘z turkumida** bo‘ladi (hammasi fe’l yoki hammasi sifat) va grammatik jihatdan jumlaga bir xil mos tushadi. Demak, tanlov grammatikaga emas, **ma’noga** bog‘liq.","Variantlar ko‘pincha bir-biriga yaqin ma’noli bo‘ladi: farq so‘zning **kuchida** (*slightly* yoki *dramatically*), **ohangida** (ijobiy yoki salbiy) yoki **aniq ma’nosida**.","Farqlang: agar variantlar bir so‘zning turli shakllari (*is / are*, *its / their*) yoki tinish belgilari bo‘lsa — bu grammatika (Standard English Conventions) savoli. Agar variantlar *However, Therefore, For example* kabi bog‘lovchilar bo‘lsa — bu transitions savoli."]},{"type":"method","heading":"Ishlash usuli: qadamma-qadam","steps":["**Avval savolni o‘qing.** Bo‘sh joy savolimi yoki *most nearly mean* savolimi — shunga qarab matnning qaysi joyiga ko‘proq e’tibor berishni bilasiz.","**Matnni to‘liq o‘qing, variantlarga hali qaramang.** Bo‘sh joydan oldingi va keyingi jumlalar ayniqsa muhim: ma’noning kaliti ko‘pincha aynan shu yerda. Variantlarni oldin ko‘rsangiz, ular fikringizni chalg‘itadi.","**Kalit dalil va signal so‘zlarni toping.** Matn bo‘sh joy haqida nima deydi? Qarama-qarshilik (*however, but, although, yet*), davom (*and, also, similarly*), sabab-natija (*because, therefore, thus*) yoki tushuntirish (ikki nuqta “:” va tire “—” dan keyingi qism) belgilari qaysi yo‘nalishni ko‘rsatyapti?","**O‘z so‘zingiz bilan bashorat qiling.** Bo‘sh joyga o‘zbekcha yoki oddiy inglizcha so‘z qo‘ying: “shubha ostiga qo‘ydi”, “kichik”, *good / bad*. Bashorat chiroyli bo‘lishi shart emas — **yo‘nalishi** (ijobiy yoki salbiy, ko‘p yoki kam, qo‘llaydi yoki qarshi) to‘g‘ri bo‘lsa yetarli.","**Variantlarni bashoratingiz bilan solishtirib, chiqarib tashlang.** Avval yo‘nalishi teskari variantlarni, keyin juda kuchli yoki juda kuchsiz variantlarni o‘chiring. Bluebook’dagi **Option Eliminator** bilan ularning ustidan chizib qo‘ying.","**Qolgan variantni jumlaga qo‘yib, matnni yana bir marta o‘qing.** Jumla tabiiy eshitilishi va matndagi **har bir** tafsilotga mos kelishi kerak. Ikki variant qolsa, qaysi biri matndagi dalilga aniqroq mos kelishini tekshiring — SAT eng aniq (*most precise*) so‘zni so‘raydi."]},{"type":"example","heading":"Namuna 1: qarama-qarshilik signali","example":{"problem":"Which choice completes the text with the most logical and precise word or phrase?","passage":"For decades, many historians assumed that merchants on the Silk Road relied almost entirely on camel caravans to move their goods. A recent study of merchant letters preserved in a desert archive, however, ______ that view: the letters describe donkeys, horses and even river boats carrying silk, paper and spices over long stretches of the journey. The researchers argue that trade routes were far more varied than earlier accounts suggested.","choices":["reinforces","overlooks","complicates","summarizes"],"solution":["**Signal so‘z:** *however* (“biroq”). Demak, yangi tadqiqot tarixchilarning eski fikriga **qarshi** yo‘nalishda nimadir qilmoqda.","**Dalil:** ikki nuqtadan keyingi qism bo‘sh joyni tushuntiradi — xatlarda tuyadan tashqari eshak, ot va daryo qayiqlari ham tilga olingan. Oxirgi jumla ham savdo yo‘llari “ancha xilma-xil” bo‘lganini aytadi.","**Bashorat:** tadqiqot eski fikrni “shubha ostiga qo‘yadi”, manzara u qadar oddiy emasligini ko‘rsatadi.","**C) complicates** — “murakkablashtiradi, oddiy emasligini ko‘rsatadi”. Tadqiqot tuyalar ishlatilmagan demayapti, faqat yuk tashish faqat tuyalardan iborat bo‘lmaganini ko‘rsatyapti. Yo‘nalishi ham, kuchi ham aniq mos. ✓","**A) reinforces** (“mustahkamlaydi”) — teskari ma’no. *However* signalini e’tiborsiz qoldirgan o‘quvchi aynan shuni tanlaydi.","**B) overlooks** (“e’tiborsiz qoldiradi”) — tadqiqot eski fikrni chetlab o‘tmayapti, aksincha unga bevosita javob bermoqda.","**D) summarizes** (“qisqacha bayon qiladi”) — xatlar eski fikrni takrorlamaydi, balki unga zid yangi ma’lumot beradi."],"answer":"C) complicates"}},{"type":"example","heading":"Namuna 2: ko‘p ma’noli so‘z (most nearly mean)","example":{"problem":"As used in the text, what does the word “address” most nearly mean?","passage":"When the city council received hundreds of complaints about crowded buses, it formed a small committee to address the problem. Instead of simply buying more vehicles, the committee studied ridership data, interviewed drivers and redesigned three bus routes that overlapped with one another. Within a year, average waiting times at bus stops had fallen by nearly a third, and the council decided to use the committee''s approach for other city services.","choices":["speak to","deal with","send to","locate"],"solution":["**Savol:** *most nearly mean* — *address* so‘zining **shu matndagi** ma’nosi kerak. Bu so‘zning lug‘atda bir nechta ma’nosi bor: “manzil”, “nutq so‘zlamoq, murojaat qilmoq”, “xatga manzil yozmoq” va “muammo bilan shug‘ullanmoq”.","**Kontekst:** qo‘mita muammoni *address* qilish uchun tuzilgan, keyin esa ma’lumotlarni o‘rgangan, haydovchilardan so‘ragan va yo‘nalishlarni qayta tuzgan. Bularning hammasi — muammoni **hal qilish** uchun qilingan ishlar.","**Bashorat:** “hal qilish, muammo ustida ishlash”.","**B) deal with** — “hal qilmoq, shug‘ullanmoq”. Matndagi barcha harakatlarga mos. ✓","**A) speak to** — “nutq so‘zlamoq, murojaat qilmoq”. *Address an audience* iborasida shu ma’no bor, lekin qo‘mita muammoga nutq so‘zlamaydi.","**C) send to** — xat yoki posilkaga manzil yozish ma’nosi; matnda hech narsa jo‘natilmayapti.","**D) locate** — “joylashuvini topmoq”. *Address* ot sifatida “manzil” degani, lekin matnda muammo qayerdaligini topish haqida gap yo‘q.","**Xulosa:** *most nearly mean* savollarida so‘zning eng mashhur ma’nosi (bu yerda “manzil” yoki “nutq”) ko‘pincha tuzoq bo‘ladi."],"answer":"B) deal with"}},{"type":"example","heading":"Namuna 3: so‘zning kuchi (darajasi)","example":{"problem":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Engineers tested a new coating designed to keep solar panels free of dust in dry regions, where dirty panels can lose much of their power. After six months, panels with the coating generated about 2 percent more electricity than identical panels without it. The team described the improvement as ______: clearly measurable and worth further study, but too small on its own to justify the coating''s high price for most solar farms.","choices":["negligible","modest","remarkable","temporary"],"solution":["**Signal:** ikki nuqtadan keyingi qism bo‘sh joyning tayyor ta’rifi: “aniq o‘lchanadigan va o‘rganishga arziydi, **lekin** yolg‘iz o‘zi qimmat narxni oqlash uchun juda kichik”.","**Bashorat:** “kichik, lekin haqiqiy” — ya’ni na juda katta, na umuman ahamiyatsiz.","**B) modest** — “uncha katta bo‘lmagan, kamtarona”. Ham “haqiqiy”, ham “kichik” degan ikki shartga mos. ✓","**A) negligible** — “e’tiborga arzimaydigan darajada kichik”. Yo‘nalishi to‘g‘ri (kichik), lekin **juda kuchli**: matn natijani *clearly measurable and worth further study* deydi, ya’ni u e’tiborga arziydi.","**C) remarkable** — “ajoyib, diqqatga sazovor”. Teskari yo‘nalish: matn yaxshilanish kichik ekanini ta’kidlaydi.","**D) temporary** — “vaqtinchalik”. Natija qancha davom etishi haqida matnda ma’lumot yo‘q; bu variant boshqa savolga javob beradi."],"answer":"B) modest"}},{"type":"watch_out","heading":"Nimaga e’tibor berish kerak","items":["**Oddiy so‘z — kutilmagan ma’no.** *address, sound, check, credit, figure, novel* kabi tanish so‘zlar SAT’da ko‘pincha ikkinchi darajali ma’nosida keladi: *a sound argument* — “asosli dalil”, *a novel method* — “yangi, original usul”. Lug‘atdagi birinchi ma’noga emas, kontekstga ishoning.","**“Logical” va “precise” — ikki alohida shart.** Mantiqiy so‘z matn yo‘nalishiga mos keladi; aniq so‘z esa darajasi, ohangi va mavzusi bo‘yicha ham mos keladi. Ikki variant “taxminan to‘g‘ri” ko‘rinsa, matndagi dalilga **aniqroq** mos kelganini tanlang.","**Ikki nuqta (:) va tire (—) — tayyor ta’rif.** Ulardan keyingi qism ko‘pincha bo‘sh joyni tushuntiradi. Shu qismni o‘qimasdan javob bermang.","**Bilmagan so‘z chiqsa:** uni darhol tashlamang va darhol tanlamang ham. Avval bilgan variantlaringizni tekshiring: agar ularning hammasi aniq noto‘g‘ri bo‘lsa, notanish so‘zni tanlang. So‘z qismlari ham yordam beradi: *un-, dis-, mis-* — inkor yoki xato, *re-* — qayta, *-less* — “-siz”. Matndagi notanish so‘zni esa “X” deb qabul qilib o‘qishda davom eting — ko‘pincha ma’noni tushunish uchun u shart emas.","**Signal so‘zlarni o‘zbekchaga “tarjima qiling”:** *however, yet, but, although, despite* → “biroq” (yo‘nalish o‘zgaradi); *moreover, also, similarly, likewise* → “shuningdek” (yo‘nalish davom etadi); *therefore, thus, as a result, consequently* → “shuning uchun” (natija).","**Savolni bir zumda tushuning:** *most logical and precise word or phrase* → “mantiqan to‘g‘ri va eng aniq so‘z”; *as used in the text … most nearly mean* → “shu matnda nimani anglatadi”. Butun matnni so‘zma-so‘z tarjima qilishga urinmang: kim? nima qildi? qaysi yo‘nalishda? — shu uch savolga javob bashorat uchun yetarli.","**Lug‘atni so‘z birikmasi bilan o‘rganing.** Alohida so‘z emas, ibora yodlang: *undermine a claim* (da’voni zaiflashtirmoq), *bolster support* (qo‘llab-quvvatlashni kuchaytirmoq), *a tentative conclusion* (dastlabki, ehtiyotkor xulosa). SAT so‘zlarni aynan shunday birikmalarda ishlatadi."]},{"type":"traps","heading":"Keng tarqalgan xatolar (tuzoq variantlar)","items":["**Teskari ma’no:** signal so‘zni (*however*, *although*) e’tiborsiz qoldirsangiz, aynan teskari variantni tanlaysiz (1-namunadagi *reinforces*).","**Juda kuchli yoki juda kuchsiz:** yo‘nalishi to‘g‘ri, lekin darajasi noto‘g‘ri so‘z (3-namunadagi *negligible*). *Destroy* o‘rniga *weaken*, *always* o‘rniga *often* kerak bo‘lishi mumkin.","**Mashhur ma’no tuzog‘i:** *most nearly mean* savolida so‘zning eng ko‘p ishlatiladigan ma’nosi deyarli har doim variantlar orasida bo‘ladi va ko‘pincha noto‘g‘ri (2-namunadagi *locate* va *speak to*).","**Mavzuga mos, lekin mantiqqa mos emas:** variant matn mavzusiga yaqin so‘z (savdo haqidagi matnda *trade*, *exchange* kabi), lekin jumladagi mantiqiy vazifani bajarmaydi.","**“Aqlli” ko‘rinadigan so‘z:** qiyin va kam uchraydigan so‘z o‘z-o‘zidan to‘g‘ri emas. To‘g‘ri javob ko‘pincha oddiy so‘z bo‘ladi.","**Faqat bitta jumlaga mos:** variant bo‘sh joyli jumlaga to‘g‘ri tushadi, lekin keyingi jumla bilan ziddiyatga kiradi. Doim butun matnni hisobga oling."]},{"type":"time","heading":"Vaqt bo‘yicha maslahat","items":["Reading and Writing bo‘limi ikki moduldan iborat: har birida **27 ta savol** va **32 daqiqa** (jami 54 savol, 64 daqiqa). Bu bir savolga o‘rtacha **71 soniya** degani.","Words in Context matnlari qisqa, shuning uchun bu savollarga **40–60 soniya** sarflashga harakat qiling. Tejangan vaqt uzunroq savollarga (ikki matnli, grafikli, inference) qoladi.","Modulda o‘xshash savollar birga guruhlangan va osondan qiyinga qarab joylashtirilgan. Guruh oxiridagi savolga ko‘proq vaqt ketishi normal.","So‘zni bilmasangiz, ikki daqiqa o‘ylash ham uni eslatmaydi. Bilgan variantlaringizni tekshirib chiqarib tashlang, qolganidan birini tanlang va **Mark for Review** bilan belgilab keyingi savolga o‘ting.","Savolni hech qachon bo‘sh qoldirmang: College Board’ning o‘zi ko‘pchilik o‘quvchilar uchun bo‘sh qoldirgandan ko‘ra taxmin qilish yaxshiroq ekanini, ayniqsa bir-ikki variantni chiqarib tashlay olsangiz, ta’kidlaydi."]},{"type":"terms","heading":"Muhim inglizcha atamalar","terms":[{"term":"most logical and precise","meaning":"eng mantiqiy va eng aniq: so‘z ham matn yo‘nalishiga, ham uning darajasi va ohangiga mos bo‘lishi kerak"},{"term":"as used in the text","meaning":"matnda ishlatilgan ma’noda — lug‘atdagi umumiy ma’no emas"},{"term":"most nearly mean","meaning":"ma’nosi eng yaqin (to‘liq sinonim bo‘lishi shart emas)"},{"term":"context","meaning":"kontekst: so‘z atrofidagi jumlalar va matnning umumiy mazmuni"},{"term":"connotation","meaning":"so‘zning qo‘shimcha ohangi: ijobiy (*confident*), salbiy (*arrogant*) yoki neytral"},{"term":"phrase","meaning":"ibora, so‘z birikmasi (*rule out*, *account for*)"},{"term":"complicate (a view)","meaning":"(fikrni) murakkablashtirmoq — u to‘liq to‘g‘ri yoki oddiy emasligini ko‘rsatmoq"},{"term":"undermine","meaning":"zaiflashtirmoq, asosini yemirmoq — SAT matnlarida juda ko‘p uchraydi"},{"term":"underscore","meaning":"ta’kidlamoq, alohida urg‘u bermoq"},{"term":"novel (adjective)","meaning":"yangi, original — *novel* faqat “roman” degani emas"}]},{"type":"checklist","heading":"Javobni tanlashdan oldin tekshiring","items":["Variantlarga qarashdan oldin o‘z bashoratimni qildimmi?","Tanlagan so‘zim signal so‘zlar (*however*, *because*, ikki nuqta) ko‘rsatgan yo‘nalishga mosmi?","So‘zning kuchi va ohangi matndagi dalilga mosmi — ortiqcha kuchli yoki kuchsiz emasmi?","So‘zni bo‘sh joyga qo‘yib, butun matnni qayta o‘qidimmi?"]}]'::jsonb
from public.guides g where g.slug = 'words-in-context'
